import socket
import time
import signal
import sys
import logging
from threading import Thread, Lock

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

try:
    from gpiozero import DigitalOutputDevice, PWMOutputDevice
    from gpiozero.pins.mock import MockFactory
    _GPIOZERO_AVAILABLE = True
except ImportError:
    _GPIOZERO_AVAILABLE = False
    MockFactory = None

try:
    from adafruit_mcp3008 import MCP3008
    from adafruit_mcp3008 import MCP3008_CS
    _MCP3008_AVAILABLE = True
except ImportError:
    _MCP3008_AVAILABLE = False

SPI_CLK = 11
SPI_MOSI = 10
SPI_MISO = 9
SPI_CS_1 = 8
SPI_CS_2 = 7

MOTOR_A_FORWARD = 27
MOTOR_A_BACKWARD = 22
MOTOR_B_CLOCKWISE = 24
MOTOR_B_COUNTERCLOCKWISE = 25
MOTOR_A_ENABLE = 17
MOTOR_B_ENABLE = 23

DEFAULT_THRESHOLD = 30.0
DEFAULT_DURATION = 5.0
HEALTH_CHECK_INTERVAL = 60
NUM_READINGS = 5
READING_DELAY = 0.02

_running = True
_lock = Lock()


class MotorController:
    def __init__(self, forward_pin, backward_pin, enable_pin, pwm_frequency=1000):
        self.forward = None
        self.backward = None
        self.enable = None
        self.pwm_frequency = pwm_frequency
        self._initialized = False
        try:
            if _GPIOZERO_AVAILABLE:
                self.forward = DigitalOutputDevice(forward_pin)
                self.backward = DigitalOutputDevice(backward_pin)
                self.enable = PWMOutputDevice(enable_pin, frequency=pwm_frequency)
            else:
                logging.warning("gpiozero not available; motor controller will be passive.")
            self._initialized = True
        except Exception as e:
            logging.error(f"MotorController init failed: {e}")

    def set_speed(self, speed):
        if not self._initialized:
            return
        try:
            speed = max(0.0, min(100.0, speed))
            if speed > 0:
                self.forward.on()
                self.backward.off()
            else:
                self.forward.off()
                self.backward.off()
            if self.enable:
                self.enable.value = speed / 100.0
        except Exception as e:
            logging.error(f"set_speed error: {e}")

    def stop(self):
        if not self._initialized:
            return
        try:
            if self.forward:
                self.forward.off()
            if self.backward:
                self.backward.off()
            if self.enable:
                self.enable.value = 0.0
        except Exception as e:
            logging.error(f"stop error: {e}")

    def cleanup(self):
        self.stop()
        for dev in (self.forward, self.backward, self.enable):
            if dev:
                try:
                    dev.close()
                except Exception:
                    pass


class MoistureSensor:
    def __init__(self, channel, cs_pin):
        self.channel = channel
        self.cs_pin = cs_pin
        self.spi = None
        self.mcp = None
        self._initialized = False
        try:
            if _MCP3008_AVAILABLE:
                import busio
                import digitalio
                from board import D11, D10, D9, D8
                pins = {8: D8, 7: D7, 10: D10, 9: D9, 11: D11}
                clk = pins[SPI_CLK]
                mosi = pins[SPI_MOSI]
                miso = pins[SPI_MISO]
                cs = digitalio.DigitalInOut(pins[cs_pin])
                cs.direction = digitalio.Direction.OUTPUT
                cs.value = True
                spi = busio.SPI(clock=clk, MOSI=mosi, MISO=miso)
                self.mcp = MCP3008(spi, cs)
                self._initialized = True
            else:
                logging.warning("adafruit_mcp3008 not available; sensor will return -1.")
        except Exception as e:
            logging.error(f"MoistureSensor init failed: {e}")

    def read_moisture_level(self):
        if not self._initialized:
            return -1.0
        try:
            if self.mcp is None:
                return -1.0
            raw = self.mcp.read(self.channel)
            if raw is None:
                return -1.0
            return float(raw) / 1023.0 * 100.0
        except Exception as e:
            logging.error(f"read_moisture_level error: {e}")
            return -1.0

    def cleanup(self):
        if self.mcp:
            try:
                self.mcp.close()
            except Exception:
                pass


def read_sensor_data(sensor1, sensor2):
    readings1 = []
    readings2 = []
    for _ in range(NUM_READINGS):
        r1 = sensor1.read_moisture_level()
        r2 = sensor2.read_moisture_level()
        if r1 >= 0:
            readings1.append(r1)
        if r2 >= 0:
            readings2.append(r2)
        time.sleep(READING_DELAY)
    avg1 = sum(readings1) / len(readings1) if readings1 else -1.0
    avg2 = sum(readings2) / len(readings2) if readings2 else -1.0
    return avg1, avg2


def water_plant(motor, duration):
    try:
        motor.set_speed(50.0)
        time.sleep(duration)
        motor.stop()
    except Exception as e:
        logging.error(f"water_plant error: {e}")


def handle_client(client_socket, sensor1, sensor2, motor_a, motor_b, threshold, duration):
    try:
        data = client_socket.recv(1024).decode().strip()
        if not data:
            return
        parts = data.split()
        cmd = parts[0].upper()
        if cmd == "WATER_PLANT_1":
            Thread(target=water_plant, args=(motor_a, duration), daemon=True).start()
        elif cmd == "WATER_PLANT_2":
            Thread(target=water_plant, args=(motor_b, duration), daemon=True).start()
        elif cmd == "GET_SENSOR_DATA":
            avg1, avg2 = read_sensor_data(sensor1, sensor2)
            resp = f"Sensor 1: {avg1:.2f}%, Sensor 2: {avg2:.2f}%\n"
            client_socket.sendall(resp.encode())
        elif cmd == "SET_THRESHOLD":
            global threshold
            if len(parts) > 1:
                try:
                    threshold = float(parts[1])
                    client_socket.sendall(b"Threshold set.\n")
                except ValueError:
                    client_socket.sendall(b"Invalid threshold value.\n")
            else:
                client_socket.sendall(b"Threshold value required.\n")
        elif cmd == "SET_WATERING_DURATION":
            global duration
            if len(parts) > 1:
                try:
                    duration = float(parts[1])
                    client_socket.sendall(b"Duration set.\n")
                except ValueError:
                    client_socket.sendall(b"Invalid duration value.\n")
            else:
                client_socket.sendall(b"Duration value required.\n")
        else:
            client_socket.sendall(b"Unknown command.\n")
    except Exception as e:
        logging.error(f"handle_client error: {e}")
    finally:
        try:
            client_socket.close()
        except Exception:
            pass


def health_check(sensor1, sensor2, motor_a, motor_b):
    while _running:
        try:
            avg1, avg2 = read_sensor_data(sensor1, sensor2)
            if avg1 < 0 or avg2 < 0:
                logging.warning("Sensor read failed in health check.")
            if avg1 < 20:
                logging.warning("Plant 1 needs watering!")
            if avg2 < 20:
                logging.warning("Plant 2 needs watering!")
        except Exception as e:
            logging.error(f"Health check error: {e}")
        time.sleep(HEALTH_CHECK_INTERVAL)


def signal_handler(sig, frame):
    global _running
    _running = False


def main():
    global threshold, duration
    threshold = DEFAULT_THRESHOLD
    duration = DEFAULT_DURATION
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    sensor1 = MoistureSensor(0, SPI_CS_1)
    sensor2 = MoistureSensor(1, SPI_CS_2)
    motor_a = MotorController(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, MOTOR_A_ENABLE)
    motor_b = MotorController(MOTOR_B_CLOCKWISE, MOTOR_B_COUNTERCLOCKWISE, MOTOR_B_ENABLE)
    health_thread = Thread(target=health_check, args=(sensor1, sensor2, motor_a, motor_b), daemon=True)
    health_thread.start()
    server_socket = None
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(("0.0.0.0", 12345))
        server_socket.listen(5)
        server_socket.settimeout(1.0)
        logging.info("Server listening on 0.0.0.0:12345")
        while _running:
            try:
                client_socket, addr = server_socket.accept()
                logging.info(f"Connection from {addr}")
                Thread(target=handle_client, args=(client_socket, sensor1, sensor2, motor_a, motor_b, threshold, duration), daemon=True).start()
            except socket.timeout:
                continue
            except Exception as e:
                logging.error(f"Accept error: {e}")
    except Exception as e:
        logging.error(f"Server error: {e}")
    finally:
        _running = False
        if server_socket:
            try:
                server_socket.close()
            except Exception:
                pass
        sensor1.cleanup()
        sensor2.cleanup()
        motor_a.cleanup()
        motor_b.cleanup()
        logging.info("Cleanup complete.")


if __name__ == "__main__":
    main()

