import time
import signal
import sys
import math
import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import adafruit_ads1x15.ads1015 as ADS
from adafruit_ads1x15.analog_in import AnalogIn
from adafruit_circuitpython_lsm303_accel import LSM303_Accel
from adafruit_circuitpython_lsm303dlh_mag import LSM303DLH_Mag
from adafruit_ads1x15 import ADS1015
import RPi.GPIO as GPIO

# Constants
MOTOR_DIR_PIN = 20
MOTOR_STEP_PIN = 21
MOTOR_CW = 1
MOTOR_CCW = 0
MOTOR_MS0_PIN = 14
MOTOR_MS1_PIN = 15
MOTOR_RESOLUTION = {
    'Full': (0, 0),
    'Half': (1, 0),
    '1/4': (0, 1),
    '1/8': (1, 1)
}
PWM_FREQUENCY = 500
ADC_GAIN = 1
ADC_CHANNEL = 0
ADC_MAX_VOLTAGE = 2.048

# Global state
running = True
pwm = None

def signal_handler(sig, frame):
    global running
    running = False

def initialize_i2c():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_accelerometer(i2c):
    try:
        accelerometer = adafruit_lsm303_accel.LSM303_Accel(i2c)
        return accelerometer
    except Exception as e:
        print(f"Error initializing accelerometer: {e}")
        return None

def initialize_magnetometer(i2c):
    try:
        magnetometer = adafruit_lsm303dlh_mag.LSM303DLH_Mag(i2c)
        return magnetometer
    except Exception as e:
        print(f"Error initializing magnetometer: {e}")
        return None

def initialize_adc(i2c):
    try:
        ads = ADS.ADS1015(i2c, address=0x48)
        ads.gain = ADC_GAIN
        return ads
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None

def initialize_motor(dir_pin, step_pin, ms0_pin, ms1_pin, resolution='Full'):
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(dir_pin, GPIO.OUT)
        GPIO.setup(step_pin, GPIO.OUT)
        GPIO.setup(ms0_pin, GPIO.OUT)
        GPIO.setup(ms1_pin, GPIO.OUT)
        GPIO.output(dir_pin, MOTOR_CCW)
        ms0, ms1 = MOTOR_RESOLUTION[resolution]
        GPIO.output(ms0_pin, ms0)
        GPIO.output(ms1_pin, ms1)
        return True
    except Exception as e:
        print(f"Error initializing motor: {e}")
        return False

def setup_pwm(step_pin, frequency):
    global pwm
    try:
        pwm = GPIO.PWM(step_pin, frequency)
        pwm.start(0)
        return True
    except Exception as e:
        print(f"Error setting up PWM: {e}")
        return False

def set_motor_speed(pwm_obj, duty_cycle):
    try:
        pwm_obj.ChangeDutyCycle(duty_cycle)
    except Exception as e:
        print(f"Error setting motor speed: {e}")

def read_adc_channel(adc, channel):
    try:
        chan = AnalogIn(adc, channel)
        return chan.voltage
    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}")
        return None

def voltage_to_duty_cycle(voltage, max_voltage=ADC_MAX_VOLTAGE):
    return int((voltage / max_voltage) * 255)

def calculate_heading(magnetometer):
    try:
        mag_x, mag_y, _ = magnetometer.magnetic
        heading_rad = math.atan2(mag_y, mag_x)
        heading_deg = math.degrees(heading_rad)
        if heading_deg < 0:
            heading_deg += 360
        return heading_deg
    except Exception as e:
        print(f"Error calculating heading: {e}")
        return None

def calculate_inclination(accelerometer):
    try:
        acc_x, acc_y, acc_z = accelerometer.acceleration
        inclination_xz = math.degrees(math.atan2(acc_x, acc_z))
        inclination_yz = math.degrees(math.atan2(acc_y, acc_z))
        return inclination_xz, inclination_yz
    except Exception as e:
        print(f"Error calculating inclination: {e}")
        return None, None

def cleanup():
    global pwm
    if pwm is not None:
        try:
            pwm.stop()
        except Exception:
            pass
    GPIO.cleanup()
    print("GPIO cleaned up.")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c = initialize_i2c()
    if i2c is None:
        sys.exit(1)

    accelerometer = initialize_accelerometer(i2c)
    if accelerometer is None:
        sys.exit(1)

    magnetometer = initialize_magnetometer(i2c)
    if magnetometer is None:
        sys.exit(1)

    adc = initialize_adc(i2c)
    if adc is None:
        sys.exit(1)

    if not initialize_motor(MOTOR_DIR_PIN, MOTOR_STEP_PIN, MOTOR_MS0_PIN, MOTOR_MS1_PIN, 'Full'):
        sys.exit(1)

    if not setup_pwm(MOTOR_STEP_PIN, PWM_FREQUENCY):
        sys.exit(1)

    try:
        while running:
            adc_voltage = read_adc_channel(adc, ADC_CHANNEL)
            if adc_voltage is not None:
                duty_cycle = voltage_to_duty_cycle(adc_voltage)
                set_motor_speed(pwm, duty_cycle)
            else:
                set_motor_speed(pwm, 0)

            acc_x, acc_y, acc_z = accelerometer.acceleration
            print(f'Acceleration (m/s^2): ({acc_x:10.3f}, {acc_y:10.3f}, {acc_z:10.3f})')

            mag_x, mag_y, mag_z = magnetometer.magnetic
            print(f'Magnetometer (gauss): ({mag_x:10.3f}, {mag_y:10.3f}, {mag_z:10.3f})')

            heading = calculate_heading(magnetometer)
            if heading is not None:
                print(f"Heading: {heading:.2f} degrees")

            inclination_xz, inclination_yz = calculate_inclination(accelerometer)
            if inclination_xz is not None and inclination_yz is not None:
                print(f"XZ angle = {inclination_xz:6.2f}deg   YZ angle = {inclination_yz:6.2f}deg")

            time.sleep(1)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

