import spidev
import time
import logging
import signal
import sys
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

PUMP_GPIO_PIN = 18
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1350000
SOIL_MOISTURE_CHANNEL = 0
DRY_THRESHOLD = 450


class SmartGardenController:
    def __init__(self, pump_pin, spi_bus, spi_device, spi_speed_hz, moisture_channel, dry_threshold):
        self.pump_pin = pump_pin
        self.moisture_channel = moisture_channel
        self.dry_threshold = dry_threshold
        self.spi = None
        self._running = True

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pump_pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            logging.error(f"GPIO setup failed: {e}")
            raise

        try:
            self.spi = spidev.SpiDev()
            self.spi.open(spi_bus, spi_device)
            self.spi.max_speed_hz = spi_speed_hz
            self.spi.mode = 0
            logging.info(f"SPI opened: bus={spi_bus}, device={spi_device}, speed={spi_speed_hz} Hz")
        except Exception as e:
            logging.error(f"SPI initialization failed: {e}")
            self.close()
            raise

    def read_moisture(self):
        if self.spi is None:
            logging.error("SPI device not initialized")
            return None
        try:
            command = [1, (8 + self.moisture_channel) << 4, 0]
            response = self.spi.xfer2(command)
            raw_value = ((response[1] & 3) << 8) + response[2]
            logging.debug(f"Raw moisture value: {raw_value}")
            return raw_value
        except Exception as e:
            logging.error(f"Error reading moisture: {e}")
            return None

    def run_pump(self, run_seconds):
        try:
            GPIO.output(self.pump_pin, GPIO.HIGH)
            logging.info(f"Pump ON for {run_seconds} seconds")
            time.sleep(run_seconds)
        except Exception as e:
            logging.error(f"Error running pump: {e}")
        finally:
            GPIO.output(self.pump_pin, GPIO.LOW)
            logging.info("Pump OFF")

    def irrigation_cycle(self):
        moisture_level = self.read_moisture()
        if moisture_level is None:
            logging.warning("Skipping cycle due to sensor read failure")
            return False
        if moisture_level > self.dry_threshold:
            logging.info(f"Soil wet (raw={moisture_level}), running pump for 2s")
            self.run_pump(2)
            return True
        logging.info(f"Soil dry (raw={moisture_level}), no watering needed")
        return False

    def close(self):
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception as e:
                logging.error(f"Error closing SPI: {e}")
            finally:
                self.spi = None
        try:
            GPIO.cleanup()
        except Exception as e:
            logging.error(f"GPIO cleanup error: {e}")
        logging.info("Resources released")

    def stop(self):
        self._running = False


def schedule_cycles(controller, cycle_count, interval_seconds):
    for cycle_index in range(cycle_count):
        if not controller._running:
            logging.info("Controller stopped by signal")
            break
        logging.info(f"Starting scheduled cycle {cycle_index + 1}/{cycle_count}")
        controller.irrigation_cycle()
        if cycle_index < cycle_count - 1:
            time.sleep(interval_seconds)


def signal_handler(signum, frame):
    logging.info(f"Signal {signum} received, shutting down...")
    if 'controller' in globals():
        controller.stop()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    controller = None
    try:
        controller = SmartGardenController(
            PUMP_GPIO_PIN, SPI_BUS, SPI_DEVICE, SPI_SPEED_HZ,
            SOIL_MOISTURE_CHANNEL, DRY_THRESHOLD
        )
        schedule_cycles(controller, cycle_count=10, interval_seconds=3)
    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if controller is not None:
            controller.close()

