import time
import signal
import sys
import board
import busio
import adafruit_max30102

LOG_FILE = "heart_rate_log.txt"
SAMPLE_INTERVAL = 1.0
WINDOW_SECONDS = 4.0

running = True
sensor = None


def _format_value(v):
    """Safely format a value, handling _AdaValue (emulated) objects."""
    if v is None:
        return "None"
    try:
        return f"{v:.2f}"
    except (TypeError, ValueError):
        try:
            return f"{int(v):d}"
        except (TypeError, ValueError):
            return str(v)


def _safe_get(v):
    """Safely read a property from the sensor, returning None on failure."""
    try:
        return v
    except Exception:
        return None


def _cleanup(signum=None, frame=None):
    """Signal handler / cleanup routine."""
    global running
    running = False


def main():
    global sensor

    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    # Initialize I2C bus
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Fatal: failed to initialize I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    # Initialize MAX30102 sensor
    try:
        sensor = adafruit_max30102.MAX30102(i2c)
        sensor.setup()
    except Exception as e:
        print(f"Fatal: MAX30102 sensor not detected on I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

    print("MAX30102 initialized. Logging heart rate to heart_rate_log.txt. Press Ctrl-C to stop.")

    ir_values = []
    red_values = []

    while running:
        loop_start = time.monotonic()

        try:
            ir = _safe_get(sensor.ir)
            red = _safe_get(sensor.red)

            if ir is not None and red is not None:
                ir_values.append(ir)
                red_values.append(red)

                # Keep rolling window of ~4 seconds
                cutoff = time.monotonic() - WINDOW_SECONDS
                while ir_values and ir_values[0][1] < cutoff:
                    ir_values.pop(0)
                while red_values and red_values[0][1] < cutoff:
                    red_values.pop(0)

                # Estimate BPM from peak count in the window
                now = time.monotonic()
                window_ir = [v for v, t in ir_values if t >= now - WINDOW_SECONDS]
                window_red = [v for v, t in red_values if t >= now - WINDOW_SECONDS]

                if window_ir and window_red:
                    avg_ir = sum(window_ir) / len(window_ir)
                    avg_red = sum(window_red) / len(window_red)
                    # Simple heuristic: if red is significantly higher, assume valid reading
                    if avg_red > avg_ir * 0.5:
                        bpm = int(len(window_ir) / WINDOW_SECONDS * 60)
                    else:
                        bpm = 0
                else:
                    bpm = 0

                timestamp = time.strftime("%Y-%m-%dT%H:%M:%S")
                log_entry = f"{timestamp} - Heart Rate: {_format_value(bpm)} bpm, IR: {_format_value(avg_ir if window_ir else None)}, RED: {_format_value(avg_red if window_red else None)}\n"

                try:
                    with open(LOG_FILE, "a") as f:
                        f.write(log_entry)
                except OSError as e:
                    print(f"Warning: failed to write log file: {e}", file=sys.stderr)

                print(log_entry.strip())

        except Exception as e:
            print(f"Warning: sensor read error: {e}", file=sys.stderr)

        # Maintain ~1-second sampling interval
        elapsed = time.monotonic() - loop_start
        sleep_time = max(0.0, SAMPLE_INTERVAL - elapsed)
        time.sleep(sleep_time)

    print("\nShutting down...")
    if sensor is not None:
        try:
            sensor.shutdown()
        except Exception:
            pass


if __name__ == "__main__":
    main()

