import argparse
import json
import logging
import queue
import signal
import sys
import threading
import time

import cv2
import numpy as np
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DEFAULT_CONFIG = {
    "resolution": "640x480",
    "framerate": 30,
    "max_queue_size": 5,
    "gpio_pin": 17,
    "led_duration": 2,
    "motion_threshold": 25
}

class MotionDetector:
    def __init__(self, config):
        self.config = config
        self.frame_queue = queue.Queue(maxsize=config["max_queue_size"])
        self.running = True
        self.camera = None
        self.led_pin = config.get("gpio_pin")
        self.led_duration = config.get("led_duration", 2)
        self.motion_threshold = config.get("motion_threshold", 25)
        self.led_timer = None
        self.lock = threading.Lock()

    def initialize_camera(self):
        try:
            resolution = tuple(map(int, self.config["resolution"].split("x")))
            self.camera = cv2.VideoCapture(0)
            if not self.camera.isOpened():
                raise IOError("Cannot open camera")
            self.camera.set(cv2.CAP_PROP_FRAME_WIDTH, resolution[0])
            self.camera.set(cv2.CAP_PROP_FRAME_HEIGHT, resolution[1])
            self.camera.set(cv2.CAP_PROP_FPS, self.config["framerate"])
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            raise

    def capture_frames(self):
        try:
            while self.running:
                ret, frame = self.camera.read()
                if not ret:
                    logging.error("Failed to capture frame from camera.")
                    break
                try:
                    self.frame_queue.put(frame, timeout=1)
                except queue.Full:
                    logging.warning("Frame queue is full. Dropping frame.")
