import cv2
import sys
import time
import signal
import logging
import numpy as np

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None
    logging.warning("RPi.GPIO not available; running in mock GPIO mode.")

try:
    from lib_robotkit.extras import simple_pwm
except ImportError:
    simple_pwm = None
    logging.warning("lib_robotkit.extras.simple_pwm not available; running in mock PWM mode.")

FACE_CASCADE_PATH = '/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml'
CAMERA_INDEX = 0
WINDOW_NAME = 'Human Detection'
RESIZE_HEIGHT = 32
LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
SERVO_FREQ = 50
SERVO_STEP = 20
SERVO_DELAY = 0.02

_running = True


def _signal_handler(signum, frame):
    global _running
    logging.info(f"Signal {signum} received; shutting down.")
    _running = False


def initialize_camera(camera_index=CAMERA_INDEX):
    try:
        cap = cv2.VideoCapture(camera_index)
        if not cap.isOpened():
            raise IOError(f"Cannot open camera at index {camera_index}")
        logging.info(f"Camera {camera_index} opened successfully.")
        return cap
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return None


def initialize_face_detector(cascade_path=FACE_CASCADE_PATH):
    try:
        if not cv2.os.path.exists(cascade_path):
            raise FileNotFoundError(f"Cascade file not found: {cascade_path}")
        face_cascade = cv2.CascadeClassifier(cascade_path)
        if face_cascade.empty():
            raise IOError(f"Failed to load face cascade classifier from {cascade_path}")
        logging.info("Face detector initialized successfully.")
        return face_cascade
    except Exception as e:
        logging.error(f"Error initializing face detector: {e}")
        return None


def initialize_gpio():
    if GPIO is None:
        logging.warning("Mock GPIO mode enabled.")
        return None
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        logging.info("GPIO initialized: LED=14, BUTTON=15.")
        return True
    except Exception as e:
        logging.error(f"Error initializing GPIO: {e}")
        return False


def initialize_servo():
    if simple_pwm is None:
        logging.warning("Mock PWM mode enabled.")
        return None
    try:
        pwm = simple_pwm(SERVO_PIN, SERVO_FREQ)
        pwm.start(0)
        logging.info(f"Servo initialized on GPIO{SERVO_PIN} at {SERVO_FREQ} Hz.")
        return pwm
    except Exception as e:
        logging.error(f"Error initializing servo: {e}")
        return None


def detect_faces(image, face_cascade):
    try:
        gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
        faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
        return faces
    except Exception as e:
        logging.error(f"Error detecting faces: {e}")
        return []


def draw_rectangles(image, faces):
    try:
        for (x, y, w, h) in faces:
            cv2.rectangle(image, (x, y), (x + w, y + h), (255, 0, 0), 2)
    except Exception as e:
        logging.error(f"Error drawing rectangles: {e}")


def control_led(state, gpio_ok):
    if not gpio_ok:
        return
    try:
        GPIO.output(LED_PIN, GPIO.HIGH if state else GPIO.LOW)
    except Exception as e:
        logging.error(f"Error controlling LED: {e}")


def control_servo(angle, pwm_ok):
    if not pwm_ok:
        return
    try:
        angle = max(0, min(180, angle))
        duty = (angle / 180.0) * 100.0
        pwm = simple_pwm(SERVO_PIN, SERVO_FREQ)
        pwm.start(duty)
        time.sleep(SERVO_DELAY)
        pwm.stop()
    except Exception as e:
        logging.error(f"Error controlling servo: {e}")


def cleanup(cap, pwm_ok, gpio_ok):
    logging.info("Cleaning up resources...")
    if cap is not None:
        try:
            cap.release()
        except Exception:
            pass
    try:
        cv2.destroyAllWindows()
    except Exception:
        pass
    if pwm_ok:
        try:
            pwm = simple_pwm(SERVO_PIN, SERVO_FREQ)
            pwm.start(0)
            time.sleep(SERVO_DELAY)
            pwm.stop()
        except Exception:
            pass
    if gpio_ok:
        try:
            GPIO.cleanup()
        except Exception:
            pass
    logging.info("Cleanup complete.")


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    cap = initialize_camera()
    if cap is None:
        logging.error("Camera initialization failed. Exiting.")
        sys.exit(0)

    face_cascade = initialize_face_detector()
    if face_cascade is None:
        logging.error("Face detector initialization failed. Exiting.")
        cleanup(cap, False, False)
        sys.exit(0)

    gpio_ok = initialize_gpio()
    pwm_ok = initialize_servo()

    servo_angle = 90
    try:
        while _running:
            ret, frame = cap.read()
            if not ret:
                logging.error("Failed to grab frame from camera.")
                break

            try:
                h, w = frame.shape[:2]
                if h != RESIZE_HEIGHT:
                    frame = cv2.resize(frame, (int(w * RESIZE_HEIGHT / h), RESIZE_HEIGHT))
            except Exception as e:
                logging.error(f"Error resizing frame: {e}")
                continue

            faces = detect_faces(frame, face_cascade)
            face_detected = len(faces) > 0

            control_led(face_detected, gpio_ok)

            if face_detected:
                face_x = (faces[0][0] + faces[0][2] // 2)
                if face_x > w // 2:
                    servo_angle = min(180, servo_angle + SERVO_STEP)
                else:
                    servo_angle = max(0, servo_angle - SERVO_STEP)
                control_servo(servo_angle, pwm_ok)

            draw_rectangles(frame, faces)

            try:
                cv2.imshow(WINDOW_NAME, frame)
            except Exception as e:
                logging.error(f"Error displaying frame: {e}")
                break

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup(cap, pwm_ok, gpio_ok)


if __name__ == "__main__":
    main()

