import os
import time
import datetime
import logging
import configparser
import signal
import sys
import shutil
import glob

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

PIR_PIN = 4
DEFAULT_CONFIG_FILE = 'config.ini'
DEFAULT_LOG_FILE = 'system.log'
DEFAULT_STORAGE_DIR = 'camera_storage'
DEFAULT_DISK_SPACE_THRESHOLD_MB = 100

config = None
camera = None
running = True


def setup_logging(log_file):
    log_dir = os.path.dirname(os.path.abspath(log_file))
    if not os.path.isdir(log_dir):
        try:
            os.makedirs(log_dir, exist_ok=True)
        except OSError:
            log_dir = './logs'
            log_file = os.path.join(log_dir, os.path.basename(log_file))
            try:
                os.makedirs(log_dir, exist_ok=True)
            except OSError:
                log_file = 'system.log'
    try:
        logging.basicConfig(
            filename=log_file,
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s'
        )
    except (OSError, PermissionError):
        print(f"Cannot write to log file {log_file}; falling back to console.")
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s'
        )
    logging.info("Logging initialized.")


def load_config(config_file):
    global config
    config = configparser.ConfigParser()
    if not os.path.exists(config_file):
        logging.warning(f"Config file {config_file} not found; creating with defaults.")
        config['DEFAULT'] = {
            'storage_directory': DEFAULT_STORAGE_DIR,
            'disk_space_threshold_mb': str(DEFAULT_DISK_SPACE_THRESHOLD_MB),
            'log_file': DEFAULT_LOG_FILE
        }
        try:
            with open(config_file, 'w') as f:
                config.write(f)
        except OSError as e:
            logging.error(f"Failed to write default config: {e}")
    try:
        config.read(config_file)
        return config['DEFAULT']
    except (configparser.Error, KeyError) as e:
        logging.error(f"Error reading config file: {e}")
        return None


def setup_gpio(pin):
    if GPIO is None:
        logging.warning("RPi.GPIO not available; running in degraded mode.")
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        logging.info(f"GPIO pin {pin} configured as input with pull-down.")
        return True
    except Exception as e:
        logging.error(f"Failed to setup GPIO pin {pin}: {e}")
        return False


def initialize_camera():
    if Picamera2 is None:
        logging.error("picamera2 library not installed.")
        return None
    try:
        cam = Picamera2()
        cam.configure(cam.create_still_configuration())
        cam.start()
        logging.info("Camera initialized successfully.")
        return cam
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        return None


def capture_image(cam, storage_dir):
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(storage_dir, f"image_{timestamp}.jpg")
        cam.capture_file(filename, format='jpeg', quality=85)
        logging.info(f"Image captured: {filename}")
        return filename
    except Exception as e:
        logging.error(f"Failed to capture image: {e}")
        return None


def capture_video(cam, storage_dir):
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(storage_dir, f"video_{timestamp}.h264")
        cam.start_recording(filename, bitrate=1700000)
        time.sleep(5)
        cam.stop_recording()
        logging.info(f"Video captured: {filename}")
        return filename
    except Exception as e:
        logging.error(f"Failed to capture video: {e}")
        try:
            cam.stop_recording()
        except Exception:
            pass
        return None


def manage_disk_space(storage_dir, threshold_mb):
    try:
        statvfs = os.statvfs(storage_dir)
        total = statvfs.f_frsize * statvfs.f_blocks
        free = statvfs.f_frsize * statvfs.f_bavail
        used_mb = (total - free) / (1024 * 1024)
        if used_mb > threshold_mb:
            logging.warning(f"Disk space usage ({used_mb:.1f} MB) exceeds threshold ({threshold_mb} MB). Managing space.")
            files = []
            for root, _, filenames in os.walk(storage_dir):
                for f in filenames:
                    full = os.path.join(root, f)
                    try:
                        files.append((os.path.getmtime(full), full))
                    except OSError:
                        pass
            files.sort()
            freed = 0
            for _, f in files:
                try:
                    if f.endswith('.h264'):
                        os.remove(f)
                        freed += 1
                        logging.info(f"Deleted old video: {f}")
                    elif f.endswith('.jpg'):
                        os.remove(f)
                        freed += 1
                        logging.info(f"Deleted old image: {f}")
                    statvfs = os.statvfs(storage_dir)
                    total = statvfs.f_frsize * statvfs.f_blocks
                    free = statvfs.f_frsize * statvfs.f_bavail
                    used_mb = (total - free) / (1024 * 1024)
                    if used_mb <= threshold_mb:
                        break
                except OSError as e:
                    logging.error(f"Error deleting file {f}: {e}")
            logging.info(f"Deleted {freed} files to free up disk space.")
    except Exception as e:
        logging.error(f"Error managing disk space: {e}")


def cleanup(signum=None, frame=None):
    global running, camera
    running = False
    logging.info("Shutdown signal received. Cleaning up...")
    if camera is not None:
        try:
            camera.stop()
            camera.close()
            logging.info("Camera released.")
        except Exception as e:
            logging.error(f"Error releasing camera: {e}")
    if GPIO is not None:
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"Error cleaning GPIO: {e}")
    if signum is not None:
        sys.exit(0)


def main():
    global camera, running
    config_data = load_config(DEFAULT_CONFIG_FILE)
    if config_data is None:
        print("Failed to load configuration. Exiting.")
        return

    storage_directory = config_data.get('storage_directory', DEFAULT_STORAGE_DIR)
    disk_space_threshold_mb = int(config_data.get('disk_space_threshold_mb', DEFAULT_DISK_SPACE_THRESHOLD_MB))
    log_file = config_data.get('log_file', DEFAULT_LOG_FILE)

    setup_logging(log_file)
    logging.info("Starting motion-activated camera system.")

    if not setup_gpio(PIR_PIN):
        logging.warning("GPIO setup failed; continuing in degraded mode.")

    camera = initialize_camera()
    if camera is None:
        logging.warning("Camera initialization failed; continuing in degraded mode.")

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        while running:
            try:
                motion_detected = GPIO.input(PIR_PIN) if GPIO is not None else False
            except Exception:
                motion_detected = False
                time.sleep(0.5)
                continue

            if motion_detected:
                logging.info("Motion detected!")
                time.sleep(2)

                now = datetime.datetime.now()
                date_dir = os.path.join(storage_directory, str(now.year), f"{now.month:02d}", f"{now.day:02d}")
                try:
                    os.makedirs(date_dir, exist_ok=True)
                except OSError as e:
                    logging.error(f"Failed to create directory {date_dir}: {e}")
                    time.sleep(1)
                    continue

                manage_disk_space(storage_directory, disk_space_threshold_mb)

                if camera is not None:
                    for _ in range(3):
                        if not running:
                            break
                        capture_image(camera, date_dir)
                        time.sleep(0.5)

                    if running and camera is not None:
                        capture_video(camera, date_dir)

            time.sleep(0.1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()
        logging.info("Program exited.")


if __name__ == "__main__":
    main()

