import time
import datetime
import statistics
import json
import logging
import signal
import sys
import os

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sensors": [
        {"trigger": 17, "echo": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger": 22, "echo": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger": 24, "echo": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning(f"Config file '{config_file}' not found. Using defaults.")
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding JSON from '{config_file}': {e}. Using defaults.")
    except OSError as e:
        logging.error(f"Error reading '{config_file}': {e}. Using defaults.")
    return DEFAULT_CONFIG


def initialize_gpio(config):
    if GPIO is None:
        logging.warning("RPi.GPIO not available; running in mock mode.")
        return True
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for s in config.get("sensors", []):
            t = s.get("trigger")
            e = s.get("echo")
            if t is None or e is None:
                logging.error("Sensor config missing trigger/echo pin.")
                return False
            GPIO.setup(t, GPIO.OUT, initial=GPIO.LOW)
            GPIO.setup(e, GPIO.IN)
        return True
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return False


def measure_distance(trigger, echo, offset, max_distance):
    if GPIO is None:
        return None
    try:
        GPIO.output(trigger, GPIO.LOW)
        time.sleep(0.000002)
        GPIO.output(trigger, GPIO.HIGH)
