import signal
import sys
import time
from pathlib import Path

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

FAN_PIN = 17
TEMP_FILE = Path("/sys/class/thermal/thermal_zone0/temp")
POLL_INTERVAL = 5.0
DEFAULT_PWM = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def validate_thresholds(thresholds, pwm_values):
    if len(thresholds) != len(pwm_values):
        raise ValueError("Thresholds and PWM values arrays must have the same length.")
    for pwm in pwm_values:
        if not 0.0 <= pwm <= 1.0:
            raise ValueError("PWM values must be between 0.0 and 1.0.")


def get_cpu_temperature():
    try:
        raw = TEMP_FILE.read_text().strip()
        return int(raw) / 1000.0
    except (OSError, ValueError) as e:
        raise RuntimeError(f"Failed to read CPU temperature: {e}") from e


def determine_pwm(temperature, thresholds, pwm_values):
    for i, threshold in enumerate(thresholds):
        if temperature > threshold:
            return pwm_values[i]
    return pwm_values[-1]


def set_fan_speed(fan, pwm_value):
    try:
        fan.value = pwm_value
    except Exception as e:
        raise RuntimeError(f"Failed to set fan PWM: {e}") from e


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    thresholds = [65, 55, 50, 45]
    pwm_values = [1.0, 0.8, 0.6, 0.4]

    try:
        validate_thresholds(thresholds, pwm_values)
    except ValueError as e:
        print(f"Configuration error: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        fan = PWMOutputDevice(FAN_PIN)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        set_fan_speed(fan, DEFAULT_PWM)
        print(f"Fan control started on GPIO{FAN_PIN} at default speed {DEFAULT_PWM:.2f}")

        while _running:
            try:
                temperature = get_cpu_temperature()
                target_pwm = determine_pwm(temperature, thresholds, pwm_values)
                set_fan_speed(fan, target_pwm)
                print(f"Temperature: {temperature:.1f}°C, Fan speed: {target_pwm:.2f}")
            except RuntimeError as e:
                print(f"Error during monitoring cycle: {e}", file=sys.stderr)
                try:
                    set_fan_speed(fan, DEFAULT_PWM)
                except RuntimeError:
                    pass

            for _ in range(int(POLL_INTERVAL)):
                if not _running:
                    break
                time.sleep(1)

    finally:
        try:
            set_fan_speed(fan, DEFAULT_PWM)
            print("Fan set to default speed during shutdown.")
        except Exception as e:
            print(f"Error setting fan to default during shutdown: {e}", file=sys.stderr)
        try:
            fan.close()
        except Exception as e:
            print(f"Error closing PWM device: {e}", file=sys.stderr)
        print("Fan control stopped.")


if __name__ == "__main__":
    main()

