#!/usr/bin/env python3
"""
Raspberry Pi motion-activated security camera with storage management.

Captures 15 fps video via the CSI camera module, detects motion by comparing
average brightness of consecutive grayscale frames, records 5-second H.264
clips on motion, and enforces a 1.0 GB storage limit by deleting oldest files.
"""

import argparse
import datetime
import os
import signal
import sys
import time
from pathlib import Path

import cv2
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
DEFAULT_THRESHOLD = 5
DEFAULT_DURATION = 5          # seconds
DEFAULT_MAX_SIZE = 1.0        # GB
STORAGE_DIR = Path("/home/pi/security_footage")
FRAME_RATE = 15               # fps
MOTION_CHECK_INTERVAL = 2.0   # seconds between motion checks
CAPTURE_RESOLUTION = (320, 240)  # width, height

# ---------------------------------------------------------------------------
# Globals for clean shutdown
# ---------------------------------------------------------------------------
_running = True
_camera: Picamera2 | None = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Raspberry Pi motion-activated security camera (CSI camera)"
    )
    parser.add_argument(
        "--threshold", type=int, default=DEFAULT_THRESHOLD,
        help="Motion threshold (average brightness difference, default 5)"
    )
    parser.add_argument(
        "--duration", type=int, default=DEFAULT_DURATION,
        help="Recording duration in seconds (default 5)"
    )
    parser.add_argument(
        "--max_size", type=float, default=DEFAULT_MAX_SIZE,
        help="Maximum storage size in GB (default 1.0)"
    )
    return parser.parse_args()


def _ensure_storage_dir() -> bool:
    """Create the storage directory if it does not exist.

    Returns True on success, False on failure.
    """
    try:
        STORAGE_DIR.mkdir(parents=True, exist_ok=True)
        return True
    except PermissionError as exc:
        print(f"Error: permission denied creating {STORAGE_DIR}: {exc}", file=sys.stderr)
        return False
    except OSError as exc:
        print(f"Error: cannot create {STORAGE_DIR}: {exc}", file=sys.stderr)
        return False


def _manage_storage(max_bytes: int) -> None:
    """Delete oldest files in STORAGE_DIR until total size <= max_bytes."""
    if not STORAGE_DIR.is_dir():
        return
    try:
        files = sorted(
            (p for p in STORAGE_DIR.iterdir() if p.is_file()),
            key=lambda p: p.stat().st_mtime
        )
    except OSError as exc:
        print(f"Warning: cannot list storage directory: {exc}", file=sys.stderr)
        return

    total = 0
    for f in files:
        try:
            total += f.stat().st_size
        except OSError as exc:
            print(f"Warning: cannot stat {f}: {exc}", file=sys.stderr)
            continue
        if total <= max_bytes:
            break
        try:
            f.unlink()
            print(f"Deleted old file: {f.name}")
        except OSError as exc:
            print(f"Warning: cannot delete {f}: {exc}", file=sys.stderr)


def _capture_gray(cam: Picamera2) -> np.ndarray | None:
    """Capture a single frame and return it as a grayscale uint8 array.

    Returns None on failure.
    """
    try:
        frame = cam.capture_array()
    except Exception as exc:
        print(f"Error: frame capture failed: {exc}", file=sys.stderr)
        return None
    if frame is None:
        print("Error: captured frame is None", file=sys.stderr)
        return None
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_RGB2GRAY)
    except cv2.error as exc:
        print(f"Error: color conversion failed: {exc}", file=sys.stderr)
        return None
    return gray


def _average_brightness(gray: np.ndarray) -> float:
    """Return the mean pixel value of a grayscale frame."""
    return float(np.mean(gray))


def _record_clip(cam: Picamera2, duration: int, filename: str) -> bool:
    """Record an H.264 clip for *duration* seconds.

    Returns True on success, False on failure.
    """
    encoder = H264Encoder(bitrate=1_000_000)
    output = FileOutput(filename)
    try:
        cam.start_recording(encoder, output)
    except Exception as exc:
        print(f"Error: failed to start recording: {exc}", file=sys.stderr)
        return False

    deadline = time.monotonic() + duration
    try:
        while time.monotonic() < deadline and _running:
            time.sleep(0.1)
    finally:
        try:
            cam.stop_recording()
        except Exception as exc:
            print(f"Warning: stop_recording failed: {exc}", file=sys.stderr)
    return True


def main() -> int:
    global _camera

    args = _parse_args()
    if args.threshold < 0:
        print("Error: threshold must be >= 0", file=sys.stderr)
        return 2
    if args.duration <= 0:
        print("Error: duration must be > 0", file=sys.stderr)
        return 2
    if args.max_size <= 0:
        print("Error: max_size must be > 0", file=sys.stderr)
        return 2

    max_bytes = int(args.max_size * 1_073_741_824)  # 1 GB

    if not _ensure_storage_dir():
        return 1

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # ------------------------------------------------------------------
    # Camera initialization
    # ------------------------------------------------------------------
    try:
        _camera = Picamera2()
        config = _camera.create_video_configuration(
            main={"size": CAPTURE_RESOLUTION, "format": "RGB888"},
            controls={"FrameRate": FRAME_RATE}
        )
        _camera.configure(config)
        _camera.start()
        print("Camera initialized successfully.")
    except Exception as exc:
        print(f"Error: camera initialization failed: {exc}", file=sys.stderr)
        if _camera is not None:
            try:
                _camera.close()
            except Exception:
                pass
        return 1

    # ------------------------------------------------------------------
    # Warm-up: skip a few frames to let auto-exposure settle
    # ------------------------------------------------------------------
    for _ in range(5):
        if not _running:
            break
        _capture_gray(_camera)
        time.sleep(0.1)

    prev_brightness: float | None = None

    try:
        while _running:
            gray = _capture_gray(_camera)
            if gray is None:
                time.sleep(0.5)
                continue

