import sys
import time
import signal
import threading
import wave
import aifc
import sunau
import pygame.mixer
import cv2

import config
import face

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_camera = None
_lock = None
_button = None
_mixer = None
_running = True


def _cleanup():
    """Release all hardware / audio resources exactly once."""
    global _camera, _lock, _button, _mixer
    if _camera is not None:
        try:
            _camera.release()
        except Exception:
            pass
        _camera = None
    if _lock is not None:
        try:
            _lock.close()
        except Exception:
            pass
        _lock = None
    if _button is not None:
        try:
            _button.close()
        except Exception:
            pass
        _button = None
    if _mixer is not None:
        try:
            _mixer.quit()
        except Exception:
            pass
        _mixer = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _load_sound(path):
    """Load a WAV / AIFF / SUN audio file, returning a pygame.Sound or None."""
    try:
        return pygame.mixer.Sound(path)
    except pygame.error:
        try:
            with wave.open(path, "rb") as fh:
                data = fh.readframes(fh.getnframes())
            return pygame.mixer.Sound(buffer=data)
        except Exception:
            try:
                with aifc.open(path, "rb") as fh:
                    data = fh.readframes(fh.getnframes())
                return pygame.mixer.Sound(buffer=data)
            except Exception:
                try:
                    with sunau.open(path, "rb") as fh:
                        data = fh.readframes(fh.getnframes())
                    return pygame.mixer.Sound(buffer=data)
                except Exception:
                    print(f"[ERROR] Could not load sound file: {path}", file=sys.stderr)
                    return None


def _play_sound(channel, sound):
    """Play a sound on the given channel if it is not already playing."""
    if sound is None:
        return
    try:
        if not channel.get_busy():
            channel.play(sound)
    except Exception as exc:
        print(f"[WARN] Sound playback failed: {exc}", file=sys.stderr)


def _load_model():
    """Load the face-recognition model, verifying the file exists first."""
    import os
    model_path = config.TRAINING_FILE
    if not os.path.isfile(model_path):
        print(f"[ERROR] Training file not found: {model_path}", file=sys.stderr)
        sys.exit(1)
    try:
        return face.load_model(model_path)
    except Exception as exc:
        print(f"[ERROR] Failed to load model: {exc}", file=sys.stderr)
        sys.exit(1)


def _init_audio():
    """Initialize the pygame mixer with the configured parameters."""
    global _mixer
    try:
        pygame.mixer.init(
            frequency=config.AUDIO_FREQUENCY,
            size=config.AUDIO_SIZE,
            channels=config.AUDIO_CHANNELS,
            buffer=config.AUDIO_BUFFER,
        )
        _mixer = pygame.mixer
    except pygame.error as exc:
        print(f"[ERROR] Audio init failed: {exc}", file=sys.stderr)
        sys.exit(1)


def _init_hardware():
    """Initialize camera, GPIO lock/button, and audio."""
    global _camera, _lock, _button

    # --- Camera ----------------------------------------------------------
    try:
        _camera = config.get_camera()
        if _camera is None:
            print("[ERROR] Camera returned None", file=sys.stderr)
            sys.exit(1)
    except Exception as exc:
        print(f"[ERROR] Camera init failed: {exc}", file=sys.stderr)
        sys.exit(1)

    # --- GPIO (lock + button) -------------------------------------------
    try:
        import gpiozero
        _lock = gpiozero.OutputDevice(config.LOCK_GPIO_PIN, active_high=True, initial_value=True)
        _button = gpiozero.Button(config.BUTTON_GPIO_PIN, pull_up=True)
    except Exception as exc:
        print(f"[ERROR] GPIO init failed: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)


def _lock_door():
    """Drive the lock pin HIGH (locked)."""
    if _lock is not None:
        try:
            _lock.on()
        except Exception as exc:
            print(f"[WARN] Failed to lock door: {exc}", file=sys.stderr)


def _unlock_door():
    """Drive the lock pin LOW (unlocked)."""
    if _lock is not None:
        try:
            _lock.off()
        except Exception as exc:
            print(f"[WARN] Failed to unlock door: {exc}", file=sys.stderr)


def _capture_frame():
    """Capture a single frame from the camera; return None on failure."""
    try:
        ok, frame = _camera.read()
        if not ok or frame is None:
            print("[WARN] Camera read failed", file=sys.stderr)
            return None
        return frame
    except Exception as exc:
        print(f"[WARN] Camera read exception: {exc}", file=sys.stderr)
        return None


def _process_frame(frame, model, sounds):
    """Detect a face, run recognition, and act on the result."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    except Exception as exc:
        print(f"[WARN] Grayscale conversion failed: {exc}", file=sys.stderr)
        return

    try:
        face_coords = face.detect_single(gray)
    except Exception as exc:
        print(f"[WARN] Face detection failed: {exc}", file=sys.stderr)
        return

    if face_coords is None:
        print("[INFO] No face detected")
        return

    x, y, w, h = face_coords
    try:
        cropped = face.crop(gray, x, y, w, h)
        resized = face.resize(cropped)
    except Exception as exc:
        print(f"[WARN] Face preprocessing failed: {exc}", file=sys.stderr)
        return

    try:
        label, confidence = face.predict(model, resized)
    except Exception as exc:
        print(f"[WARN] Recognition failed: {exc}", file=sys.stderr)
        return

    print(f"[INFO] Predicted: {label}  Confidence: {confidence:.4f}")

    if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
        print("[INFO] Access granted — unlocking door")
        _unlock_door()
        _play_sound(sounds[0], sounds[3])
    else:
        print("[INFO] Access denied")
        _play_sound(sounds[2], sounds[4])
        _play_sound(sounds[1], sounds[5])


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _init_hardware()
    _init_audio()
    model = _load_model()

    sounds = [
        _mixer.Channel(0),
        _mixer.Channel(1),
        _mixer.Channel(2),
        _load_sound(config.WELCOME_SOUND_PATH),
        _load_sound(config.LATER_SOUND_PATH),
        _load_sound(config.WAIT_SOUND_PATH),
    ]
    if any(s is None for s in sounds[3:]):
        print("[ERROR] One or more sound files could not be loaded", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    _lock_door()
    print("[INFO] Door locked. Waiting for button press or 'l' on stdin...")

    try:
        while _running:
            # --- Button check ------------------------------------------
            if _button.is_pressed:
                frame = _capture_frame()
                if frame is not None:
                    _process_frame(frame, model, sounds)
                time.sleep(0.1)
                continue

            # --- Stdin 'l' check ---------------------------------------
            try:
                import select
                if select.select([sys.stdin], [], [], 0.0)[0]:
                    line = sys.stdin.readline().strip()
                    if line == "l":
                        print("[INFO] Manual lock command received")
                        _lock_door()
            except Exception:
                pass

            time.sleep(0.1)
    finally:
        print("[INFO] Shutting down...")
        _cleanup()


if __name__ == "__main__":
    main()

