import asyncio
import signal
import threading
import logging
import numpy as np
from typing import Callable, Optional

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

try:
    from picamera2 import Picamera2
except ImportError:
    logger.error("picamera2 library is not installed. Install with: pip install picamera2")
    raise

try:
    import cv2
except ImportError:
    logger.error("opencv-python is not installed. Install with: pip install opencv-python")
    raise


class WebSocketHandler:
    """Thread-safe WebSocket handler for broadcasting camera frames."""

    def __init__(self):
        self._connections: set = set()
        self._lock = threading.Lock()

    def has_connections(self) -> bool:
        with self._lock:
            return len(self._connections) > 0

    def add_connection(self, conn) -> None:
        with self._lock:
            self._connections.add(conn)

    def remove_connection(self, conn) -> None:
        with self._lock:
            self._connections.discard(conn)

    def broadcast(self, data: bytes) -> None:
        with self._lock:
            for conn in list(self._connections):
                try:
                    if conn.open:
                        conn.send(data)
                except Exception as e:
                    logger.warning(f"Failed to send to client: {e}")
                    self.remove_connection(conn)


class CameraStreamer:
    """Streams camera video to WebSocket clients with motion detection."""

    def __init__(
        self,
        websocket_handler: WebSocketHandler,
        detect_motion_function: Optional[Callable[[np.ndarray, np.ndarray], bool]] = None,
        resolution: tuple = (640, 480),
        framerate: int = 10,
    ):
        if not isinstance(websocket_handler, WebSocketHandler):
            raise TypeError("websocket_handler must be a WebSocketHandler instance")
        if detect_motion_function is not None and not callable(detect_motion_function):
            raise TypeError("detect_motion_function must be callable or None")
        if not isinstance(resolution, tuple) or len(resolution) != 2:
            raise ValueError("resolution must be a (width, height) tuple")
        if not isinstance(framerate, int) or framerate <= 0:
            raise ValueError("framerate must be a positive integer")

        self.websocket_handler = websocket_handler
        self.detect_motion_function = detect_motion_function
        self.resolution = resolution
        self.framerate = framerate
        self.camera: Optional[Picamera2] = None
        self.loop: Optional[asyncio.AbstractEventLoop] = None
        self._frame_buffer: list = []
        self._buffer_lock = threading.Lock()
        self._running = False
        self._thread: Optional[threading.Thread] = None

    def _initialize_camera(self) -> None:
        """Initialize the Picamera2 instance with the configured resolution and framerate."""
        try:
            self.camera = Picamera2()
            config = self.camera.create_video_configuration(
                main={"size": self.resolution, "format": "RGB888"},
                lores={"size": self.resolution, "format": "YUV420"},
            )
            self.camera.configure(config)
            self.camera.set_controls({"FrameRate": self.framerate})
            self.camera.start()
            logger.info(
                f"Camera initialized: resolution={self.resolution}, framerate={self.framerate}"
            )
        except Exception as e:
            logger.error(f"Failed to initialize camera: {e}")
            raise

    def _capture_frame(self) -> Optional[np.ndarray]:
        """Capture a single frame from the camera and return it as a NumPy array."""
        try:
            frame = self.camera.capture_array("main")
            if frame is None or frame.size == 0:
                logger.warning("Captured empty frame")
                return None
            return frame
        except Exception as e:
            logger.error(f"Frame capture failed: {e}")
            return None

    def _encode_jpeg(self, frame: np.ndarray) -> Optional[bytes]:
        """Encode a NumPy frame to JPEG bytes using OpenCV."""
        try:
            ok, encoded = cv2.imencode(".jpg", frame)
            if not ok or encoded is None:
                logger.warning("JPEG encoding failed")
                return None
            return encoded.tobytes()
        except Exception as e:
            logger.error(f"JPEG encoding failed: {e}")
            return None

    def _decode_jpeg(self, data: bytes) -> Optional[np.ndarray]:
        """Decode JPEG bytes to a NumPy frame using OpenCV."""
        try:
            arr = np.frombuffer(data, dtype=np.uint8)
            frame = cv2.imdecode(arr, cv2.IMREAD_COLOR)
            if frame is None:
                logger.warning("JPEG decode returned None")
                return None
            return frame
        except Exception as e:
            logger.error(f"JPEG decode failed: {e}")
            return None

    def _process_frame(self, frame: np.ndarray) -> None:
        """Process a single frame: detect motion and broadcast if needed."""
        try:
            if self.detect_motion_function is not None:
                with self._buffer_lock:
                    if self._frame_buffer:
                        prev_frame = self._frame_buffer[-1]
                        if self.detect_motion_function(prev_frame, frame):
                            jpeg_data = self._encode_jpeg(frame)
                            if jpeg_data:
                                self._schedule_broadcast(jpeg_data)
                    self._frame_buffer.append(frame)
                    if len(self._frame_buffer) > 5:
                        self._frame_buffer.pop(0)
            else:
                jpeg_data = self._encode_jpeg(frame)
                if jpeg_data:
                    self._schedule_broadcast(jpeg_data)
        except Exception as e:
            logger.error(f"Frame processing error: {e}")

    def _schedule_broadcast(self, data: bytes) -> None:
        """Schedule a broadcast via the asyncio event loop."""
        if self.loop is None:
            logger.warning("Event loop not available for broadcast")
            return
        try:
            self.loop.call_soon_threadsafe(self.websocket_handler.broadcast, data)
        except Exception as e:
            logger.error(f"Failed to schedule broadcast: {e}")

    def start(self, loop: asyncio.AbstractEventLoop) -> None:
        """Start the camera streamer in a background thread."""
        if self._running:
            logger.warning("Camera streamer is already running")
            return
        self.loop = loop
        try:
            self._initialize_camera()
        except Exception:
            logger.error("Camera initialization failed; aborting start")
            return
        self._running = True
        self._thread = threading.Thread(target=self._run, daemon=True)
        self._thread.start()
        logger.info("Camera streamer started")

    def _run(self) -> None:
        """Main capture loop running in the background thread."""
        try:
            while self._running:
                frame = self._capture_frame()
                if frame is not None:
                    self._process_frame(frame)
        except Exception as e:
            logger.error(f"Camera streamer thread error: {e}")
        finally:
            self._cleanup()

    def _cleanup(self) -> None:
        """Release camera resources."""
        if self.camera is not None:
            try:
                self.camera.stop()
                logger.info("Camera stopped")
            except Exception as e:
                logger.error(f"Error stopping camera: {e}")
            finally:
                self.camera = None
        self._running = False
        logger.info("Camera streamer stopped")

    def stop(self) -> None:
        """Signal the streamer to stop and wait for the thread to finish."""
        self._running = False
        if self._thread is not None and self._thread.is_alive():
            self._thread.join(timeout=5.0)
            if self._thread.is_alive():
                logger.warning("Camera streamer thread did not stop within timeout")
        self._cleanup()


def main() -> None:
    """Entry point: set up signal handling and run the streamer."""
    websocket_handler = WebSocketHandler()
    streamer = CameraStreamer(
        websocket_handler=websocket_handler,
        detect_motion_function=None,
        resolution=(640, 480),
        framerate=10,
    )

    def _signal_handler(signum, frame):
        logger.info(f"Received signal {signum}, shutting down...")
        streamer.stop()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    try:
        streamer.start(loop)
        loop.run_forever()
    except KeyboardInterrupt:
        logger.info("Keyboard interrupt received")
    finally:
        streamer.stop()
        loop.close()


if __name__ == "__main__":
    main()

