import os
import time
import random
import signal
import sys
from datetime import datetime

import gpiozero
from picamera2 import Picamera2

# --- Configuration -----------------------------------------------------------
BUTTON_PIN = 17
IMAGE_DIR = "images"
DEBOUNCE_DELAY = 0.2
LOOP_PAUSE = 0.1

# --- Globals for cleanup -----------------------------------------------------
_button = None
_camera = None
_running = True


def _cleanup():
    """Release camera and GPIO resources on exit."""
    global _camera, _button
    if _camera is not None:
        try:
            _camera.close()
        except Exception:
            pass
        _camera = None
    if _button is not None:
        try:
            _button.close()
        except Exception:
            pass
        _button = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _ensure_image_dir():
    """Create the image directory if it does not exist."""
    try:
        os.makedirs(IMAGE_DIR, exist_ok=True)
    except OSError as exc:
        print(f"Error: cannot create image directory '{IMAGE_DIR}': {exc}", file=sys.stderr)
        raise


def _init_camera():
    """Initialize the Picamera2 instance; return None on failure."""
    try:
        cam = Picamera2()
        cam.configure(
            cam.create_preview_configuration(
                main={"format": "XRGB8888", "size": (640, 480)}
            )
        )
        cam.start()
        return cam
    except Exception as exc:
        print(f"Error: camera initialization failed: {exc}", file=sys.stderr)
        return None


def _init_button():
    """Initialize the button input with pull-up; return None on failure."""
    try:
        return gpiozero.Button(BUTTON_PIN, pull_up=True, bounce_time=DEBOUNCE_DELAY)
    except Exception as exc:
        print(f"Error: GPIO setup failed on pin {BUTTON_PIN}: {exc}", file=sys.stderr)
        return None


def _read_simulated_sensors():
    """Return simulated temperature and humidity readings."""
    temperature = random.uniform(10.0, 40.0)
    humidity = random.uniform(30.0, 90.0)
    return temperature, humidity


def main():
    global _button, _camera

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Ensure image directory exists
    _ensure_image_dir()

    # Initialize camera
    _camera = _init_camera()
    if _camera is None:
        _cleanup()
        sys.exit(1)

    # Initialize button
    _button = _init_button()
    if _button is None:
        _cleanup()
        sys.exit(1)

    print("Monitoring button on GPIO 17 (BCM). Press Ctrl+C to exit.")

    try:
        while _running:
            if _button.is_pressed:
                timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                filename = os.path.join(IMAGE_DIR, f"image_{timestamp}.jpg")

                try:
                    _camera.capture_file(filename)
                    print(f"Image saved: {filename}")
                except Exception as exc:
                    print(f"Error: image capture failed: {exc}", file=sys.stderr)

                temperature, humidity = _read_simulated_sensors()
                print(
                    f"Temperature: {temperature:.2f} C, "
                    f"Humidity: {humidity:.2f} %"
                )

            time.sleep(LOOP_PAUSE)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        _cleanup()
        print("Resources released. Exiting.")


if __name__ == "__main__":
    main()

