import config
import face

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_lock = threading.Lock()


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    with _lock:
        _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


class Door:
    """Door-lock controller with a push-button and an actuator output."""

    def __init__(self, lock_pin=18, button_pin=17):
        self.lock_pin = lock_pin
        self.button_pin = button_pin
        self.is_locked = True
        self._lock_state = False
        self._button_state = False
        self._init_gpio()

    # ------------------------------------------------------------------
    # GPIO setup (no external driver library)
    # ------------------------------------------------------------------
    def _init_gpio(self):
        """Configure BCM pins for the lock actuator and button with pull-up."""
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.lock_pin, GPIO.OUT, initial=GPIO.LOW)
            GPIO.setup(self.button_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        except Exception as exc:
            raise RuntimeError(f"GPIO initialization failed: {exc}") from exc

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------
    def lock(self):
        self._set_lock(False)

    def unlock(self):
        self._set_lock(True)

    def is_button_up(self):
        """Return True when the button is pressed to ground."""
        try:
            import RPi.GPIO as GPIO
            return GPIO.input(self.button_pin) == GPIO.LOW
        except Exception as exc:
            print(f"Warning: button read failed: {exc}", file=sys.stderr)
            return False

    def is_locked_now(self):
        return self._lock_state

    # ------------------------------------------------------------------
    # Internal helpers
    # ------------------------------------------------------------------
    def _set_lock(self, unlock):
        """Drive the lock actuator and update internal state."""
        try:
            import RPi.GPIO as GPIO
            GPIO.output(self.lock_pin, GPIO.HIGH if unlock else GPIO.LOW)
            self._lock_state = unlock
        except Exception as exc:
            print(f"Warning: lock actuator write failed: {exc}", file=sys.stderr)

    def cleanup(self):
        """Release GPIO resources."""
        try:
            import RPi.GPIO as GPIO
            GPIO.cleanup()
        except Exception:
            pass


class Sound:
    """Thin wrapper around pygame.mixer.Sound with error handling."""

    def __init__(self, path):
        self.sound = None
        try:
            self.sound = mixer.Sound(path)
        except Exception as exc:
            print(f"Error loading sound '{path}': {exc}", file=sys.stderr)

    def play(self, channel):
        if self.sound is not None:
            try:
                channel.play(self.sound)
            except Exception as exc:
                print(f"Error playing sound: {exc}", file=sys.stderr)


class AudioPlayer:
    """Concurrent audio mixer playing three pre-loaded Sound objects."""

    def __init__(self, welcome_sound, wait_sound, later_sound):
        self.welcome_sound = welcome_sound
        self.wait_sound = wait_sound
        self.later_sound = later_sound
        self.channel_a = None
