import os
import sys
import time
import signal
import logging
import termios
import tty
import speech_recognition as sr
from picamera2 import Picamera2
import sx126x

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

SAMPLE_RATE = 44100
CHUNK_SIZE = 1024
TARGET_WORD = "capture"
IMAGE_PATH = "/home/raspberry/Desktop/IoT Project/captured_image.jpg"
LORA_FREQUENCY = 868
LORA_ADDRESS = 0
LORA_POWER = 22
LORA_AIR_SPEED = 2400

running = True
old_settings = None

def signal_handler(sig, frame):
    global running
    running = False

def init_lora_node():
    try:
        return sx126x.sx126x(serial_num=-1, freq=LORA_FREQUENCY, addr=LORA_ADDRESS,
                             power=LORA_POWER, rssi=True, air_speed=LORA_AIR_SPEED, relay=False)
    except Exception as e:
        logging.error(f"Failed to initialize LoRa node: {e}")
        return None

def send_lora_message(node, message):
    if node is None:
        logging.error("LoRa node not initialized. Cannot send message.")
        return False
    try:
        offset_frequency = LORA_FREQUENCY - 850
        data = bytes([0]) + bytes([0]) + bytes([offset_frequency]) + \
               bytes([node.addr >> 8]) + bytes([node.addr & 0xff]) + \
               bytes([node.offset_freq]) + message.encode()
        node.send(data)
        logging.info(f"Sent LoRa message: {message}")
        return True
    except Exception as e:
        logging.error(f"Failed to send LoRa message: {e}")
        return False

def capture_image(camera):
    try:
        os.makedirs(os.path.dirname(IMAGE_PATH), exist_ok=True)
        camera.capture_file(IMAGE_PATH)
        logging.info(f"Image captured and saved to: {IMAGE_PATH}")
        return True
    except Exception as e:
        logging.error(f"Failed to capture image: {e}")
        return False

def main():
    global old_settings
    signal.signal(signal.SIGINT, signal_handler)

    try:
        old_settings = termios.tcgetattr(sys.stdin)
        tty.setcbreak(sys.stdin.fileno())
    except Exception as e:
        logging.error(f"Failed to set terminal settings: {e}")

    try:
        camera = Picamera2()
        camera.configure(camera.create_still_configuration())
        camera.start()
        logging.info("Camera initialized.")
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        return

    lora_node = init_lora_node()

    recognizer = sr.Recognizer()
    try:
        with sr.Microphone(sample_rate=SAMPLE_RATE, chunk_size=CHUNK_SIZE) as source:
            logging.info("Adjusting for ambient noise...")
            recognizer.adjust_for_ambient_noise(source, duration=1)
            logging.info("Listening for the word 'capture'...")

            while running:
                try:
                    audio = recognizer.listen(source, timeout=5, phrase_time_limit=5)
                    words = recognizer.recognize_google(audio)
                    logging.info(f"Recognized: {words}")

                    if TARGET_WORD in words.lower():
                        if capture_image(camera):
                            send_lora_message(lora_node, "Image captured")

                except sr.WaitTimeoutError:
                    pass
                except sr.UnknownValueError:
                    logging.warning("Could not understand audio")
                except sr.RequestError as e:
                    logging.error(f"Could not request results from Google Web Speech API; {e}")
                except Exception as e:
                    logging.error(f"An unexpected error occurred: {e}")

    except Exception as e:
        logging.error(f"Microphone initialization failed: {e}")
    finally:
        if old_settings is not None:
            try:
                termios.tcsetattr(sys.stdin, termios.TCSADRAIN, old_settings)
            except Exception:
                pass
        try:
            camera.stop()
            camera.close()
            logging.info("Camera resources released.")
        except Exception:
            pass
        if lora_node is not None:
            try:
                lora_node.close()
                logging.info("LoRa node closed.")
            except Exception:
                pass
        logging.info("Exiting program.")

if __name__ == "__main__":
    main()

