import smbus

THERMAL_ZONE = '/sys/class/thermal/thermal_zone0/temp'
I2C_BUS = 1

running = True
bus = None

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global bus
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass
        bus = None

def main():
    global bus
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C via raspi-config.")
        sys.exit(1)
    except PermissionError:
        print(f"Error: Permission denied on I2C bus {I2C_BUS}. Run as root or add user to i2c group.")
        sys.exit(1)
    except OSError as e:
        print(f"Error initializing I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        while running:
            try:
                with open(THERMAL_ZONE, 'r') as f:
                    raw = f.read().strip()
                millideg = int(raw)
                celsius = millideg / 1000.0
                print(f"Temperature: {celsius:.2f} °C")
            except FileNotFoundError:
                print(f"Error: Thermal zone file {THERMAL_ZONE} not found.")
            except PermissionError:
                print(f"Error: Permission denied reading {THERMAL_ZONE}.")
            except (ValueError, OSError) as e:
                print(f"Error reading temperature: {e}")

            time.sleep(2)
    finally:
        cleanup()

if __name__ == '__main__':
    main()

