import os
import time
import signal
import logging
from PIL import Image, ImageOps

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class AnimatedGif:
    """
    Manages and plays animated GIFs on a display.

    Optimized for Raspberry Pi with robust error handling and resource cleanup.
    """

    def __init__(self, display, width=None, height=None, folder=None):
        self.display = display
        self.width = width if width is not None else display.width
        self.height = height if height is not None else display.height
        self.folder = folder
        self._files = []
        self._frames = []
        self._is_running = False
        self._current_index = 0
        self._loop = 0
        self._current_loop = 0
        self._original_handlers = {}

    def _install_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            self._original_handlers[sig] = signal.signal(sig, self._signal_handler)

    def _restore_signal_handlers(self):
        for sig, handler in self._original_handlers.items():
            try:
                signal.signal(sig, handler)
            except (ValueError, OSError):
                pass
        self._original_handlers.clear()

    def _signal_handler(self, signum, frame):
        logger.info(f"Received signal {signum}; stopping animation.")
        self.stop()
        self._restore_signal_handlers()

    def load_files(self, folder=None):
        if folder is not None:
            self.folder = folder
        if not self.folder:
            raise ValueError("Folder path must be set before loading files.")
        if not os.path.isdir(self.folder):
            raise FileNotFoundError(f"Folder not found: {self.folder}")

        self._files = []
        try:
            for entry in os.listdir(self.folder):
                full_path = os.path.join(self.folder, entry)
                if os.path.isfile(full_path) and entry.lower().endswith('.gif'):
                    try:
                        with Image.open(full_path) as img:
                            img.verify()
                        self._files.append(full_path)
                    except Exception as e:
                        logger.warning(f"Skipping invalid or corrupt GIF: {full_path} - {e}")
        except OSError as e:
            logger.error(f"Error accessing folder {self.folder}: {e}")
            raise

        if not self._files:
            raise FileNotFoundError(f"No valid GIF files found in {self.folder}")
        logger.info(f"Found {len(self._files)} valid GIF files.")

    def preload(self):
        if not self._files:
            raise RuntimeError("No files loaded. Call load_files() first.")

        self._frames = []
        for file_path in self._files:
            try:
                with Image.open(file_path) as img:
                    duration = img.info.get('duration', 100)
                    loop = img.info.get('loop', 0)
                    frames = []
                    for frame in range(img.n_frames):
