import os
import signal
import sys
import time
from PIL import Image

try:
    import lib.epd7in5b as display_driver
except ImportError:
    display_driver = None


class GifPlayer:
    """
    Plays GIF animations on an ST7789 SPI display (240x240) on a Raspberry Pi.

    Uses the lib.epd7in5b driver library to interface with the display.
    """

    DEFAULT_FRAME_DELAY = 100  # milliseconds

    def __init__(self, root_folder, width=240, height=240):
        """
        Initializes the GifPlayer.

        Args:
            root_folder (str): Path to the folder containing GIF files.
            width (int): Display width in pixels.
            height (int): Display height in pixels.
        """
        self.root_folder = root_folder
        self.width = width
        self.height = height
        self.gif_files = []
        self.display = None
        self._running = False

        if not os.path.isdir(self.root_folder):
            raise FileNotFoundError(f"Folder not found: {self.root_folder}")

        self._load_gifs()
        self._initialize_display()

    def _load_gifs(self):
        """Loads all GIF file paths from the root folder."""
        try:
            self.gif_files = [
                os.path.join(self.root_folder, f)
                for f in os.listdir(self.root_folder)
                if f.lower().endswith(".gif")
            ]
            if not self.gif_files:
                raise ValueError(f"No GIF files found in {self.root_folder}")
        except OSError as e:
            raise OSError(f"Error accessing folder {self.root_folder}: {e}")

    def _initialize_display(self):
        """Initializes the display driver."""
        if display_driver is None:
            raise ImportError("lib.epd7in5b library not found.")
        try:
            self.display = display_driver.EPD()
            self.display.init()
        except Exception as e:
            raise RuntimeError(f"Failed to initialize display: {e}")

    def play(self, file_path):
        """
        Plays a single GIF animation on the display.

        Args:
            file_path (str): Path to the GIF file.
        """
        if not os.path.isfile(file_path):
            raise FileNotFoundError(f"GIF file not found: {file_path}")

        try:
            image = Image.open(file_path)
            n_frames = getattr(image, "n_frames", 1)

            for frame in range(n_frames):
                image.seek(frame)
                rgb_image = image.convert("RGB")
                padded_image = Image.new(
                    "RGB", (self.width, self.height), (0, 0, 0)
                )
                offset = (
                    (self.width - rgb_image.width) // 2,
                    (self.height - rgb_image.height) // 2,
                )
                padded_image.paste(rgb_image, offset)

                self.display.display(self.display.getbuffer(padded_image))

                duration = image.info.get("duration", self.DEFAULT_FRAME_DELAY)
                time.sleep(duration / 1000.0)

        except Exception as e:
            raise RuntimeError(f"Error playing GIF {file_path}: {e}")

    def run(self):
        """Runs the GIF animation loop indefinitely."""
        self._running = True
        try:
            while self._running:
                for gif_file in self.gif_files:
                    if not self._running:
                        break
                    self.play(gif_file)
        except KeyboardInterrupt:
            print("\nInterrupted by user.")
        finally:
            self.cleanup()

    def cleanup(self):
        """Releases display resources."""
        self._running = False
        if self.display is not None:
            try:
                self.display.clear()
                self.display.sleep()
            except Exception:
                pass
            self.display = None


def main():
    root_folder = "/home/pi/gifs"
    player = None

    def signal_handler(signum, frame):
        if player is not None:
            player._running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        player = GifPlayer(root_folder)
        player.run()
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        if player is not None:
            player.cleanup()
        sys.exit(1)


if __name__ == "__main__":
    main()

