import time
import datetime
import sqlite3
import logging
import json
import random
import sys
import signal

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

CONFIG_FILE = "config.json"
DATABASE_FILE = "air_quality.db"
LOG_FILE = "air_quality_monitor.log"

logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

DEFAULT_CONFIG = {
    "gpio_button_pin": 17,
    "database_file": DATABASE_FILE,
    "min_update_interval": 300,
    "sensor_error_rate": 0.2,
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        logging.info(f"Configuration loaded from {config_file}")
        return config
    except FileNotFoundError:
        logging.warning(f"Configuration file not found: {config_file}. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in {config_file}: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except Exception as e:
        logging.error(f"Error loading configuration: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()


def init_gpio(button_pin):
    if GPIO is None:
        logging.warning("RPi.GPIO not available; button disabled.")
        return None
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(button_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        logging.info(f"GPIO initialized: pin {button_pin} as input with pull-up.")
        return button_pin
    except Exception as e:
        logging.error(f"Failed to initialize GPIO pin {button_pin}: {e}")
        return None


def read_simulated_sensor(sensor_error_rate):
    if random.random() < sensor_error_rate:
        logging.warning("Simulated sensor error: returning None.")
        return None
    aqi = random.randint(0, 200)
    pm25 = random.uniform(5, 35)
    return aqi, pm25


def store_reading(db_file, timestamp, aqi, pm25):
    try:
        conn = sqlite3.connect(db_file)
        cursor = conn.cursor()
        cursor.execute(
            """
            CREATE TABLE IF NOT EXISTS readings (
                timestamp TEXT PRIMARY KEY,
                aqi INTEGER,
                pm25 REAL
            )
            """
        )
        cursor.execute(
            "INSERT OR REPLACE INTO readings (timestamp, aqi, pm25) VALUES (?, ?, ?)",
            (timestamp, aqi, pm25),
        )
        conn.commit()
        conn.close()
        logging.info(f"Stored reading: {timestamp}, AQI={aqi}, PM2.5={pm25:.2f}")
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")


def classify_aqi(aqi):
    if aqi < 50:
        return "GREEN", "Good"
    elif aqi < 100:
        return "YELLOW", "Moderate"
    elif aqi < 150:
        return "ORANGE", "Unhealthy for Sensitive Groups"
    else:
        return "RED", "Unhealthy"


def display_reading(aqi, pm25, color, health):
    print(f"Simulated e-paper display: AQI={aqi} (Color: {color}), PM2.5={pm25:.2f}")
    print(f"Health: {health}")


def cleanup_gpio(button_pin):
    if GPIO is not None and button_pin is not None:
        try:
            GPIO.cleanup(button_pin)
            logging.info(f"GPIO pin {button_pin} cleaned up.")
        except Exception as e:
            logging.error(f"Error cleaning up GPIO pin {button_pin}: {e}")


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config(CONFIG_FILE)
    button_pin = config.get("gpio_button_pin", DEFAULT_CONFIG["gpio_button_pin"])
    db_file = config.get("database_file", DEFAULT_CONFIG["database_file"])
    min_interval = config.get("min_update_interval", DEFAULT_CONFIG["min_update_interval"])
    sensor_error_rate = config.get("sensor_error_rate", DEFAULT_CONFIG["sensor_error_rate"])

    if not isinstance(button_pin, int) or button_pin < 1 or button_pin > 27:
        logging.error(f"Invalid GPIO pin {button_pin}; must be 1-27. Using default.")
        button_pin = DEFAULT_CONFIG["gpio_button_pin"]

    active_pin = init_gpio(button_pin)
    last_update = 0.0

    try:
        while _running:
            if active_pin is not None:
                try:
                    if GPIO.input(active_pin) == GPIO.LOW:
                        time.sleep(0.2)
                        if GPIO.input(active_pin) == GPIO.LOW:
                            now = time.time()
                            if now - last_update >= min_interval:
                                result = read_simulated_sensor(sensor_error_rate)
                                if result is not None:
                                    aqi, pm25 = result
                                    timestamp = datetime.datetime.now().isoformat()
                                    store_reading(db_file, timestamp, aqi, pm25)
                                    color, health = classify_aqi(aqi)
                                    display_reading(aqi, pm25, color, health)
                                    last_update = now
                                else:
                                    logging.warning("Sensor returned None; skipping update.")
                            else:
                                logging.info("Update skipped: minimum interval not reached.")
                except Exception as e:
                    logging.error(f"Error reading button: {e}")
            else:
                time.sleep(0.5)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup_gpio(active_pin)
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

