# PCF8574 I2C address (A0-A2 tied to GND)
PCF8574_ADDR = 0x20

# Default I2C bus on Raspberry Pi (physical pins 3=SDA, 5=SCL)
I2C_BUS = 1

# Number of sensors
NUM_SENSORS = 8

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def read_pcf8574(bus, addr):
    """Read the 8-bit port from the PCF8574. Returns None on I2C error."""
    try:
        return bus.read_byte(addr)
    except OSError as e:
        print(f"I2C read error (sensor may be absent): {e}")
        return None


def main():
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        while _running:
            port = read_pcf8574(bus, PCF8574_ADDR)

            if port is None:
                # Error reading from PCF8574 (sensor absent or bus error)
                print("Error reading from PCF8574. Check wiring and sensor presence.")
                time.sleep(1)
                continue

            # Check each sensor pin (active-low: LOW = obstacle detected)
            for i in range(NUM_SENSORS):
                if not (port & (1 << i)):
                    print(f"Obstacle detected by sensor {i}")

            time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

