#!/usr/bin/env python3
"""
Clean Energy Monitoring System Simulation for Raspberry Pi 4.

Simulates light and temperature sensors on GPIO17 (BCM) and GPIO4 (BCM)
and monitors the Pi's internal temperature via vcgencmd.
"""

import time
import datetime
import random
import subprocess
import sys
import signal

# Constants
LOW_LIGHT_THRESHOLD = 300  # Lux
HIGH_TEMP_THRESHOLD = 35    # Celsius
HIGH_PI_TEMP_THRESHOLD = 75 # Celsius
SAMPLE_INTERVAL = 5         # Seconds

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def simulate_light_sensor():
    """Simulate a light sensor reading in lux.

    Daylight (06:00-18:00) yields 600-1000 lux;
    Nighttime yields 100-300 lux.
    """
    hour = datetime.datetime.now().hour
    if 6 <= hour < 18:
        return random.randint(600, 1000)
    else:
        return random.randint(100, 300)


def simulate_temperature_sensor():
    """Simulate a temperature sensor reading in Celsius (20-30 °C)."""
    return random.randint(20, 30)


def get_pi_temperature():
    """Read the Pi's internal temperature via vcgencmd.

    Returns:
        float: Temperature in Celsius, or None on error.
    """
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        # Expected output: temp=42.8'C
        temp_str = result.stdout.strip()
        if not temp_str.startswith('temp='):
            print(f"Unexpected vcgencmd output: {temp_str!r}", file=sys.stderr)
            return None
        temp_c_str = temp_str.split('=', 1)[1].split("'", 1)[0]
        return float(temp_c_str)
    except subprocess.TimeoutExpired:
        print("Error: vcgencmd timed out.", file=sys.stderr)
        return None
    except subprocess.CalledProcessError as e:
        print(f"Error: vcgencmd failed (rc={e.returncode}): {e.stderr}", file=sys.stderr)
        return None
    except (ValueError, IndexError) as e:
        print(f"Error parsing vcgencmd output: {e}", file=sys.stderr)
        return None
    except FileNotFoundError:
        print("Error: vcgencmd not found. Is this running on a Raspberry Pi?", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading Pi temperature: {e}", file=sys.stderr)
        return None


def calculate_voltage(light_level):
    """Calculate simulated voltage based on light level.

    light > 300 lux -> 11.5-12.5 V
    otherwise       -> 10.0-11.0 V
    """
    if light_level > 300:
        return round(random.uniform(11.5, 12.5), 2)
    else:
        return round(random.uniform(10.0, 11.0), 2)


def calculate_current(light_level):
    """Calculate simulated current based on light level.

    light > 300 lux -> 1.5-2.5 A
    otherwise       -> 0.5-1.0 A
    """
    if light_level > 300:
        return round(random.uniform(1.5, 2.5), 2)
    else:
        return round(random.uniform(0.5, 1.0), 2)


def log_data(timestamp, light_level, temperature, voltage, current, pi_temp):
    """Log sensor data to stdout."""
    pi_temp_str = f"{pi_temp:.1f}" if pi_temp is not None else "N/A"
    print(
        f"{timestamp} - Light: {light_level} lux, "
        f"Temperature: {temperature} °C, "
        f"Voltage: {voltage} V, "
        f"Current: {current} A, "
        f"Pi Temp: {pi_temp_str} °C"
    )


def check_alerts(light_level, temperature, pi_temp):
    """Check thresholds and print alerts."""
    if light_level < LOW_LIGHT_THRESHOLD:
        print("WARNING: Low light level detected!")
    if temperature > HIGH_TEMP_THRESHOLD:
        print("WARNING: High temperature detected! Simulating cooling activation.")
    if pi_temp is not None and pi_temp > HIGH_PI_TEMP_THRESHOLD:
        print("CRITICAL: High Pi temperature detected! Simulating system shutdown.")


def main():
    """Main loop: simulate sensors, read Pi temp, log, and check alerts."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    print("Clean Energy Monitoring System started. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                light_level = simulate_light_sensor()
            except Exception as e:
                print(f"Error simulating light sensor: {e}", file=sys.stderr)
                light_level = 0

            try:
                temperature = simulate_temperature_sensor()
            except Exception as e:
                print(f"Error simulating temperature sensor: {e}", file=sys.stderr)
                temperature = 0

            try:
                pi_temp = get_pi_temperature()
            except Exception as e:
                print(f"Error reading Pi temperature: {e}", file=sys.stderr)
                pi_temp = None

            voltage = calculate_voltage(light_level)
            current = calculate_current(light_level)

            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            log_data(timestamp, light_level, temperature, voltage, current, pi_temp)
            check_alerts(light_level, temperature, pi_temp)

            # Sleep in small increments to allow prompt signal handling
            slept = 0
            while _running and slept < SAMPLE_INTERVAL:
                time.sleep(0.5)
                slept += 0.5

    except Exception as e:
        print(f"Fatal error in main loop: {e}", file=sys.stderr)
    finally:
        print("Clean Energy Monitoring System stopped.")


if __name__ == "__main__":
    main()

