import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
TIMEOUT = 1
READ_INTERVAL = 0.5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_temperature(ser):
    """Read one line from the serial port and return the first float found."""
    raw = ser.readline()
    if not raw:
        return None
    line = raw.decode('ascii', errors='replace').strip()
    if not line:
        return None
    parts = line.split()
    if not parts:
        return None
    return float(parts[0])

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud")

        while _running:
            try:
                temp = read_temperature(ser)
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                break
            except ValueError:
                print("Error: malformed data received (not a valid float)")
            except Exception as e:
                print(f"Unexpected read error: {e}")
            else:
                if temp is not None:
                    print(f"Temperature: {temp:.1f} C")
            time.sleep(READ_INTERVAL)

    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Fatal error: {e}")
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

