import time
import logging
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT20_I2C_ADDRESS = 0x3C
I2C_BUS_NUMBER = 1
MEASURE_DELAY = 0.08
RETRY_DELAY = 2.0
MAX_RETRIES = 5
STATUS_REG = 0x71
STATUS_READY_MASK = 0x18
STATUS_READY_VALUE = 0x18
DATA_REG = 0x71
CRC_POLYNOMIAL = 0x31
CRC_INIT = 0xFF


class DHT20:
    def __init__(self, i2c_bus_number=I2C_BUS_NUMBER, address=DHT20_I2C_ADDRESS):
        self.address = address
        self.bus = None
        try:
            self.bus = smbus2.SMBus(i2c_bus_number)
            time.sleep(0.5)
            status = self.bus.read_i2c_block_data(self.address, STATUS_REG, 1)[0]
            if (status & STATUS_READY_MASK) != STATUS_READY_VALUE:
                logging.error(f"DHT20 not ready. Status: 0x{status:02X}")
                self.close()
                self.bus = None
        except OSError as e:
            logging.error(f"Failed to initialize DHT20 on bus {i2c_bus_number}: {e}")
            self.bus = None

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            finally:
                self.bus = None

    def __del__(self):
        self.close()

    def _calculate_crc8(self, data):
        crc = CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def read(self):
        if self.bus is None:
            logging.error("DHT20 not initialized.")
            return None, None, True

        for attempt in range(MAX_RETRIES):
            try:
                self.bus.write_byte(self.address, DATA_REG)
                time.sleep(MEASURE_DELAY)

                status = self.bus.read_i2c_block_data(self.address, STATUS_REG, 1)[0]
                if (status & STATUS_READY_MASK) != STATUS_READY_VALUE:
                    logging.warning(f"Attempt {attempt + 1}/{MAX_RETRIES}: DHT20 not ready. Status: 0x{status:02X}")
                    if attempt < MAX_RETRIES - 1:
                        time.sleep(RETRY_DELAY)
                    continue

                data = self.bus.read_i2c_block_data(self.address, DATA_REG, 7)
                if len(data) < 7:
                    logging.error(f"Attempt {attempt + 1}/{MAX_RETRIES}: Incomplete data read ({len(data)} bytes).")
                    if attempt < MAX_RETRIES - 1:
                        time.sleep(RETRY_DELAY)
                    continue

                calculated_crc = self._calculate_crc8(data[:6])
                received_crc = data[6]
                crc_error = calculated_crc != received_crc

                if crc_error:
                    logging.warning(f"Attempt {attempt + 1}/{MAX_RETRIES}: CRC mismatch (calculated: 0x{calculated_crc:02X}, received: 0x{received_crc:02X}).")
                    if attempt < MAX_RETRIES - 1:
                        time.sleep(RETRY_DELAY)
                    continue

                raw_humidity = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
                raw_temperature = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

                humidity = (raw_humidity / 2**20) * 100.0
                temperature = (raw_temperature / 2**20) * 200.0 - 50.0

                logging.info(f"Attempt {attempt + 1}/{MAX_RETRIES}: Temperature = {temperature:.2f}°C, Humidity = {humidity:.2f}%")
                return temperature, humidity, crc_error

            except OSError as e:
                logging.error(f"Attempt {attempt + 1}/{MAX_RETRIES}: I2C bus error: {e}")
                if attempt < MAX_RETRIES - 1:
                    time.sleep(RETRY_DELAY)

        logging.error("Failed to read DHT20 after multiple retries.")
        return None, None, True


if __name__ == "__main__":
    sensor = DHT20()
    if sensor.bus is not None:
        temperature, humidity, crc_error = sensor.read()
        if temperature is not None and humidity is not None:
