import logging
from smbus2 import SMBus, i2c_msg

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the AOSONG DHT20 I2C temperature/humidity sensor."""

    DHT20_I2C_ADDR = 0x3C
    DHT20_STATUS_REG = 0x71
    DHT20_MEASURE_REG = 0xAC
    DHT20_RESET_REG = 0xBA
    DHT20_RESET_CMD = 0x80
    DHT20_STATUS_BUSY = 0x01
    DHT20_STATUS_CRC_ERROR = 0x02
    DHT20_STATUS_DATA_READY = 0x18
    DHT20_INIT_STATUS = 0x18

    CRC8_POLYNOMIAL = 0x31
    CRC8_INIT = 0xFF

    def __init__(self, bus_number=1):
        self.bus = None
        self._closed = False
        try:
            self.bus = SMBus(bus_number)
            logger.info(f"Opened I2C bus {bus_number}")
        except OSError as e:
            logger.error(f"Failed to open I2C bus {bus_number}: {e}")
            self.bus = None
            return

        try:
            status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
            if status != self.DHT20_INIT_STATUS:
                logger.error(
                    f"DHT20 not detected (status=0x{status:02X}, "
                    f"expected 0x{self.DHT20_INIT_STATUS:02X}). "
                    "Attempting reset."
                )
                self._reset()
                time.sleep(0.05)
                status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
                if status != self.DHT20_INIT_STATUS:
                    logger.error(
                        f"DHT20 still not detected after reset "
                        f"(status=0x{status:02X})."
                    )
                    self.close()
                    self.bus = None
                    return
            logger.info("DHT20 sensor detected and initialized.")
        except OSError as e:
            logger.error(f"Error communicating with DHT20: {e}")
            self.close()
            self.bus = None

    def _reset(self):
        try:
            self._write_register(self.DHT20_RESET_REG, [self.DHT20_RESET_CMD])
        except OSError as e:
            logger.error(f"Reset command failed: {e}")
            raise

    def _read_register(self, register, length):
        if self.bus is None:
            raise OSError("I2C bus is not initialized.")
        try:
            write_msg = i2c_msg.write(self.DHT20_I2C_ADDR, [register])
            read_msg = i2c_msg.read(self.DHT20_I2C_ADDR, length)
            self.bus.i2c_rdwr(write_msg, read_msg)
            return list(read_msg)
        except OSError as e:
            logger.error(f"I2C read error at register 0x{register:02X}: {e}")
            raise

    def _write_register(self, register, data):
        if self.bus is None:
            raise OSError("I2C bus is not initialized.")
        try:
            write_msg = i2c_msg.write(self.DHT20_I2C_ADDR, [register] + data)
            self.bus.i2c_rdwr(write_msg)
        except OSError as e:
            logger.error(f"I2C write error at register 0x{register:02X}: {e}")
            raise

    def _calculate_crc8(self, data):
        crc = self.CRC8_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self.CRC8_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def measure(self):
