        while True:
            try:
                status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
            except OSError:
                return None, None, True
            if status & self.DHT20_STATUS_CRC_ERROR:
                logger.warning("CRC error detected during measurement.")
                return None, None, True
            if status & self.DHT20_STATUS_DATA_READY:
                break
            if time.monotonic() - start_time > timeout:
                logger.error("Measurement timed out waiting for data ready.")
                return None, None, True
            time.sleep(0.01)

        try:
            data = self._read_register(0x71, 7)
        except OSError:
            return None, None, True

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

        humidity = (humidity_raw / 2**20) * 100.0
        temperature = (temperature_raw / 2**20) * 200.0 - 50.0

        calculated_crc = self._calculate_crc8(data[:6])
        crc_error = calculated_crc != data[6]
        if crc_error:
            logger.warning("CRC mismatch: calculated=0x%02X, received=0x%02X",
                           calculated_crc, data[6])

        return temperature, humidity, crc_error

    def close(self):
        if self.bus is not None and not self._closed:
            try:
                self.bus.close()
                logger.info("I2C bus closed.")
            except OSError as e:
                logger.error(f"Error closing I2C bus: {e}")
            finally:
                self._closed = True
                self.bus = None


def main():
    sensor = DHT20(bus_number=1)
    if sensor.bus is None:
        logger.error("Failed to initialize DHT20. Exiting.")
        sys.exit(1)

    def signal_handler(signum, frame):
        logger.info(f"Signal {signum} received. Cleaning up...")
        sensor.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        temperature, humidity, crc_error = sensor.measure()
        if crc_error:
            logger.error("Measurement failed due to CRC error.")
        else:
            logger.info(f"Temperature: {temperature:.2f} °C")
            logger.info(f"Humidity: {humidity:.2f} %")
    except Exception as e:
        logger.error(f"Unexpected error during measurement: {e}")
    finally:
        sensor.close()


if __name__ == "__main__":
    main()

