import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Constants
SLEEP_DURATION = 2  # seconds
I2C_RETRY_DELAY = 0.5  # seconds


def initialize_i2c():
    """Initializes the I2C bus using board.SCL and board.SDA."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_multiplexer(i2c_bus):
    """Initializes the TCA9548A I2C multiplexer."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
        return multiplexer
    except Exception as e:
        print(f"Error initializing I2C multiplexer: {e}")
        return None


def initialize_sensors(multiplexer):
    """Initializes the BME280 and TSL2591 sensors."""
    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0], address=0x77)
        tsl2591 = adafruit_tsl2591.TSL2591(multiplexer[1], address=0x29)
        return bme280, tsl2591
    except Exception as e:
        print(f"Error initializing sensors: {e}")
        return None, None


def read_sensor_data(bme280, tsl2591):
    """Reads temperature, humidity, and light intensity from the sensors."""
    try:
        temperature = bme280.temperature
        humidity = bme280.humidity
        light_intensity = tsl2591.lux
        return temperature, humidity, light_intensity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None


def display_sensor_data(temperature, humidity, light_intensity):
    """Displays the sensor data to the console."""
    if temperature is not None and humidity is not None and light_intensity is not None:
        print(f"Temperature: {temperature:.2f} C")
        print(f"Humidity: {humidity:.2f} %")
        print(f"Light Intensity: {light_intensity:.2f} lux")
        print("-" * 20)


def main():
    """Main function to read and display sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280, tsl2591 = initialize_sensors(multiplexer)
    if bme280 is None or tsl2591 is None:
        return

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280, tsl2591)
            display_sensor_data(temperature, humidity, light_intensity)
            time.sleep(SLEEP_DURATION)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        print("Exiting program.")


if __name__ == "__main__":
    main()

