import time
import signal
import sys
from gpiozero import PWMOutputDevice

PIN = 18
FREQ = 50.0
MIN_TEMP = 40.0
MAX_TEMP = 80.0
MIN_DUTY = 25.0
MAX_DUTY = 100.0
POLL_INTERVAL = 1.0

running = True

def _handle_signal(signum, frame):
    global running
    running = False

def read_cpu_temp():
    """Return CPU temperature in °C, or None on error."""
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (OSError, ValueError) as e:
        print(f"[WARN] Could not read CPU temperature: {e}", file=sys.stderr)
        return None

def compute_duty(temp):
    if temp <= MIN_TEMP:
        return MIN_DUTY
    if temp >= MAX_TEMP:
        return MAX_DUTY
    return (temp - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) / (MAX_TEMP - MIN_TEMP) + MIN_DUTY

def main():
    global running
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pwm = PWMOutputDevice(PIN, frequency=FREQ, initial_value=0.0)
    except Exception as e:
        print(f"[ERROR] Failed to initialize PWM on BCM pin {PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            temp = read_cpu_temp()
            if temp is not None:
                duty = compute_duty(temp)
                pwm.value = duty / 100.0
                print(f"CPU: {temp:.1f} °C  ->  Duty: {duty:.1f}%")
            time.sleep(POLL_INTERVAL)
    except KeyboardInterrupt:
        pass
    finally:
        try:
            pwm.value = 0.0
            pwm.close()
        except Exception:
            pass
        print("\nPWM stopped and resources released. Exiting.")

if __name__ == '__main__':
    main()

