import time
import json
import random
import logging
import signal
import sys
import urllib.request
import urllib.error
from collections import deque

try:
    import board
    import adafruit_dht
except ImportError:
    board = None
    adafruit_dht = None

CONFIG_FILE = "config.json"
DHT_PIN = board.D4
READ_INTERVAL = 60
MOVING_AVERAGE_WINDOW = 5
WEBHOOK_RETRY_DELAYS = [1, 3, 9]
MAX_WEBHOOK_RETRIES = 3
PAUSE_DURATION = 300
TEMP_MIN, TEMP_MAX = -40.0, 80.0
HUM_MIN, HUM_MAX = 0.0, 100.0

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

_running = True
_dht_device = None


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received, shutting down...", signum)
    _running = False


def load_config(path):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logger.error("Config file not found: %s", path)
        return None
    except json.JSONDecodeError as e:
        logger.error("Invalid JSON in config: %s", e)
        return None


def init_sensor():
    global _dht_device
    if adafruit_dht is None or board is None:
        logger.warning("adafruit_dht/board not installed; using simulated data.")
        return False
    try:
        _dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
        logger.info("DHT22 initialized on BCM pin 4.")
        return True
    except Exception as e:
        logger.error("Failed to initialize DHT22: %s", e)
        _dht_device = None
        return False


def read_sensor():
    if _dht_device is not None:
        try:
            t = _dht_device.temperature
            h = _dht_device.humidity
            if t is None or h is None:
                raise RuntimeError("Sensor returned None")
            return float(t), float(h)
        except RuntimeError as e:
            logger.warning("DHT22 read error: %s", e)
            return None, None
        except Exception as e:
            logger.error("Unexpected DHT22 error: %s", e)
            return None, None
    return None, None


def validate(t, h):
    if t is None or h is None:
        return False
    if not (TEMP_MIN <= t <= TEMP_MAX):
        logger.warning("Temperature out of range: %.1f", t)
        return False
    if not (HUM_MIN <= h <= HUM_MAX):
        logger.warning("Humidity out of range: %.1f", h)
        return False
    return True


def simulate():
    t = random.uniform(20.0, 30.0)
    h = random.uniform(60.0, 80.0)
    logger.info("Simulated: T=%.1f°C H=%.1f%%", t, h)
    return t, h


def moving_average(data, window):
    if not data:
        return None, None
    if len(data) < window:
        n = len(data)
    else:
        n = window
    ts = [d[0] for d in data[-n:]]
    hs = [d[1] for d in data[-n:]]
    return sum(ts) / n, sum(hs) / n


def send_webhook(url, data):
    payload = json.dumps(data).encode("utf-8")
    req = urllib.request.Request(
        url, data=payload, headers={"Content-Type": "application/json"}
    )
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            if 200 <= resp.status < 300:
                logger.info("Webhook sent successfully (HTTP %d).", resp.status)
                return True
            logger.error("Webhook returned HTTP %d.", resp.status)
            return False
    except urllib.error.HTTPError as e:
        logger.error("Webhook HTTP error: %s", e)
        return False
    except urllib.error.URLError as e:
        logger.error("Webhook URL error: %s", e)
        return False
    except Exception as e:
        logger.error("Webhook send error: %s", e)
        return False


def cleanup():
    global _dht_device
    if _dht_device is not None:
        try:
            _dht_device.exit()
        except Exception:
            pass
        _dht_device = None
    logger.info("Cleanup complete.")


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config(CONFIG_FILE)
    if config is None:
        logger.error("Cannot start without config.")
        sys.exit(1)

    webhook_url = config.get("webhook_url")
    if not webhook_url:
        logger.error("Config missing 'webhook_url'.")
        sys.exit(1)

    sensor_ok = init_sensor()
    if not sensor_ok:
        logger.warning("Sensor unavailable; using simulation.")

    history = deque(maxlen=MOVING_AVERAGE_WINDOW)
    webhook_failures = 0
    paused = False
    pause_until = 0

    try:
        while _running:
            if paused:
                if time.time() >= pause_until:
                    logger.info("Resuming after pause.")
                    paused = False
                    webhook_failures = 0
                else:
                    time.sleep(5)
                continue

            t, h = read_sensor() if sensor_ok else simulate()

            if not validate(t, h):
                t, h = simulate()

            history.append((t, h))
            avg_t, avg_h = moving_average(list(history), MOVING_AVERAGE_WINDOW)

            data = {
                "temperature": round(avg_t, 2),
                "humidity": round(avg_h, 2),
                "timestamp": time.time(),
            }

            success = send_webhook(webhook_url, data)

            if success:
                webhook_failures = 0
            else:
                webhook_failures += 1
                if webhook_failures > MAX_WEBHOOK_RETRIES:
                    logger.warning("Webhook failed %d times; pausing for %d s.",
                                   webhook_failures, PAUSE_DURATION)
                    paused = True
                    pause_until = time.time() + PAUSE_DURATION
                    webhook_failures = 0
                else:
                    for delay in WEBHOOK_RETRY_DELAYS:
                        if not _running:
                            break
                        logger.info("Webhook retry in %d s...", delay)
                        time.sleep(delay)

            if _running:
                time.sleep(READ_INTERVAL)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

