import time
import signal
import sys
import board
import adafruit_dht

# Global sensor handle so signal handler can release it
_sensor = None

def _cleanup(signum=None, frame=None):
    """Release the DHT11 sensor on exit or signal."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None
    if signum is not None:
        sys.exit(0)

def main():
    global _sensor

    # Register signal handlers for clean shutdown on SIGINT / SIGTERM
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    # Initialize the DHT11 sensor on board.D4 (BCM 4, physical pin 7)
    try:
        _sensor = adafruit_dht.DHT11(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 on board.D4: {e}")
        sys.exit(1)

    print("DHT11 sensor initialized on board.D4. Reading every 5 seconds...")

    try:
        while True:
            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity

                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f} C  |  Humidity: {humidity:.1f} %")
                else:
                    print("Sensor returned None for temperature or humidity.")

            except RuntimeError as e:
                # DHT11 reads can occasionally fail due to timing jitter
                print(f"Read error: {e}")

            except Exception as e:
                # Catch-all for unexpected I/O or bus errors
                print(f"Unexpected error during read: {e}")

            # Wait 5 seconds before the next reading
            time.sleep(5)

    finally:
        _cleanup()

if __name__ == "__main__":
    main()

