import time
import signal
import sys
import logging
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

try:
    import adafruit_dht
    import board
except ImportError:
    adafruit_dht = None
    board = None

DHT_PIN = 17
FAN_PIN = 18
LOG_FILE = "urban_data_log.txt"
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
READ_INTERVAL = 2.0
NUM_READINGS = 5

_running = True
_dht_device = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def setup_logging():
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s [%(levelname)s] %(message)s",
    )


def setup_gpio():
    if GPIO is None:
        logging.warning("RPi.GPIO not available; running in emulated mode.")
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)
        logging.info("GPIO initialized: fan pin BCM %d as output (LOW).", FAN_PIN)
    except Exception as exc:
        logging.warning("GPIO setup failed (%s); running in emulated mode.", exc)


def setup_sensor():
    global _dht_device
    if adafruit_dht is None or board is None:
        logging.warning("adafruit_dht/board not available; sensor disabled.")
        return None
    try:
        _dht_device = adafruit_dht.DHT11(board.D17, use_pulseio=False)
        logging.info("DHT11 initialized on BCM pin 17.")
        return _dht_device
    except Exception as exc:
        logging.warning("DHT11 init failed (%s); sensor disabled.", exc)
        _dht_device = None
        return None


def read_sensor(sensor):
    if sensor is None:
        return None, None
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        return temperature, humidity
    except Exception as exc:
        logging.error("Sensor read failed: %s", exc)
        return None, None


def control_fan(temperature, humidity, fan_state):
    if temperature is None or humidity is None:
        logging.warning("Insufficient data; fan state unchanged (%s).",
                        "ON" if fan_state else "OFF")
        return fan_state
    if temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
        if not fan_state:
            logging.info("Fan ON: temp %.1f°C > %.1f°C or humidity %.1f%% > %.1f%%",
                         temperature, TEMP_THRESHOLD, humidity, HUMIDITY_THRESHOLD)
        if GPIO is not None:
            GPIO.output(FAN_PIN, GPIO.HIGH)
        return True
    else:
        if fan_state:
            logging.info("Fan OFF: temp %.1f°C <= %.1f°C and humidity %.1f%% <= %.1f%%",
                         temperature, TEMP_THRESHOLD, humidity, HUMIDITY_THRESHOLD)
        if GPIO is not None:
            GPIO.output(FAN_PIN, GPIO.LOW)
        return False


def log_data(temperature, humidity, fan_state):
    timestamp = datetime.now().isoformat(timespec="seconds")
    status = "Fan ON" if fan_state else "Fan OFF"
    line = f"{timestamp} - Temp: {temperature:.1f}C, Humidity: {humidity:.1f}%, {status}\n"
    try:
        with open(LOG_FILE, "a") as fh:
            fh.write(line)
    except OSError as exc:
        logging.error("Failed to write log file: %s", exc)
    print(line.strip())


def cleanup():
    global _dht_device
    if _dht_device is not None:
        try:
            _dht_device.exit()
        except Exception:
            pass
        _dht_device = None
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass
    logging.info("Resources released.")


def main():
    global _running
    setup_logging()
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    setup_gpio()
    sensor = setup_sensor()
    fan_state = False
    try:
        for i in range(NUM_READINGS):
            if not _running:
                break
            temperature, humidity = read_sensor(sensor)
            fan_state = control_fan(temperature, humidity, fan_state)
            log_data(temperature, humidity, fan_state)
            if i < NUM_READINGS - 1 and _running:
                time.sleep(READ_INTERVAL)
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

