import time
import logging
import smbus2
from typing import Tuple, Optional

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 I2C temperature/humidity sensor."""

    DEFAULT_I2C_BUS = 1
    DEFAULT_I2C_ADDRESS = 0x3C

    def __init__(self, i2c_bus: int = DEFAULT_I2C_BUS, i2c_address: int = DEFAULT_I2C_ADDRESS) -> None:
        self._i2c_bus_number = i2c_bus
        self._i2c_address = i2c_address
        self._bus: Optional[smbus2.SMBus] = None
        self._last_read_time: float = 0.0
        self._min_read_interval: float = 2.0
        self._running = False

    def __enter__(self) -> 'DHT20':
        if not self._running:
            self.begin()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self.close()

    def begin(self) -> bool:
        """Initialize the I2C bus and verify the DHT20 is present."""
        try:
            self._bus = smbus2.SMBus(self._i2c_bus_number)
        except OSError as e:
            logger.error(f"Failed to open I2C bus {self._i2c_bus_number}: {e}")
            return False

        try:
            self._bus.read_byte(self._i2c_address)
        except OSError as e:
            logger.error(f"No DHT20 found at address 0x{self._i2c_address:02X} on bus {self._i2c_bus_number}: {e}")
            self.close()
            return False

        time.sleep(0.5)
        self._running = True
        logger.info(f"DHT20 initialized on bus {self._i2c_bus_number} at address 0x{self._i2c_address:02X}")
        return True

    def close(self) -> None:
        """Release the I2C bus handle."""
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            self._bus = None
        self._running = False

    @staticmethod
    def _calculate_crc8(data: bytes) -> int:
        """Calculate CRC-8 for DHT20 data (polynomial 0x31, init 0xFF)."""
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _read_register(self) -> Optional[bytes]:
        """Trigger a measurement and read 7 bytes from the sensor."""
        if self._bus is None:
            logger.error("I2C bus not initialized")
            return None

        try:
            self._bus.write_byte(self._i2c_address, 0xAC)
            time.sleep(0.08)
            data = self._bus.read_i2c_block_data(self._i2c_address, 0x71, 7)
            return bytes(data)
        except OSError as e:
            logger.warning(f"I2C communication error: {e}")
            return None

    def _parse_data(self, data: bytes) -> Tuple[Optional[float], Optional[float], bool]:
        """Parse 7-byte response; return (temp_c, humidity, error)."""
        if data is None or len(data) != 7:
            return None, None, True

        if self._calculate_crc8(data[:6]) != data[6]:
            logger.warning("CRC mismatch — retrying measurement")
            return None, None, True

        status = data[0]
        if status & 0x80:
            logger.warning(f"Sensor status bit 7 set (0x{status:02X}) — retrying")
            return None, None, True

        raw_temp = ((data[1] << 8) | data[2]) & 0xFFFFF
        raw_hum = ((data[3] << 8) | data[4]) & 0xFFFFF

        humidity = (raw_hum / 2**20) * 100.0
        temperature = (raw_temp / 2**20) * 200.0 - 50.0
        return temperature, humidity, False

    def get_temperature_and_humidity(self) -> Tuple[Optional[float], Optional[float], bool]:
        """
        Read temperature and humidity.

        Returns:
            (temperature_c, humidity, error_flag)
            error_flag is True if all retries failed or CRC is bad.
        """
        now = time.monotonic()
        if now - self._last_read_time < self._min_read_interval:
            logger.debug("Throttling read — minimum interval not elapsed")
            return None, None, True

        for attempt in range(5):
            raw = self._read_register()
            if raw is None:
                logger.warning(f"Read attempt {attempt + 1}/5 failed")
                time.sleep(0.01)
                continue

            temp, hum, err = self._parse_data(raw)
            if not err:
                self._last_read_time = time.monotonic()
                return temp, hum, False

            time.sleep(0.01)

        logger.error("Failed to obtain valid data after 5 attempts")
        return None, None, True


def main() -> int:
    sensor = DHT20(i2c_bus=1, i2c_address=0x3C)
    if not sensor.begin():
        logger.error("DHT20 initialization failed — exiting")
        return 0

    try:
        for _ in range(5):
            temp, hum, err = sensor.get_temperature_and_humidity()
            if err:
                logger.warning("Read returned error")
            else:
                logger.info(f"Temperature: {temp:.2f} °C  |  Humidity: {hum:.2f} %")
            time.sleep(2.0)
    except KeyboardInterrupt:
        logger.info("Interrupted by user")
    except SystemExit:
        logger.info("System exit requested")
    finally:
        sensor.close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

