import time
import board
import busio
import adafruit_ahtx0

# AHT20 valid ranges
TEMP_MIN, TEMP_MAX = -40.0, 85.0
HUM_MIN, HUM_MAX = 0.0, 100.0

# Delay between readings (seconds)
READ_INTERVAL = 5

# Delay between reinitialization attempts (seconds)
REINIT_DELAY = 5


def init_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - I2C init error: {e}")
        return None


def init_sensor(i2c_bus):
    """Initialize the AHT20 sensor on the given I2C bus."""
    try:
        sensor = adafruit_ahtx0.AHTx0(i2c_bus)
        return sensor
    except Exception as e:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Sensor init error: {e}")
        return None


def read_sensor_data(sensor):
    """Read temperature and humidity from the AHT20 sensor.

    Returns (temperature, humidity) or (None, None) on error.
    """
    try:
        temperature = sensor.temperature
        humidity = sensor.relative_humidity
        return temperature, humidity
    except Exception as e:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Sensor read error: {e}")
        return None, None


def validate_data(temperature, humidity):
    """Validate that readings are within plausible ranges."""
    if temperature is None or humidity is None:
        return False
    if not (TEMP_MIN <= temperature <= TEMP_MAX):
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Temperature out of range: {temperature:.1f} C")
        return False
    if not (HUM_MIN <= humidity <= HUM_MAX):
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Humidity out of range: {humidity:.1f} %")
        return False
    return True


def print_data(temperature, humidity):
    """Print the temperature and humidity with a timestamp."""
    print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")


def main():
    """Main loop: initialize, read, validate, print, and handle errors."""
    i2c = init_i2c()
    if i2c is None:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Failed to initialize I2C bus. Exiting.")
        return

    sensor = init_sensor(i2c)
    if sensor is None:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Failed to initialize AHT20 sensor. Exiting.")
        i2c.deinit()
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(sensor)

            if temperature is not None and humidity is not None:
                if validate_data(temperature, humidity):
                    print_data(temperature, humidity)

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Program interrupted by user.")
    except Exception as e:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Unexpected error: {e}")
    finally:
        # Clean up I2C resources
        try:
            i2c.deinit()
        except Exception:
            pass
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - I2C resources released. Exiting.")


if __name__ == "__main__":
    main()

