import time
import datetime
import csv
import os
import fcntl
import random
import signal
import sys
import traceback

try:
    import adafruit_dht
    import board
except ImportError:
    print("Required libraries not installed. Install with:")
    print("  pip install adafruit-circuitpython-dht")
    sys.exit(1)

# Configuration
SENSOR_1_PIN = board.D17
SENSOR_2_PIN = board.D27
HIGH_HUMIDITY_THRESHOLD = 75.0
LOW_HUMIDITY_THRESHOLD = 45.0
HIGH_HUMIDITY_ALERT_COUNT = 3
LOW_HUMIDITY_ALERT_COUNT = 3
ALERT_SUPPRESSION_MINUTES = 30
READ_INTERVAL_SECONDS = 60
MAX_RETRIES = 3
RETRY_DELAY_SECONDS = 2
CLOUD_SUCCESS_RATE = 0.8

# Global state
running = True
last_high_alert_time = {1: None, 2: None}
last_low_alert_time = {1: None, 2: None}

def log_error(message):
    try:
        with open("error.log", "a") as f:
            fcntl.flock(f.fileno(), fcntl.LOCK_EX)
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            f.write(f"{timestamp} - ERROR: {message}\n")
            fcntl.flock(f.fileno(), fcntl.LOCK_UN)
    except Exception as e:
        print(f"CRITICAL: Could not write to error.log: {e}")

def log_alert(message):
    try:
        with open("retail_alerts.log", "a") as f:
            fcntl.flock(f.fileno(), fcntl.LOCK_EX)
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            f.write(f"{timestamp} - ALERT: {message}\n")
            fcntl.flock(f.fileno(), fcntl.LOCK_UN)
    except Exception as e:
        log_error(f"Could not write to retail_alerts.log: {e}")

def log_cloud(message):
    try:
        with open("cloud_log.log", "a") as f:
            fcntl.flock(f.fileno(), fcntl.LOCK_EX)
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            f.write(f"{timestamp} - CLOUD: {message}\n")
            fcntl.flock(f.fileno(), fcntl.LOCK_UN)
    except Exception as e:
        log_error(f"Could not write to cloud_log.log: {e}")

def is_alert_suppressed(sensor_id, alert_type):
    if alert_type == "high":
        last_time = last_high_alert_time[sensor_id]
    else:
        last_time = last_low_alert_time[sensor_id]
    if last_time is None:
        return False
    elapsed = datetime.datetime.now() - last_time
    return elapsed.total_seconds() < ALERT_SUPPRESSION_MINUTES * 60

def update_alert_suppression(sensor_id, alert_type):
    if alert_type == "high":
        last_high_alert_time[sensor_id] = datetime.datetime.now()
    else:
        last_low_alert_time[sensor_id] = datetime.datetime.now()

def read_sensor_data(sensor, sensor_id):
    for attempt in range(MAX_RETRIES):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is None or humidity is None:
                raise RuntimeError("Sensor returned None")
            if not (0 <= humidity <= 100):
                raise ValueError(f"Humidity out of range: {humidity}")
            if not (0 <= temperature <= 35):
                raise ValueError(f"Temperature out of range: {temperature}")
            return temperature, humidity
        except Exception as e:
            log_error(f"Sensor {sensor_id} read attempt {attempt + 1} failed: {e}")
            if attempt < MAX_RETRIES - 1:
                time.sleep(RETRY_DELAY_SECONDS)
    log_error(f"Sensor {sensor_id} failed after {MAX_RETRIES} retries.")
    return None, None

def log_data(timestamp, sensor_id, temperature, humidity):
    filename = f"retail_data_{timestamp.strftime('%Y-%m-%d')}.csv"
    try:
        with open(filename, "a", newline="") as f:
            fcntl.flock(f.fileno(), fcntl.LOCK_EX)
            writer = csv.writer(f)
            if f.tell() == 0:
                writer.writerow(["Timestamp", "Sensor ID", "Temperature (C)", "Humidity (%)"])
            writer.writerow([timestamp.strftime("%Y-%m-%d %H:%M:%S"), sensor_id, temperature, humidity])
            fcntl.flock(f.fileno(), fcntl.LOCK_UN)
    except Exception as e:
        log_error(f"Could not write to {filename}: {e}")

def check_alerts(sensor_id, humidity, high_count, low_count):
    if humidity > HIGH_HUMIDITY_THRESHOLD:
        high_count += 1
        if high_count >= HIGH_HUMIDITY_ALERT_COUNT and not is_alert_suppressed(sensor_id, "high"):
            log_alert(f"High Humidity Alert: Sensor {sensor_id}, Humidity: {humidity:.2f}%")
            update_alert_suppression(sensor_id, "high")
            if random.random() < CLOUD_SUCCESS_RATE:
                log_cloud(f"Simulated Cloud Push: High Humidity Alert for Sensor {sensor_id}")
            high_count = 0
    else:
        high_count = 0

    if humidity < LOW_HUMIDITY_THRESHOLD:
        low_count += 1
        if low_count >= LOW_HUMIDITY_ALERT_COUNT and not is_alert_suppressed(sensor_id, "low"):
            log_alert(f"Low Humidity Alert: Sensor {sensor_id}, Humidity: {humidity:.2f}%")
            update_alert_suppression(sensor_id, "low")
            if random.random() < CLOUD_SUCCESS_RATE:
                log_cloud(f"Simulated Cloud Push: Low Humidity Alert for Sensor {sensor_id}")
            low_count = 0
    else:
        low_count = 0

    return high_count, low_count

def signal_handler(sig, frame):
    global running
    running = False

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        sensor1 = adafruit_dht.DHT22(SENSOR_1_PIN, use_pulseio=False)
        sensor2 = adafruit_dht.DHT22(SENSOR_2_PIN, use_pulseio=False)
    except Exception as e:
        log_error(f"Failed to initialize DHT22 sensors: {e}")
        sys.exit(1)

    high_count1 = 0
    low_count1 = 0
    high_count2 = 0
    low_count2 = 0

    try:
        while running:
            timestamp = datetime.datetime.now()

            temp1, hum1 = read_sensor_data(sensor1, 1)
            if temp1 is not None and hum1 is not None:
                log_data(timestamp, 1, temp1, hum1)
                high_count1, low_count1 = check_alerts(1, hum1, high_count1, low_count1)

            temp2, hum2 = read_sensor_data(sensor2, 2)
            if temp2 is not None and hum2 is not None:
                log_data(timestamp, 2, temp2, hum2)
                high_count2, low_count2 = check_alerts(2, hum2, high_count2, low_count2)

            for _ in range(READ_INTERVAL_SECONDS):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        log_error(f"Unexpected error in main loop: {e}\n{traceback.format_exc()}")
    finally:
        try:
            sensor1.exit()
        except Exception:
            pass
        try:
            sensor2.exit()
        except Exception:
            pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

