    try:
        with open(TEMPERATURE_LOG_FILE, 'a') as f:
            f.write(f'{timestamp}, Temperature: {temperature:.2f} C\n')
    except Exception as e:
        log_error(f'Failed to write to temperature log: {e}')

def send_to_thing speak(temperature):
    """Sends the temperature data to ThingSpeak."""
    try:
        payload = {
            'api_key': THINGSPEAK_API_KEY,
            'field1': temperature
        }
        response = requests.post(
            f'https://api.thingspeak.com/update?api_key={THINGSPEAK_API_KEY}',
            data=payload,
            timeout=10
        )
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        log_error(f'Failed to send data to ThingSpeak: {e}')

def read_temperature():
