            raise RuntimeError('Sensor returned None for temperature')
        return temperature
    except Exception as e:
        log_error(f'Failed to read temperature: {e}')
        # Clean up and recreate sensor on next attempt
        if _sensor is not None:
            try:
                _sensor.exit()
            except Exception:
                pass
            _sensor = None
        return None

def signal_handler(signum, frame):
    """Handles SIGINT and SIGTERM for clean shutdown."""
    global _running
    _running = False

