import serial
import time
import signal
import sys
import numpy as np
import matplotlib.pyplot as plt

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
FRAME_ROWS = 24
FRAME_COLS = 32
EXPECTED_VALUES = FRAME_ROWS * FRAME_COLS
REFRESH_INTERVAL = 0.1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
            xonxoff=False,
            rtscts=False,
            dsrdtr=False,
        )
        if not ser.is_open:
            ser.open()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port {port}: {e}", file=sys.stderr)
        return None

def parse_frame_data(data):
    if not data:
        return None
    try:
        parts = data.split(',')
        if len(parts) != EXPECTED_VALUES:
            return None
        values = [int(p) for p in parts]
        return np.array(values, dtype=np.float32).reshape((FRAME_ROWS, FRAME_COLS))
    except ValueError:
        return None
    except Exception as e:
        print(f"Error parsing data: {e}", file=sys.stderr)
        return None

def update_heatmap(fig, ax, img, data):
    try:
        img.set_data(data)
        ax.set_title(f"Thermal Camera - Max: {data.max():.1f}")
        fig.canvas.draw_idle()
        fig.canvas.flush_events()
    except Exception as e:
        print(f"Error updating heatmap: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if ser is None:
        print("Failed to initialize serial communication. Exiting.", file=sys.stderr)
        sys.exit(1)

    fig, ax = plt.subplots()
    plt.ion()
    img = ax.imshow(np.zeros((FRAME_ROWS, FRAME_COLS)), cmap='inferno', interpolation='nearest', aspect='auto')
    ax.set_title("Thermal Camera - Waiting for data...")
    fig.canvas.draw_idle()
    fig.canvas.flush_events()

    last_frame = None

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                time.sleep(REFRESH_INTERVAL)
                continue
            except Exception as e:
                print(f"Unexpected read error: {e}", file=sys.stderr)
                time.sleep(REFRESH_INTERVAL)
                continue

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            frame = parse_frame_data(line)
            if frame is not None:
                last_frame = frame

            if last_frame is not None:
                update_heatmap(fig, ax, img, last_frame)

            time.sleep(REFRESH_INTERVAL)

    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        try:
            if ser and ser.is_open:
                ser.close()
                print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}", file=sys.stderr)
        try:
            plt.ioff()
            plt.close(fig)
        except Exception as e:
            print(f"Error closing plot: {e}", file=sys.stderr)
        print("Program terminated.")

if __name__ == "__main__":
    main()

