import time
import logging
import logging.handlers
import random
import os
import signal
import sys
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

DHT_PIN = 4
LOG_FILE = '/var/log/wearable/wearable.log'
FALLBACK_LOG_FILE = os.path.join(os.path.expanduser('~'), '.local', 'log', 'wearable.log')
LOG_LEVEL = logging.INFO
RETRY_DELAY = 1
MAX_RETRIES = 3
READ_INTERVAL = 5
TEMP_MIN, TEMP_MAX = 10, 55
HUM_MIN, HUM_MAX = 20, 100

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_logging():
    log_dir = os.path.dirname(LOG_FILE)
    if log_dir and not os.path.isdir(log_dir):
        try:
            os.makedirs(log_dir, exist_ok=True)
        except OSError:
            log_dir = os.path.dirname(FALLBACK_LOG_FILE)
            if log_dir:
                os.makedirs(log_dir, exist_ok=True)
    log_file = LOG_FILE if os.access(log_dir, os.W_OK) else FALLBACK_LOG_FILE
    handler = logging.handlers.TimedRotatingFileHandler(
        log_file, when='midnight', interval=1, backupCount=7
    )
    handler.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(message)s'))
    logger = logging.getLogger()
    logger.setLevel(LOG_LEVEL)
    logger.addHandler(handler)
    return logger

def setup_gpio():
    if GPIO is None:
        logging.warning('RPi.GPIO not available; running in simulation-only mode.')
        return None
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        logging.info(f'GPIO pin {DHT_PIN} configured as input for DHT22 simulation.')
        return DHT_PIN
    except Exception as e:
        logging.error(f'Failed to initialize GPIO: {e}')
        return None

def read_dht22(pin):
    if pin is None:
        return None, None
    try:
        temp = random.uniform(TEMP_MIN, TEMP_MAX)
        hum = random.uniform(HUM_MIN, HUM_MAX)
        if random.random() < 0.1:
            return None, None
        return temp, hum
    except Exception as e:
        logging.error(f'Error reading DHT22: {e}')
        return None, None

def validate_data(temp, hum):
    try:
        t = float(temp)
        h = float(hum)
        if not (TEMP_MIN <= t <= TEMP_MAX):
            logging.error(f'Temperature out of range: {t}')
            return False
        if not (HUM_MIN <= h <= HUM_MAX):
            logging.error(f'Humidity out of range: {h}')
            return False
        return True
    except (TypeError, ValueError) as e:
        logging.error(f'Invalid data type: {e}')
        return False

def cleanup_gpio(pin):
    if GPIO is not None and pin is not None:
        try:
            GPIO.cleanup(pin)
            logging.info('GPIO resources released.')
        except Exception as e:
            logging.error(f'Error during GPIO cleanup: {e}')

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    logger = setup_logging()
    logger.info('Wearable sensor simulation started.')
    pin = setup_gpio()
    try:
        while _running:
            temp, hum = None, None
            for attempt in range(1, MAX_RETRIES + 1):
                temp, hum = read_dht22(pin)
                if temp is not None and hum is not None:
                    break
                logging.warning(f'Read attempt {attempt}/{MAX_RETRIES} failed; retrying in {RETRY_DELAY}s.')
                time.sleep(RETRY_DELAY)
            if temp is None or hum is None:
                logging.error('Failed to read DHT22 after maximum retries.')
            else:
                if validate_data(temp, hum):
                    ts = datetime.now().isoformat()
                    logger.info(f'Timestamp: {ts}, Temperature: {temp:.2f}C, Humidity: {hum:.2f}%')
