import sys
import time
import signal
import threading
from typing import Optional

try:
    import DOG
except ImportError:
    print("Error: DOG library not found. Please ensure it is installed.")
    sys.exit(1)

# Global state
_running = False
_receive_thread: Optional[threading.Thread] = None
_log_file: Optional[str] = None
_lock = threading.Lock()


def _cleanup() -> None:
    """Stop the DOG API call and wait for the receive thread to finish."""
    global _running, _receive_thread

    if _receive_thread is not None and _receive_thread.is_alive():
        _running = False
        _receive_thread.join(timeout=2.0)
        if _receive_thread.is_alive():
            print("Warning: receive thread did not terminate cleanly.")

    try:
        DOG.stop()
    except Exception as e:
        print(f"Warning: DOG.stop() failed: {e}")


def _signal_handler(signum, frame) -> None:
    """Handle SIGINT/SIGTERM by stopping DOG and exiting."""
    print(f"\nReceived signal {signum}, shutting down...")
    _cleanup()
    sys.exit(0)


def _receive_loop() -> None:
    """Continuously receive data from DOG and log it to the file."""
    global _running, _log_file

    while _running:
        try:
            data = DOG.receive()
            if data is not None:
                with _lock:
                    if _log_file:
                        try:
                            with open(_log_file, "a") as f:
                                f.write(str(data) + "\n")
                        except OSError as e:
                            print(f"Error writing to log file: {e}")
        except Exception as e:
            print(f"Error during receive: {e}")
            time.sleep(0.1)
        time.sleep(0.1)


def _start_receive(filename: str) -> None:
    """Start the receive thread and the DOG API call."""
    global _running, _receive_thread, _log_file

    if _running:
        print("Receive is already running.")
        return

    try:
        DOG.start()
    except Exception as e:
        print(f"Error starting DOG API: {e}")
        return

    _log_file = filename
    _running = True
    _receive_thread = threading.Thread(target=_receive_loop, daemon=True)
    _receive_thread.start()
    print(f"Receiving data and logging to '{filename}'...")


def _stop_receive() -> None:
    """Stop the receive thread and the DOG API call."""
    global _running, _receive_thread

    if not _running:
        print("Receive is not running.")
        return

    _running = False
    if _receive_thread is not None and _receive_thread.is_alive():
        _receive_thread.join(timeout=2.0)
        if _receive_thread.is_alive():
            print("Warning: receive thread did not terminate cleanly.")

    try:
        DOG.stop()
    except Exception as e:
        print(f"Error stopping DOG API: {e}")

    _receive_thread = None
    _log_file = None
    print("Receive stopped.")


def _display_log() -> None:
    """Display the contents of the log file."""
    global _log_file

    if not _log_file:
        print("No log file is currently active.")
        return

    try:
        with open(_log_file, "r") as f:
            content = f.read()
        if content:
            print(content)
        else:
            print("Log file is empty.")
    except FileNotFoundError:
        print(f"Log file not found: {_log_file}")
    except OSError as e:
        print(f"Error reading log file: {e}")


def _send_data(data: str) -> None:
    """Send data via DOG.send()."""
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def _write_to_log(data: str) -> None:
    """Append data directly to the log file."""
    global _log_file

    if not _log_file:
        print("No log file is currently active.")
        return

    try:
        with open(_log_file, "a") as f:
            f.write(data + "\n")
        print(f"Wrote to log: {data}")
    except OSError as e:
        print(f"Error writing to log file: {e}")


def _help(command: Optional[str] = None) -> None:
    """Display help information for commands."""
    help_messages = {
        "help": "Call 'help <command>' to see information about the command.\nCommands:\n\t-display\n\t-help\n\t-send\n\t-start\n\t-stop\n\t-write\n\t-exit",
        "start": "Help for 'start':\nStarts receiving data and logs it to a file.\nUsage: start <filename>",
        "stop": "Help for 'stop':\nStops receiving data.",
        "exit": "Help for 'exit':\nCloses this window.",
        "display": "Help for 'display':\nDisplays the contents of the current log file.",
        "send": "Help for 'send':\nSends the following data using DOG.send().\nUsage: send <data>",
        "write": "Help for 'write':\nWrites the following string directly to the log file.\nUsage: write <data>",
    }

    if command:
        print(help_messages.get(command, "No help found for this command."))
    else:
        print(help_messages["help"])


def _process_command(command: str) -> None:
    """Parse and execute a user command."""
    parts = command.split()
    if not parts:
        return

    cmd = parts[0].lower()

    if cmd == "help":
        _help(parts[1] if len(parts) > 1 else None)
    elif cmd == "start":
        if len(parts) < 2:
            print("Error: 'start' command requires a filename argument.")
            return
        _start_receive(parts[1])
    elif cmd == "stop":
        _stop_receive()
    elif cmd == "exit":
        _cleanup()
        sys.exit(0)
    elif cmd == "display":
        _display_log()
    elif cmd == "send":
        if len(parts) < 2:
            print("Error: 'send' command requires data to send.")
            return
        _send_data(" ".join(parts[1:]))
    elif cmd == "write":
        if len(parts) < 2:
            print("Error: 'write' command requires data to write.")
            return
        _write_to_log(" ".join(parts[1:]))
    else:
        print(f"Unknown command: {cmd}. Try 'help'.")


def main() -> None:
    """Main entry point: initialize GPIO, register signal handlers, and run the CLI."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize DOG GPIO (required by the library)
    try:
        DOG.setup()
    except Exception as e:
        print(f"Fatal: Failed to initialize DOG GPIO: {e}")
        sys.exit(1)

    print("DOG CLI ready. Type 'help' for commands.")

    try:
        while True:
            try:
                command = input("> ")
                _process_command(command)
            except EOFError:
                print("\nEOF received, exiting.")
                break
            except Exception as e:
                print(f"An error occurred: {e}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

