import asyncio
import json
import logging
import os
import signal
import time
import urllib.request
import urllib.error
import psutil
import pyaudio
import tflite_runtime.interpreter as tflite
from gpiozero import LED
from collections import deque

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DEFAULT_CONFIG = {
    "sampling_rate": 16000,
    "chunk_size": 1024,
    "vad_sensitivity": 0.5,
    "keywords": ["hello", "goodbye"],
    "sentiment_thresholds": {"positive": 0.7, "negative": -0.7},
    "led_pin": 17,
    "cloud_endpoint": None,
    "heartbeat_interval": 60,
    "config_update_interval": 300,
    "resource_log_interval": 60,
    "model_path": "model.tflite",
    "metadata_path": "metadata.json"
}

class ConfigManager:
    def __init__(self, config_file="config.json"):
        self.config_file = config_file
        self.config = DEFAULT_CONFIG.copy()
        self.load_config()

    def load_config(self):
        try:
            with open(self.config_file, "r") as f:
                loaded = json.load(f)
                self.config.update(loaded)
            logging.info("Configuration loaded from %s", self.config_file)
        except FileNotFoundError:
            logging.warning("Configuration file not found. Using default settings.")
        except json.JSONDecodeError:
            logging.error("Invalid JSON format in configuration file. Using default settings.")
        except Exception as e:
            logging.error("Error loading configuration: %s. Using default settings.", e)

    def get_config(self):
        return self.config

    def save_config(self, config):
        try:
            with open(self.config_file, "w") as f:
                json.dump(config, f, indent=4)
            logging.info("Configuration saved to %s", self.config_file)
        except Exception as e:
            logging.error("Error saving configuration: %s", e)

class AudioProcessor:
    def __init__(self, config):
        self.config = config
        self.audio = pyaudio.PyAudio()
        self.stream = None
        self.running = True

    def start_stream(self):
        try:
            self.stream = self.audio.open(
                format=pyaudio.paInt16,
                channels=1,
                rate=self.config["sampling_rate"],
                input=True,
                frames_per_buffer=self.config["chunk_size"]
            )
            logging.info("Audio stream started.")
        except Exception as e:
            logging.error("Error starting audio stream: %s", e)
            self.stream = None

    def stop_stream(self):
        if self.stream:
            try:
                self.stream.stop_stream()
                self.stream.close()
                logging.info("Audio stream stopped.")
            except Exception as e:
                logging.error("Error stopping audio stream: %s", e)
            finally:
                self.stream = None

    def read_audio_data(self):
        if self.stream:
            try:
                data = self.stream.read(self.config["chunk_size"], exception_on_overflow=False)
                return data
            except Exception as e:
                logging.error("Error reading audio data: %s", e)
                return None
        return None

    def detect_speech(self, audio_data):
        try:
            energy = sum(abs(byte) for byte in audio_data) / len(audio_data)
            threshold = self.config["vad_sensitivity"] * 32768
            return energy > threshold
        except Exception as e:
            logging.error("Error detecting speech: %s", e)
            return False

    def cleanup(self):
        self.stop_stream()
        self.audio.terminate()
        logging.info("Audio processor cleaned up.")

class KeywordSpotter:
    def __init__(self, config, model_path, metadata_path):
        self.config = config
        self.keywords = self.config["keywords"]
        self.interpreter = None
        self.input_details = None
        self.output_details = None
        self.load_model(model_path, metadata_path)

    def load_model(self, model_path, metadata_path):
        try:
            if not os.path.exists(model_path):
                raise FileNotFoundError(f"Model file not found: {model_path}")
            self.interpreter = tflite.Interpreter(model_path=model_path)
            self.interpreter.allocate_tensors()
            self.input_details = self.interpreter.get_input_details()
            self.output_details = self.interpreter.get_output_details()
            logging.info("Keyword spotting model loaded successfully.")
        except FileNotFoundError as e:
            logging.error(str(e))
        except Exception as e:
            logging.error("Error loading keyword spotting model: %s", e)

    def spot_keyword(self, audio_data):
        if not self.interpreter:
            return None
        try:
            input_data = self.preprocess_audio(audio_data)
            self.interpreter.set_tensor(self.input_details[0]['index'], input_data)
            self.interpreter.invoke()
            output_data = self.interpreter.get_tensor(self.output_details[0]['index'])
            detected_keyword = self.postprocess_output(output_data)
            return detected_keyword
        except Exception as e:
            logging.error("Error during keyword spotting: %s", e)
            return None

    def preprocess_audio(self, audio_data):
        try:
            import numpy as np
            audio_int16 = np.frombuffer(audio_data, dtype=np.int16)
            audio_float32 = audio_int16.astype(np.float32) / 32768.0
            return audio_float32.reshape(1, -1)
        except Exception as e:
            logging.error("Error preprocessing audio: %s", e)
            return None

    def postprocess_output(self, output_data):
        try:
            predicted_index = int(output_data[0].argmax())
            if 0 <= predicted_index < len(self.keywords):
                return self.keywords[predicted_index]
            return None
        except Exception as e:
            logging.error("Error postprocessing output: %s", e)
            return None

class SentimentAnalyzer:
    def __init__(self, config, model_path, metadata_path):
        self.config = config
        self.interpreter = None
        self.input_details = None
        self.output_details = None
        self.load_model(model_path, metadata_path)
        self.sentiment_history = deque(maxlen=10)

    def load_model(self, model_path, metadata_path):
        try:
            if not os.path.exists(model_path):
                raise FileNotFoundError(f"Model file not found: {model_path}")
            self.interpreter = tflite.Interpreter(model_path=model_path)
            self.interpreter.allocate_tensors()
            self.input_details = self.interpreter.get_input_details()
            self.output_details = self.interpreter.get_output_details()
            logging.info("Sentiment analysis model loaded successfully.")
        except FileNotFoundError as e:
            logging.error(str(e))
        except Exception as e:
            logging.error("Error loading sentiment analysis model: %s", e)

    def analyze_sentiment(self, audio_data):
        if not self.interpreter:
            return 0.0
        try:
            input_data = self.preprocess_audio(audio_data)
            self.interpreter.set_tensor(self.input_details[0]['index'], input_data)
            self.interpreter.invoke()
            output_data = self.interpreter.get_tensor(self.output_details[0]['index'])
            sentiment_score = self.postprocess_output(output_data)
            self.sentiment_history.append(sentiment_score)
            return sum(self.sentiment_history) / len(self.sentiment_history)
        except Exception as e:
            logging.error("Error during sentiment analysis: %s", e)
            return 0.0

    def preprocess_audio(self, audio_data):
        try:
            import numpy as np
            audio_int16 = np.frombuffer(audio_data, dtype=np.int16)
            audio_float32 = audio_int16.astype(np.float32) / 32768.0
            return audio_float32.reshape(1, -1)
        except Exception as e:
            logging.error("Error preprocessing audio: %s", e)
            return None

    def postprocess_output(self, output_data):
        try:
            return float(output_data[0][0])
        except Exception as e:
            logging.error("Error postprocessing output: %s", e)
            return 0.0

class AlertManager:
    def __init__(self, config):
        self.config = config
        self.led = LED(config["led_pin"])
        self.alert_triggered = False

    def trigger_alert(self, sentiment_score):
        try:
            thresholds = self.config["sentiment_thresholds"]
            if sentiment_score > thresholds["positive"] and not self.alert_triggered:
                self.led.on()
                self.alert_triggered = True
                logging.warning("Positive sentiment threshold exceeded! LED activated.")
                if self.config["cloud_endpoint"]:
                    asyncio.create_task(self.send_cloud_alert("positive"))
            elif sentiment_score < thresholds["negative"] and not self.alert_triggered:
                self.led.on()
                self.alert_triggered = True
                logging.warning("Negative sentiment threshold exceeded! LED activated.")
                if self.config["cloud_endpoint"]:
                    asyncio.create_task(self.send_cloud_alert("negative"))
        except Exception as e:
            logging.error("Error triggering alert: %s", e)

    def reset_alert(self):
        try:
            self.led.off()
            self.alert_triggered = False
            logging.info("Alert reset. LED deactivated.")
        except Exception as e:
            logging.error("Error resetting alert: %s", e)

    async def send_cloud_alert(self, sentiment):
        try:
            import aiohttp
            async with aiohttp.ClientSession() as session:
                payload = {"sentiment": sentiment, "timestamp": time.time()}
                async with session.post(self.config["cloud_endpoint"], json=payload) as response:
                    if response.status == 200:
                        logging.info("Cloud alert sent successfully.")
                    else:
                        logging.error("Failed to send cloud alert. Status code: %s", response.status)
        except Exception as e:
            logging.error("Error sending cloud alert: %s", e)

    def cleanup(self):
        self.led.close()
        logging.info("Alert manager cleaned up.")

async def heartbeat(config):
    while True:
        logging.info("Heartbeat signal sent.")
        await asyncio.sleep(config["heartbeat_interval"])

async def check_config_updates(config_manager):
    while True:
        try:
            with urllib.request.urlopen("http://example.com/config.json") as response:
                if response.status == 200:
                    updated_config = json.loads(response.read().decode())
                    config_manager.save_config(updated_config)
                    logging.info("Remote configuration updated.")
        except urllib.error.URLError as e:
            logging.warning("Failed to check for configuration updates: %s", e)
        except json.JSONDecodeError:
            logging.error("Invalid JSON format in remote configuration.")
        except Exception as e:
            logging.error("Error checking for configuration updates: %s", e)
        await asyncio.sleep(config_manager.get_config()["config_update_interval"])

async def log_resource_usage():
    while True:
        try:
            cpu_percent = psutil.cpu_percent()
            memory_percent = psutil.virtual_memory().percent
            logging.info("CPU Usage: %.2f%%, Memory Usage: %.2f%%", cpu_percent, memory_percent)
        except Exception as e:
            logging.error("Error logging resource usage: %s", e)
        await asyncio.sleep(60)

async def main():
    config_manager = ConfigManager()
    config = config_manager.get_config()

    audio_processor = AudioProcessor(config)
    audio_processor.start_stream()

    keyword_spotter = KeywordSpotter(config, config["model_path"], config["metadata_path"])
    sentiment_analyzer = SentimentAnalyzer(config, config["model_path"], config["metadata_path"])
    alert_manager = AlertManager(config)

    tasks = [
        asyncio.create_task(heartbeat(config)),
        asyncio.create_task(check_config_updates(config_manager)),
        asyncio.create_task(log_resource_usage())
    ]

    try:
        while True:
            audio_data = audio_processor.read_audio_data()
            if audio_data:
                if audio_processor.detect_speech(audio_data):
                    detected_keyword = keyword_spotter.spot_keyword(audio_data)
                    if detected_keyword:
                        logging.info("Detected keyword: %s", detected_keyword)
                    sentiment_score = sentiment_analyzer.analyze_sentiment(audio_data)
                    alert_manager.trigger_alert(sentiment_score)
                    if sentiment_score < 0.1 and sentiment_score > -0.1:
                        alert_manager.reset_alert()
            await asyncio.sleep(0.1)
    except asyncio.CancelledError:
        pass
    finally:
        for task in tasks:
            task.cancel()
        audio_processor.cleanup()
        alert_manager.cleanup()
        logging.info("Application shutdown complete.")

if __name__ == "__main__":
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)

    def signal_handler(sig, frame):
        logging.info("Shutdown signal received.")
        for task in asyncio.all_tasks(loop):
            task.cancel()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        loop.run_until_complete(main())
    except KeyboardInterrupt:
        pass
    finally:
        loop.close()

