    "enjoy": 0.6, "bored": -0.4, "fun": 0.6, "boring": -0.4,
    "happy": 0.7, "sad": -0.6, "angry": -0.7, "calm": 0.5,
    "love": 0.8, "hate": -0.8, "like": 0.6, "dislike": -0.6,
    "enjoy": 0.7, "bored": -0.5, "fun": 0.8, "boring": -0.5,
    "happy": 0.8, "sad": -0.7, "angry": -0.8, "calm": 0.6,
}

POSITIVE_LED_PIN = 17
NEGATIVE_LED_PIN = 18

_initialized = False

def cleanup_gpio():
    global _initialized
    if _initialized and GPIO is not None:
        try:
            GPIO.output(POSITIVE_LED_PIN, GPIO.LOW)
            GPIO.output(NEGATIVE_LED_PIN, GPIO.LOW)
        except Exception:
            pass
        try:
            GPIO.cleanup()
        except Exception:
            pass
        _initialized = False

def setup_gpio():
    global _initialized
    if GPIO is None:
        return
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(POSITIVE_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(NEGATIVE_LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    _initialized = True

def analyze_sentiment(text):
    tokens = text.lower().split()
    scores = [vader_lexicon.get(word, 0.0) for word in tokens]
    if not scores:
        return 0.0
    return sum(scores) / len(scores)

