import time
import signal
import sys
import logging
from datetime import datetime, timezone

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)


class PIRSensor:
    """Thin wrapper around a GPIO pin reading for the HC-SR501 PIR OUT line.

    No third-party driver library is required; the class is hardware-agnostic
    and can be backed by a real GPIO library (e.g. RPi.GPIO, gpiozero, or a
    mock for testing).
    """

    def __init__(self, pin: int, backend=None):
        self.pin = pin
        self._backend = backend
        self._closed = False
        try:
            if backend is not None:
                backend.setup(pin, backend.IN)
            logger.info("PIR sensor initialized on GPIO %d", pin)
        except Exception as exc:
            logger.error("Failed to initialize PIR sensor on GPIO %d: %s", pin, exc)
            raise

    def read(self) -> bool:
        """Return True if motion is detected (OUT pin is HIGH)."""
        if self._closed:
            raise RuntimeError("Sensor has been closed")
        try:
            if self._backend is not None:
                return bool(self._backend.input(self.pin))
            # Mock backend: return True to simulate motion
            return True
        except Exception as exc:
            logger.error("Error reading PIR sensor on GPIO %d: %s", self.pin, exc)
            return False

    def close(self):
        if not self._closed:
            self._closed = True
            if self._backend is not None:
                try:
                    self._backend.cleanup(self.pin)
                except Exception as exc:
                    logger.warning("Error during GPIO cleanup: %s", exc)


class OccupancyMonitor:
    """PIR-based occupancy monitor with debounce and event logging."""

    def __init__(
        self,
        sensor: PIRSensor,
        sample_count: int = 10,
        debounce_seconds: float = 2.0,
        poll_interval: float = 0.5,
    ):
        if sample_count <= 0:
            raise ValueError("sample_count must be a positive integer")
        if debounce_seconds < 0:
            raise ValueError("debounce_seconds must be non-negative")
        if poll_interval <= 0:
            raise ValueError("poll_interval must be positive")

        self.sensor = sensor
        self.sample_count = sample_count
        self.debounce_seconds = debounce_seconds
        self.poll_interval = poll_interval
        self.detection_times: list[str] = []
        self._running = True

    def _handle_signal(self, signum, frame):
        logger.info("Received signal %d, shutting down gracefully...", signum)
        self._running = False

    def monitor(self):
        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGTERM, self._handle_signal)

        last_detection_time: float | None = None
        samples_taken = 0

        try:
            while self._running and samples_taken < self.sample_count:
                try:
                    motion_detected = self.sensor.read()
                except RuntimeError as exc:
                    logger.error("Sensor read failed: %s", exc)
                    break

                if motion_detected:
                    now = time.monotonic()
                    if last_detection_time is None or (
                        now - last_detection_time >= self.debounce_seconds
                    ):
                        timestamp = datetime.now(timezone.utc).isoformat()
                        self.detection_times.append(timestamp)
                        last_detection_time = now
                        logger.info("Motion detected at %s", timestamp)

                samples_taken += 1
                time.sleep(self.poll_interval)

        except Exception as exc:
            logger.error("Unexpected error during monitoring: %s", exc)
        finally:
            self.sensor.close()

    def get_occupancy_stats(self) -> dict:
        return {
            "total_detections": len(self.detection_times),
            "detection_times": self.detection_times,
        }

    def print_occupancy_report(self):
        stats = self.get_occupancy_stats()
        print("=== Occupancy Report ===")
        print(f"Total Detections: {stats['total_detections']}")
        if stats["detection_times"]:
            print("Detection Times:")
            for ts in stats["detection_times"]:
                print(f"  - {ts}")
        else:
            print("No detections recorded.")
        print("========================")


def main():
    PIR_PIN = 17
    try:
        sensor = PIRSensor(PIR_PIN)
    except Exception:
        logger.error("Could not initialize PIR sensor. Exiting.")
        sys.exit(1)

    monitor = OccupancyMonitor(
        sensor,
        sample_count=10,
        debounce_seconds=2.0,
        poll_interval=0.5,
    )
    monitor.monitor()
    monitor.print_occupancy_report()
    sys.exit(0)


if __name__ == "__main__":
    main()

