import time
import board
import busio
import adafruit_fingerprint

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
I2C_SCL_PIN = board.SCL   # GPIO 3 (physical pin 5)
I2C_SDA_PIN = board.SDA   # GPIO 2 (physical pin 3)
RETRY_DELAY_S = 1.0       # delay between authentication attempts

# ---------------------------------------------------------------------------
# Resource handles (created in setup, closed in finally)
# ---------------------------------------------------------------------------
i2c_bus = None
fingerprint_sensor = None


def initialize_i2c():
    """Initialize the I2C bus on SCL / SDA."""
    global i2c_bus
    try:
        i2c_bus = busio.I2C(I2C_SCL_PIN, I2C_SDA_PIN)
        print("I2C bus initialized on SCL={}, SDA={}".format(
            I2C_SCL_PIN, I2C_SDA_PIN))
    except Exception as exc:
        print("Error initializing I2C bus: {}".format(exc))
        raise


def initialize_fingerprint_sensor():
    """Initialize the Adafruit fingerprint sensor over the I2C bus."""
    global fingerprint_sensor
    try:
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        print("Fingerprint sensor initialized.")
    except ValueError as exc:
        print("I2C bus is locked or sensor not responding: {}".format(exc))
        raise
    except Exception as exc:
        print("Error initializing fingerprint sensor: {}".format(exc))
        raise


def read_fingerprint_image():
    """
    Acquire a fingerprint image from the sensor.
    Returns True on success, False on NOFINGER, ValueError on I2C lock,
    or RuntimeError on any other sensor failure.
    """
    try:
        print("Waiting for finger...")
        while True:
            try:
                ret = fingerprint_sensor.get_image()
            except ValueError as exc:
                print("I2C bus locked during get_image(): {}".format(exc))
                raise
            except Exception as exc:
                print("Unexpected error during get_image(): {}".format(exc))
                raise

            if ret == adafruit_fingerprint.OK:
                return True
            if ret == adafruit_fingerprint.NOFINGER:
                return False
            # Any other status code is treated as a transient error
            print("get_image() status={}, retrying...".format(ret))
            time.sleep(0.1)
    except ValueError:
        raise
    except Exception as exc:
        print("Error reading fingerprint image: {}".format(exc))
        raise


def create_fingerprint_template():
    """Convert the acquired image to a template. Returns True on success."""
    try:
        print("Templating...")
        ret = fingerprint_sensor.image_2_tz(1)
        if ret != adafruit_fingerprint.OK:
            print("image_2_tz() failed with status={}".format(ret))
            return False
        return True
    except ValueError as exc:
        print("I2C bus locked during image_2_tz(): {}".format(exc))
        raise
    except Exception as exc:
        print("Error creating template: {}".format(exc))
        raise


def search_fingerprint_database():
    """
    Search the fingerprint database for a match.
    Returns (True, id, confidence) on a match, (False, None, None) otherwise.
    """
    try:
        print("Searching database...")
        ret = fingerprint_sensor.finger_search()
        if ret == adafruit_fingerprint.OK:
            print("Match found! ID={}, confidence={}".format(
                fingerprint_sensor.finger_id,
                fingerprint_sensor.confidence))
            return True, fingerprint_sensor.finger_id, fingerprint_sensor.confidence
        if ret == adafruit_fingerprint.NOTFOUND:
            print("No match found.")
            return False, None, None
        print("finger_search() status={}".format(ret))
        return False, None, None
    except ValueError as exc:
        print("I2C bus locked during finger_search(): {}".format(exc))
        raise
    except Exception as exc:
        print("Error searching database: {}".format(exc))
        raise


def authenticate_user():
    """
    Authenticate a single fingerprint.
    Returns True on a successful match, False otherwise.
    """
    try:
        if not read_fingerprint_image():
            return False
        if not create_fingerprint_template():
            return False
        matched, _id, _conf = search_fingerprint_database()
        if matched:
            print("Access Granted")
        else:
            print("Access Denied")
        return matched
    except ValueError:
        raise
    except Exception as exc:
        print("Authentication error: {}".format(exc))
        return False


def main():
    """Main loop: authenticate users until interrupted."""
    global i2c_bus, fingerprint_sensor
    try:
        initialize_i2c()
        initialize_fingerprint_sensor()

        while True:
            try:
                authenticate_user()
            except ValueError:
                print("I2C bus error; retrying in {}s...".format(RETRY_DELAY_S))
            except Exception as exc:
                print("Unexpected error during authentication: {}".format(exc))
            time.sleep(RETRY_DELAY_S)

    except KeyboardInterrupt:
        print("\nExiting program (KeyboardInterrupt).")
    except ValueError:
        print("Fatal: I2C bus unavailable. Exiting.")
    except Exception as exc:
        print("Fatal error: {}".format(exc))
    finally:
        # Clean up resources on every exit path
        if fingerprint_sensor is not None:
            try:
                fingerprint_sensor.deinit()
                print("Fingerprint sensor deinitialized.")
            except Exception as exc:
                print("Error deinitializing fingerprint sensor: {}".format(exc))
