import signal
import sys
import time
import logging
from functools import partial

try:
    import RPi.GPIO as GPIO
except ImportError:
    logging.error("RPi.GPIO is not available. This script must run on a Raspberry Pi.")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

DEBOUNCE_MS = 20
CLK_PIN = 17
DT_PIN = 18

QUADRATURE_TABLE = {
    (0, 0): 0,
    (1, 0): 1,
    (1, 1): 2,
    (0, 1): 3,
}


class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.value = 0
        self._last_state = 0
        self._initialized = False

        if callback is not None and not callable(callback):
            raise TypeError("callback must be callable or None")

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.setup(self.dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            self._last_state = QUADRATURE_TABLE[
                (GPIO.input(self.clk_pin), GPIO.input(self.dt_pin))
            ]
            self._initialized = True
            logging.info(
                "Rotary encoder initialized on CLK=%d, DT=%d", clk_pin, dt_pin
            )
        except Exception as e:
            logging.error("Failed to initialize GPIO: %s", e)
            self.cleanup()
            raise

    def _handle_rotation(self, channel):
        try:
            clk_level = GPIO.input(self.clk_pin)
            dt_level = GPIO.input(self.dt_pin)
            state = QUADRATURE_TABLE[(clk_level, dt_level)]

            if state != self._last_state:
                if (state == 1 and self._last_state == 2) or (
                    state == 2 and self._last_state == 1
                ):
                    self.value += 1
                elif (state == 3 and self._last_state == 0) or (
                    state == 0 and self._last_state == 3
                ):
                    self.value -= 1

                self._last_state = state

                if self.callback is not None:
                    try:
                        self.callback(self.value)
                    except Exception as e:
                        logging.error("Callback raised an exception: %s", e)
        except Exception as e:
            logging.error("Error handling rotation: %s", e)

    def start(self):
        if not self._initialized:
            raise RuntimeError("Encoder not initialized")
        try:
            GPIO.add_event_detect(
                self.clk_pin,
                GPIO.BOTH,
                callback=self._handle_rotation,
                bouncetime=DEBOUNCE_MS,
            )
            GPIO.add_event_detect(
                self.dt_pin,
                GPIO.BOTH,
                callback=self._handle_rotation,
                bouncetime=DEBOUNCE_MS,
            )
            logging.info("Event detection started on CLK and DT pins.")
        except Exception as e:
            logging.error("Failed to start event detection: %s", e)
            self.cleanup()
            raise

    def stop(self):
        try:
            GPIO.remove_event_detect(self.clk_pin)
            GPIO.remove_event_detect(self.dt_pin)
            logging.info("Event detection stopped.")
        except Exception as e:
            logging.error("Failed to stop event detection: %s", e)

    def cleanup(self):
        try:
            self.stop()
        except Exception:
            pass
        try:
            GPIO.cleanup()
            logging.info("GPIO cleanup completed.")
        except Exception as e:
            logging.error("GPIO cleanup failed: %s", e)
        self._initialized = False


def main():
    encoder = None

    def on_rotation(value):
        print(f"Encoder value: {value}")

    def signal_handler(signum, frame):
        logging.info("Signal %d received, exiting.", signum)
        if encoder is not None:
            encoder.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        encoder = RotaryEncoder(CLK_PIN, DT_PIN, callback=on_rotation)
        encoder.start()
        logging.info("Rotary encoder running. Press Ctrl+C to exit.")
        while True:
            time.sleep(1)
    except Exception as e:
        logging.error("An error occurred: %s", e)
    finally:
        if encoder is not None:
            encoder.cleanup()


if __name__ == "__main__":
    main()

