import sys
import time
import signal

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000
USE_HW_PWM = True

pwm = None
running = True


def cleanup():
    global pwm
    if pwm is not None:
        try:
            pwm.stop()
        except Exception:
            pass
        pwm = None
    try:
        GPIO.cleanup()
    except Exception:
        pass


def signal_handler(signum, frame):
    global running
    running = False


def set_fan_speed(speed_percent):
    if not 0 <= speed_percent <= 100:
        print("Invalid fan speed. Please enter a value between 0 and 100.")
        return
    try:
        pwm.ChangeDutyCycle(speed_percent)
        print(f"Fan speed set to {speed_percent}%")
    except Exception as e:
        print(f"Error setting fan speed: {e}")


def main():
    global pwm, USE_HW_PWM

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    if USE_HW_PWM:
        try:
            GPIO.setup(FAN_PIN, GPIO.OUT)
            pwm = GPIO.PWM(FAN_PIN, PWM_FREQ)
            pwm.start(0)
            print("Using hardware PWM.")
        except Exception as e:
            print(f"Hardware PWM not available ({e}); falling back to software PWM.")
            USE_HW_PWM = False
            pwm = None

    if not USE_HW_PWM:
        try:
            GPIO.setup(FAN_PIN, GPIO.OUT)
            pwm = GPIO.PWM(FAN_PIN, PWM_FREQ)
            pwm.start(0)
            print("Using software PWM.")
        except Exception as e:
            print(f"Failed to initialize PWM: {e}")
            cleanup()
            sys.exit(1)

    print("Fan control ready. Enter a value 0-100 (q to quit).")

    try:
        while running:
            try:
                user_input = input("Enter fan speed (0-100, or q to quit): ").strip()
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_input.lower() == 'q':
                break

            try:
                fan_speed = float(user_input)
                set_fan_speed(fan_speed)
            except ValueError:
                print("Invalid input. Please enter a number between 0 and 100.")
            except Exception as e:
                print(f"An error occurred: {e}")
    finally:
        cleanup()
        print("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

