        raise ValueError(f"Goal cell {goal_cell} out of bounds")
    if grid[start_cell[1]][start_cell[0]] == OBSTACLE:
        raise ValueError(f"Start cell {start_cell} is an obstacle")
    if grid[goal_cell[1]][goal_cell[0]] == OBSTACLE:
        raise ValueError(f"Goal cell {goal_cell} is an obstacle")

