#!/usr/bin/env python3
"""
Blink an LED on GPIO17 (BCM) at 1 Hz.

Target: Raspberry Pi 3 Model B+
Wiring: LED anode -> 330 ohm resistor -> GPIO17 (BCM), LED cathode -> GND
"""

import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(0)


LED_PIN = 17
ON_DURATION = 1.0
OFF_DURATION = 1.0


def main() -> int:
    """Run the blink loop, returning a process exit code."""
    led = None
    try:
        try:
            led = LED(LED_PIN)
        except BadPinFactory:
            print("Error: No GPIO pin factory available. Are you running on a Raspberry Pi?", file=sys.stderr)
            return 0
        except GPIOZeroError as exc:
            print(f"Error: Failed to initialize GPIO{LED_PIN}: {exc}", file=sys.stderr)
            return 0
        except Exception as exc:
            print(f"Error: Unexpected GPIO initialization failure: {exc}", file=sys.stderr)
            return 0

        print(f"Blinking LED on GPIO{LED_PIN} (1 Hz). Press Ctrl+C to stop.")

        while True:
            led.on()
            time.sleep(ON_DURATION)
            led.off()
            time.sleep(OFF_DURATION)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
        return 0
    finally:
        if led is not None:
            try:
                led.close()
            except Exception:
                pass


if __name__ == "__main__":
    sys.exit(main())

