import signal
import time
from gpiozero import LED

LED_PIN = 17
led = None

def turn_on_led(pin):
    """Set the given pin HIGH."""
    if led is not None:
        led.on()

def turn_off_led(pin):
    """Set the given pin LOW."""
    if led is not None:
        led.off()

def cleanup(signum=None, frame=None):
    """Release GPIO resources and ensure the pin is LOW."""
    global led
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
        raise SystemExit(0)

def main():
    global led
    led = LED(LED_PIN)
    led.off()  # ensure known initial state
    print("Starting LED blinking on GPIO17 (BCM). Press Ctrl+C to stop.")
    try:
        while True:
            turn_on_led(LED_PIN)
            time.sleep(1)
            turn_off_led(LED_PIN)
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    finally:
        cleanup()

if __name__ == "__main__":
    signal.signal(signal.SIGTERM, cleanup)
    main()

