import json
import random
import sys

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

FRAME_COUNT = 6
KEYWORD_MAP = {
    "water": "open_valve",
    "stop": "close_valve",
    "status": "report",
}


def generate_audio_frame() -> int:
    """Return a simulated audio energy level in the range 0-9."""
    return random.randint(0, 9)


def transcribe_frame(energy_level: int) -> str:
    """Map an energy level to a keyword using a deterministic pattern."""
    keywords = list(KEYWORD_MAP.keys())
    return keywords[energy_level % len(keywords)]


def process_audio_frames(frame_count: int) -> list:
    """Simulate voice recognition over a number of audio frames."""
    actions = []
    for i in range(frame_count):
        energy = generate_audio_frame()
        keyword = transcribe_frame(energy)
        action = KEYWORD_MAP.get(keyword, "unknown")
        actions.append(action)
        print(f"Frame {i}: keyword='{keyword}' -> action='{action}'")
    return actions


def save_actions_to_json(actions: list, filename: str) -> None:
    """Persist the list of chosen actions to a JSON file."""
    try:
        with open(filename, "w", encoding="utf-8") as fh:
            json.dump(actions, fh, indent=2)
        print(f"Saved {len(actions)} actions to {filename}")
    except OSError as exc:
        print(f"Error writing JSON file '{filename}': {exc}", file=sys.stderr)
        raise


def main() -> None:
    """Entry point: run the simulation and persist results."""
    if GPIO is not None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
        except Exception as exc:
            print(f"Warning: GPIO init failed: {exc}", file=sys.stderr)

    try:
        chosen_actions = process_audio_frames(FRAME_COUNT)
        save_actions_to_json(chosen_actions, "voice_actions.json")
    except Exception as exc:
        print(f"Voice recognition error: {exc}", file=sys.stderr)
    finally:
        if GPIO is not None:
            try:
                GPIO.cleanup()
            except Exception:
                pass


if __name__ == "__main__":
    main()

