import time
import signal
import sys
import requests
from gpiozero import Button

BUTTON_PIN = 17
SERVER_URL = 'http://localhost:8000/quality'
POLL_INTERVAL = 2.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def generate_report(button_pressed):
    if button_pressed:
        return {
            'part_id': 'PART-204',
            'passed': False,
            'defect_count': 1,
        }
    return {
        'part_id': 'PART-204',
        'passed': True,
        'defect_count': 0,
    }

def send_report(report):
    try:
        response = requests.post(
            SERVER_URL,
            json=report,
            headers={'Content-Type': 'application/json'},
            timeout=5,
        )
        print(f'Server response: {response.status_code}')
    except requests.exceptions.Timeout:
        print('Error: request timed out')
    except requests.exceptions.ConnectionError:
        print('Error: cannot connect to server')
    except requests.exceptions.DNSLookupError:
        print('Error: DNS lookup failed')
    except requests.exceptions.RequestException as e:
        print(f'Error: {e}')

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        button = Button(BUTTON_PIN, pull_up=True, bounce_time=None)
    except Exception as e:
        print(f'Failed to initialize GPIO{BUTTON_PIN}: {e}')
        sys.exit(1)

    last_state = None
    try:
        while _running:
            try:
                current_state = button.is_pressed
            except Exception as e:
                print(f'GPIO read error: {e}')
                time.sleep(POLL_INTERVAL)
                continue

            if current_state != last_state:
                report = generate_report(current_state)
                send_report(report)
                last_state = current_state

            time.sleep(POLL_INTERVAL)
    finally:
        button.close()
        print('GPIO cleanup done')

if __name__ == '__main__':
    main()

