import time
import datetime
import sqlite3
import configparser
import random
import signal
import sys
import os

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

DATABASE_FILE = 'greenhouse_energy.db'
ERROR_LOG_FILE = 'greenhouse_errors.log'
ALERT_LOG_FILE = 'greenhouse_alerts.log'
RELAY_PIN = 17
DEFAULT_POWER_THRESHOLD = 100.0
SAMPLE_INTERVAL = 5
RELAY_OFF_DURATION = 60

_running = True

def log_error(message):
    ts = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG_FILE, 'a') as f:
            f.write(f"{ts} - ERROR: {message}\n")
    except OSError as e:
        print(f"Failed to write to error log: {e}", file=sys.stderr)

def log_alert(message):
    ts = datetime.datetime.now().isoformat()
    try:
        with open(ALERT_LOG_FILE, 'a') as f:
            f.write(f"{ts} - ALERT: {message}\n")
    except OSError as e:
        print(f"Failed to write to alert log: {e}", file=sys.stderr)

def signal_handler(signum, frame):
    global _running
    _running = False

def read_config():
    config = configparser.ConfigParser()
    try:
        if not config.read('config.ini'):
            log_error("config.ini not found; using default power threshold.")
            return DEFAULT_POWER_THRESHOLD
        return config.getfloat('DEFAULT', 'power_threshold', fallback=DEFAULT_POWER_THRESHOLD)
    except (configparser.Error, ValueError) as e:
        log_error(f"Error reading config.ini: {e}; using default.")
        return DEFAULT_POWER_THRESHOLD

def init_database():
    try:
        conn = sqlite3.connect(DATABASE_FILE)
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS energy_data (
                Timestamp TEXT PRIMARY KEY,
                Voltage REAL,
                Current REAL,
                Power REAL,
                Energy REAL
            )
        ''')
        conn.commit()
        conn.close()
    except sqlite3.Error as e:
