import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: sudo apt install python3-rpi.gpio")
    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_moisture():
    """Simulate a soil-moisture sensor reading (0-100 inclusive)."""
    return random.randint(0, 100)

def control_pump(moisture_level):
    """Drive the pump HIGH when moisture is below threshold, else LOW."""
    if moisture_level < MOISTURE_THRESHOLD:
        GPIO.output(PUMP_PIN, GPIO.HIGH)
        return "ON  (moisture below threshold)"
    GPIO.output(PUMP_PIN, GPIO.LOW)
    return "OFF (moisture adequate)"

def cleanup():
    """Ensure the pump is off and release GPIO resources."""
    try:
        GPIO.output(PUMP_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO initialization failed: {e}")
        print("Hint: run with sudo or check permissions (e.g., /dev/gpiomem accessible).")
        sys.exit(1)

    try:
        for i in range(1, ITERATIONS + 1):
            if not _running:
                break
            moisture = read_moisture()
            pump_state = control_pump(moisture)
            print(f"Reading {i}/{ITERATIONS}  Moisture: {moisture}%  Pump: {pump_state}")
            if i < ITERATIONS and _running:
                time.sleep(DELAY_SECONDS)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

