import RPi.GPIO as GPIO
import time
import logging
import sqlite3
import signal
import sys

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# GPIO pin definitions (BCM numbering)
SOLENOID_PINS = [17, 27, 22]
MICROSWITCH_PINS = [5, 6, 13]
IR_BREAKBEAM_PIN = 4

# Database configuration
DATABASE_NAME = 'seed_count.db'

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    logging.info("Shutdown signal received. Cleaning up...")
    running = False

def create_database():
    """Creates the SQLite database and table if they don't exist."""
    try:
        conn = sqlite3.connect(DATABASE_NAME)
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS seed_counts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
                seed_type TEXT NOT NULL,
                count INTEGER NOT NULL
            )
        ''')
        conn.commit()
        conn.close()
        logging.info("Database created/connected successfully.")
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")
        raise

def initialize_gpio():
    """Initializes GPIO pins for solenoids, microswitches, and IR breakbeam."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)

        # Setup solenoid pins as outputs, initially LOW (off)
        for pin in SOLENOID_PINS:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

