        self.ld = ld
        self.sd = sd
        self.hp = hp
        self.vp = vp
        self._laser = None
        self._servo_h = None
        self._servo_v = None
        self._gpio_available = False

    def _init_gpio(self):
        if self._gpio_available:
            return
        if GPIO is None:
            print("[Aim] Warning: RPi.GPIO unavailable; running in no-op mode.")
            self._gpio_available = False
            return
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(HORIZONTAL_PIN, GPIO.OUT)
            GPIO.setup(VERTICAL_PIN, GPIO.OUT)
            self._gpio_available = True
        except Exception as e:
            print(f"[Aim] GPIO init error: {e}")
            self._gpio_available = False

    def _move_servo(self, pin, pulse_width):
        if not self._gpio_available:
            return
        try:
            GPIO.output(pin, GPIO.HIGH)
            time.sleep(pulse_width)
            GPIO.output(pin, GPIO.LOW)
        except Exception as e:
            print(f"[Aim] Servo move error on pin {pin}: {e}")

    def aim(self, a):
        self._init_gpio()
        if not self._gpio_available:
            print("[Aim] No-op mode: skipping aim sequence.")
            return
        try:
            self._laser = Laser(LASER_PIN)
            self._servo_h = HORIZONTAL_PIN
            self._servo_v = VERTICAL_PIN
            for i in a:
                if not (1 <= i <= 10):
