                self._move_servo(self._servo_h, self.hp[10])
                self._move_servo(self._servo_v, self.vp[10])
                time.sleep(self.sd / 2)
        except Exception as e:
            print(f"[Aim] Error during aiming: {e}")
        finally:
            if self._laser:
                self._laser.off()
                self._laser.close()
            if self._gpio_available:
                try:
                    GPIO.cleanup()
                except Exception:
                    pass


def main():
    aim = Aim(ld=0.5, sd=1.0, hp=HORIZONTAL_PW, vp=VERTICAL_PW)
    try:
        aim.aim([3, 5, 7])
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if GPIO is not None:
            try:
                GPIO.cleanup()
            except Exception:
                pass


if __name__ == "__main__":
    main()

