import http.server
import socketserver
import json
import signal
import sys
import RPi.GPIO as GPIO

RELAY_PIN = 23
PORT = 5000

def setup_gpio():
    """Initialize GPIO and set relay pin as output."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO initialization failed: {e}", file=sys.stderr)
        sys.exit(1)

def cleanup_gpio(signum=None, frame=None):
    """Cleanly release GPIO resources on exit."""
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)

class RelayHandler(http.server.BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path != '/relay':
            self.send_response(404)
            self.end_headers()
            return

        content_length = int(self.headers.get('Content-Length', 0))
        if content_length == 0:
            self._respond(400, {"error": "Invalid request"})
            return

        try:
            body = self.rfile.read(content_length)
            data = json.loads(body.decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError, ValueError):
            self._respond(400, {"error": "Invalid request"})
            return

        if not isinstance(data, dict) or 'state' not in data:
            self._respond(400, {"error": "Invalid request"})
            return

        state = data['state']
        if state not in ('on', 'off'):
            self._respond(400, {"error": "Invalid request"})
            return

        try:
            GPIO.output(RELAY_PIN, GPIO.HIGH if state == 'on' else GPIO.LOW)
        except Exception as e:
            print(f"GPIO output error: {e}", file=sys.stderr)
            self._respond(500, {"error": "Internal server error"})
            return

        self._respond(200, {"status": "Relay state changed"})

    def _respond(self, status_code, payload):
        self.send_response(status_code)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(payload).encode('utf-8'))

def run_server():
    setup_gpio()
    signal.signal(signal.SIGINT, cleanup_gpio)
    signal.signal(signal.SIGTERM, cleanup_gpio)
    try:
        with socketserver.TCPServer(('0.0.0.0', PORT), RelayHandler) as httpd:
            print(f"Serving at port {PORT}")
            httpd.serve_forever()
    except Exception as e:
        print(f"Server error: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()

if __name__ == '__main__':
    run_server()

