from adafruit_pca9685 import PCA9685

# Constants
I2C_BUS = 1
PCA9685_ADDR = 0x40
PWM_FREQUENCY = 60  # Hz
SERVO_MIN_PULSE = 150  # 1.5 ms pulse for -77 degrees
SERVO_MAX_PULSE = 1900  # 2.0 ms pulse for +77 degrees
SERVO_CHANNELS = [0, 1]
DELAY = 0.25

# Global reference for cleanup
pwm = None
bus = None


def cleanup(signum=None, frame=None):
    """Set all channels to 0 and release resources on exit."""
    global pwm, bus
    if pwm is not None:
        try:
            for ch in SERVO_CHANNELS:
                pwm.channels[ch].duty_cycle = 0
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def initialize_pca9685():
    """Initialize the PCA9685 PWM driver and verify it is present."""
    global pwm, bus
    try:
        bus = smbus2.SMBus(I2C_BUS)
        # Probe the device address by reading the mode register (0x00)
        bus.read_byte_data(PCA9685_ADDR, 0x00)
        pwm = PCA9685(bus, address=PCA9685_ADDR)
        pwm.frequency = PWM_FREQUENCY
        return pwm
    except OSError as e:
        print(f"Error: PCA9685 not found at address 0x{PCA9685_ADDR:02X} on bus {I2C_BUS}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing PCA9685: {e}")
        return None


def set_servo_angle(channel, angle):
    """Set the servo angle on the specified channel using linear pulse-width mapping."""
    if pwm is None:
        print("Error: PCA9685 not initialized.")
        return False
    try:
        pulse = int(SERVO_MIN_PULSE + (angle / 180.0) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE))
        pwm.channels[channel].duty_cycle = pulse
        return True
    except Exception as e:
        print(f"Error setting servo angle on channel {channel}: {e}")
        return False


def move_servo(channel, angle):
    """Move the servo to the specified angle and wait for the delay."""
    if set_servo_angle(channel, angle):
        time.sleep(DELAY)


def main():
    """Main function to demonstrate servo control."""
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    if initialize_pca9685() is None:
        sys.exit(1)

    try:
        for channel in SERVO_CHANNELS:
            move_servo(channel, -77)
            move_servo(channel, 77)
            move_servo(channel, 0)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

