import logging
import signal
import sys
from typing import Optional

try:
    from gpiozero import OutputDevice
except ImportError:
    logging.error("gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PUMP_PIN = 20
LIGHT_PIN = 21

pump: Optional[OutputDevice] = None
light: Optional[OutputDevice] = None


def init_devices() -> None:
    global pump, light
    try:
        pump = OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
        light = OutputDevice(LIGHT_PIN, active_high=True, initial_value=False)
        logging.info("GPIO devices initialized: pump=BCM%d, light=BCM%d", PUMP_PIN, LIGHT_PIN)
    except Exception as exc:
        logging.error("Failed to initialize GPIO devices: %s", exc)
        raise


def parse_intent(phrase: str) -> str:
    normalized = phrase.strip().lower()
    if "pump" in normalized and "on" in normalized:
        return "pump_on"
    if "pump" in normalized and "off" in normalized:
        return "pump_off"
    if "light" in normalized or "switch" in normalized:
        return "light_toggle"
    return "unknown"


def apply_intent(intent: str) -> None:
    if intent == "pump_on":
        if pump is not None:
            pump.on()
        logging.info("Pump turned ON")
    elif intent == "pump_off":
        if pump is not None:
            pump.off()
        logging.info("Pump turned OFF")
    elif intent == "light_toggle":
        if light is not None:
            light.toggle()
        logging.info("Light toggled")
    else:
        logging.warning("Unknown intent: %s", intent)


def cleanup(signum: Optional[int] = None, frame=None) -> None:
    global pump, light
    if pump is not None:
        try:
            pump.off()
            pump.close()
        except Exception as exc:
            logging.error("Error closing pump device: %s", exc)
        pump = None
    if light is not None:
        try:
            light.off()
            light.close()
        except Exception as exc:
            logging.error("Error closing light device: %s", exc)
        light = None
    logging.info("GPIO cleanup completed.")
    if signum is not None:
        sys.exit(0)


def main() -> None:
    init_devices()
    signal.signal(signal.SIGTERM, cleanup)
    test_phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command",
    ]
    try:
        for phrase in test_phrases:
            intent = parse_intent(phrase)
            logging.info("Phrase: %s -> Intent: %s", phrase, intent)
            apply_intent(intent)
    except KeyboardInterrupt:
        logging.info("KeyboardInterrupt received.")
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

