import paho.mqtt.client as mqtt
import time
import logging
import json
from paho.mqtt.client import CallbackAPIVersion

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

BROKER_HOST = "localhost"
BROKER_PORT = 1883
SUBSCRIBE_TOPIC = "city/reports"
RUN_DURATION = 5

keyword_store = {"noise": ["crackle", "thunder"], "traffic": ["slow", "stop"]}
classification_counts = {"noise": 0, "traffic": 0, "other": 0}


def classify_report(report_text):
    """Classify a report text into a keyword category."""
    for category, keywords in keyword_store.items():
        for keyword in keywords:
            if keyword in report_text:
                return category
    return "other"


def handle_message(mqtt_client, userdata, message):
    """Handle an incoming MQTT message, classify it, and update counts."""
    try:
        payload = message.payload.decode("utf-8")
        logging.info("Received message: %s", payload)
        category = classify_report(payload)
        classification_counts[category] += 1
        logging.info("Classification: %s", category)
    except UnicodeDecodeError:
        logging.error("Failed to decode message payload as UTF-8")
    except Exception as e:
        logging.error("Error processing message: %s", e)


def main():
    """Set up the MQTT client, connect, subscribe, and run for a fixed duration."""
    mqtt_client = mqtt.Client(callback_api_version=CallbackAPIVersion.VERSION2)
    mqtt_client.on_message = handle_message

    try:
        mqtt_client.connect(BROKER_HOST, BROKER_PORT, keepalive=60)
        mqtt_client.subscribe(SUBSCRIBE_TOPIC)
        logging.info("Connected to broker and subscribed to %s", SUBSCRIBE_TOPIC)
    except Exception as e:
        logging.error("Failed to connect or subscribe to broker: %s", e)
        return

    try:
        mqtt_client.loop_start()
        time.sleep(RUN_DURATION)
    except Exception as e:
        logging.error("Error during message loop: %s", e)
    finally:
        try:
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
            logging.info("Disconnected from broker")
        except Exception as e:
            logging.error("Error during shutdown: %s", e)

    logging.info("Final classification counts: %s", classification_counts)


if __name__ == "__main__":
    main()

