import sys
import smbus
from datetime import datetime


class DS1338Error(Exception):
    """Base class for DS1338 related exceptions."""
    pass


class DS1338CommunicationError(DS1338Error):
    """Raised when I2C communication fails."""
    pass


class DS1338ValueError(DS1338Error):
    """Raised when provided values are out of range."""
    pass


class DS1338:
