    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07

    # Bit masks
    CH = 0x80  # Clock Halt bit (bit 7 of seconds register)
    MF = 0x80  # Mask bit (bit 6 of hours register)

    def __init__(self, twi=1, addr=0x68):
        """
        Initialize the DS1338 RTC object.

        Args:
            twi (int): I2C bus number (default: 1).
            addr (int): I2C address of the DS1338 (default: 0x68).
        """
