        self.bus = None
        try:
            self.bus = smbus.SMBus(twi)
        except FileNotFoundError:
            raise DS1338CommunicationError(
                f"I2C bus {twi} not found. Enable I2C and check /dev/i2c-{twi}."
            )
        except PermissionError:
            raise DS1338CommunicationError(
                f"Permission denied on /dev/i2c-{twi}. Run as root or add user to i2c group."
            )
        except OSError as e:
            raise DS1338CommunicationError(f"Failed to open I2C bus {twi}: {e}")

        # Verify device presence
        try:
            self.bus.read_byte_data(self.addr, self.REG_SECONDS)
        except OSError as e:
            self.close()
            raise DS1338CommunicationError(
                f"No DS1338 found at address 0x{self.addr:02X} on bus {twi}: {e}"
            )

    def close(self):
        """Release the I2C bus handle."""
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            finally:
                self.bus = None

    def _write_register(self, register, data):
        """Write a byte to a DS1338 register."""
        try:
            self.bus.write_byte_data(self.addr, register, data)
        except OSError as e:
            raise DS1338CommunicationError(
                f"I2C write error to register 0x{register:02X}: {e}"
            )

    def _read_register(self, register):
        """Read a byte from a DS1338 register."""
        try:
            return self.bus.read_byte_data(self.addr, register)
        except OSError as e:
            raise DS1338CommunicationError(
                f"I2C read error from register 0x{register:02X}: {e}"
            )

    @staticmethod
    def _bcd_to_int(bcd):
        """Convert Binary Coded Decimal (BCD) to integer."""
        return ((bcd >> 4) & 0x0F) * 10 + (bcd & 0x0F)

