        """Read and convert a time register (seconds, minutes, hours, day)."""
        raw = self._read_register(register)
        if register == self.REG_HOURS:
            # Mask bit 6 (12/24h mode) and bit 7 (clock halt)
            return self._bcd_to_int(raw & 0x3F)
        return self._bcd_to_int(raw)

    def _write_time_register(self, register, value, max_value):
        """Write and convert a time value to BCD to a register."""
        if not 0 <= value <= max_value:
            raise DS1338ValueError(
                f"Value {value} out of range (0-{max_value}) for register 0x{register:02X}"
            )
