        """Read seconds (0-59)."""
        return self._read_time_register(self.REG_SECONDS)

    def read_minutes(self):
        """Read minutes (0-59)."""
        return self._read_time_register(self.REG_MINUTES)

    def read_hours(self):
        """Read hours in 24-hour format (0-23)."""
        return self._read_time_register(self.REG_HOURS)

    def read_day(self):
        """Read day of the week (1-7, where 1 = Sunday)."""
        return self._read_time_register(self.REG_DAY)

    def read_date(self):
        """Read date (1-31)."""
        return self._read_time_register(self.REG_DATE)

    def read_month(self):
        """Read month (1-12)."""
        return self._read_time_register(self.REG_MONTH)

    def read_year(self):
        """Read year (0-99)."""
        return self._read_time_register(self.REG_YEAR)

    def write_seconds(self, seconds):
        """Write seconds (0-59)."""
        self._write_time_register(self.REG_SECONDS, seconds, 59)

    def write_minutes(self, minutes):
        """Write minutes (0-59)."""
        self._write_time_register(self.REG_MINUTES, minutes, 59)

    def write_hours(self, hours):
        """Write hours in 24-hour format (0-23)."""
        self._write_time_register(self.REG_HOURS, hours, 23)

    def write_day(self, day):
        """Write day of the week (1-7, where 1 = Sunday)."""
        self._write_time_register(self.REG_DAY, day, 7)

    def write_date(self, date):
        """Write date (1-31)."""
        self._write_time_register(self.REG_DATE, date, 31)

    def write_month(self, month):
        """Write month (1-12)."""
        self._write_time_register(self.REG_MONTH, month, 12)

    def write_year(self, year):
        """Write year (0-99)."""
        self._write_time_register(self.REG_YEAR, year, 99)

    def read_all(self):
        """
        Read all time registers and return as a tuple.

        Returns:
            tuple: (year, month, date, day, hours, minutes, seconds)
        """
        return (
            self.read_year(),
            self.read_month(),
            self.read_date(),
            self.read_day(),
            self.read_hours(),
            self.read_minutes(),
            self.read_seconds(),
        )

    def write_all(
        self,
        seconds=None,
        minutes=None,
        hours=None,
        day=None,
        date=None,
        month=None,
        year=None,
    ):
        """
        Write all time registers. Only specified values are updated.

        Args:
            seconds (int, optional): Seconds (0-59).
            minutes (int, optional): Minutes (0-59).
            hours (int, optional): Hours in 24-hour format (0-23).
            day (int, optional): Day of the week (1-7).
            date (int, optional): Date (1-31).
            month (int, optional): Month (1-12).
            year (int, optional): Year (0-99).
        """
