            self.write_seconds(seconds)
        if minutes is not None:
            self.write_minutes(minutes)
        if hours is not None:
            self.write_hours(hours)
        if day is not None:
            self.write_day(day)
        if date is not None:
            self.write_date(date)
        if month is not None:
            self.write_month(month)
        if year is not None:
            self.write_year(year)

    def read_datetime(self, century=21):
        """
        Read the current date and time and return as a datetime object.

        Args:
            century (int): The century to use for the year (default: 21).

        Returns:
            datetime: Current date and time.
        """
        year, month, date, day, hours, minutes, seconds = self.read_all()
        full_year = (century - 1) * 100 + year
        return datetime(full_year, month, date, hours, minutes, seconds)

    def write_datetime(self, dt):
        """
        Write the date and time from a datetime object.

        Args:
            dt (datetime): The datetime object to write.
        """
        self.write_all(
            seconds=dt.second,
            minutes=dt.minute,
            hours=dt.hour,
            day=dt.isoweekday(),
            date=dt.day,
            month=dt.month,
            year=dt.year % 100,
        )


# Global reference for signal handler
_rtc_instance = None


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM by closing the RTC instance and exiting."""
    if _rtc_instance is not None:
        _rtc_instance.close()
    sys.exit(0)


