    """Example usage: read and print the current date and time."""
    global _rtc_instance

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _rtc_instance = DS1338(twi=1, addr=0x68)
        now = _rtc_instance.read_datetime()
        print(f"Current date and time: {now}")
    except DS1338Error as e:
        print(f"DS1338 error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if _rtc_instance is not None:
            _rtc_instance.close()


