import serial
import time
import signal
import sys
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def initialize_gpio(pin):
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

def read_radiation_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print(f"Invalid data received (non-numeric): {line!r}", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial I/O error: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading serial data: {e}", file=sys.stderr)
        return None

def set_alarm(pin, radiation_level, threshold):
    if radiation_level > threshold:
        if GPIO.input(pin) == GPIO.LOW:
            GPIO.output(pin, GPIO.HIGH)
            print("Alarm triggered: Radiation level exceeds threshold!")
    else:
        if GPIO.input(pin) == GPIO.HIGH:
            GPIO.output(pin, GPIO.LOW)
            print("Alarm cleared: Radiation level is back to normal.")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        initialize_gpio(ALARM_PIN)
    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        serial_connection.close()
        sys.exit(1)

    try:
        while _running:
            radiation = read_radiation_data(serial_connection)
            if radiation is not None:
                print(f"Radiation Level: {radiation:.2f} µSv/h")
                set_alarm(ALARM_PIN, radiation, RADIATION_THRESHOLD)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

