def set_alarm(pin, radiation_level, threshold):
    if radiation_level > threshold:
        if GPIO.input(pin) == GPIO.LOW:
            GPIO.output(pin, GPIO.HIGH)
            print("Alarm triggered: Radiation level exceeds threshold!")
    else:
        if GPIO.input(pin) == GPIO.HIGH:
            GPIO.output(pin, GPIO.LOW)
            print("Alarm cleared: Radiation level is back to normal.")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        initialize_gpio(ALARM_PIN)
    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        serial_connection.close()
        sys.exit(1)

    try:
        while _running:
            radiation = read_radiation_data(serial_connection)
            if radiation is not None:
                print(f"Radiation Level: {radiation:.2f} µSv/h")
                set_alarm(ALARM_PIN, radiation, RADIATION_THRESHOLD)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up. Exiting.")

if __name__ == "__main__":
    main()

