import threading
import signal
import sys
import os
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'water_flow_log.txt'
READ_INTERVAL = 1.0

stop_event = threading.Event()
serial_connection = None


def log_message(message: str) -> None:
    """Append a timestamped message to the log file."""
    timestamp = datetime.now().isoformat(timespec='seconds')
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as logfile:
            logfile.write(f"{timestamp} - {message}\n")
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)


def read_flow_rate() -> None:
    """Continuously read flow-rate data from the serial port and log it."""
    global serial_connection
    while not stop_event.is_set():
        try:
            if serial_connection is None or not serial_connection.is_open:
                print("Serial port is not open. Attempting to open...", file=sys.stderr)
                try:
                    serial_connection = serial.Serial(
                        SERIAL_PORT,
                        BAUD_RATE,
                        timeout=TIMEOUT,
                    )
                except serial.SerialException as e:
                    print(f"Failed to open serial port: {e}", file=sys.stderr)
                    stop_event.wait(READ_INTERVAL)
                    continue

            raw = serial_connection.readline()
            if not raw:
                continue

            decoded = raw.decode('ascii', errors='replace').strip()
            if not decoded:
                continue

            flow_rate = float(decoded)
            print(f"Flow Rate: {flow_rate} L/min")
            log_message(f"Flow Rate: {flow_rate} L/min")

        except ValueError:
            log_message(f"Invalid data received (not a float): {decoded!r}")
        except serial.SerialException as e:
            print(f"Serial communication error: {e}", file=sys.stderr)
            log_message(f"Serial communication error: {e}")
            if serial_connection is not None:
                try:
                    serial_connection.close()
                except Exception:
                    pass
                serial_connection = None
            stop_event.wait(READ_INTERVAL)
            continue
        except OSError as e:
            print(f"I/O error: {e}", file=sys.stderr)
            log_message(f"I/O error: {e}")
            if serial_connection is not None:
                try:
                    serial_connection.close()
                except Exception:
                    pass
                serial_connection = None
            stop_event.wait(READ_INTERVAL)
            continue

        stop_event.wait(READ_INTERVAL)


def signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM by signaling the reader thread to stop."""
    print(f"\nReceived signal {signum}, stopping...")
    stop_event.set()


def main() -> None:
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    reader_thread = threading.Thread(target=read_flow_rate, daemon=True)
    reader_thread.start()

    try:
        while not stop_event.is_set():
            stop_event.wait(0.5)
    except KeyboardInterrupt:
        stop_event.set()

    reader_thread.join(timeout=5)
    if reader_thread.is_alive():
        print("Reader thread did not stop cleanly.", file=sys.stderr)

    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
        except Exception:
            pass
    print("Program finished.")


if __name__ == "__main__":
    main()

