import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

@dataclass
class GPS_readings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellites: Optional[int] = None

class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_port: Optional[serial.Serial] = None
        self._connected = False

    def connect(self) -> bool:
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            self._connected = True
            logging.info("Connected to GPS on %s at %d baud.", self.port, self.baudrate)
            return True
        except serial.SerialException as e:
            logging.error("Failed to connect to GPS on %s: %s", self.port, e)
            self.serial_port = None
            self._connected = False
            return False

    def disconnect(self) -> None:
        if self._connected and self.serial_port is not None:
            try:
                if self.serial_port.is_open:
                    self.serial_port.close()
                logging.info("Disconnected from GPS.")
            except serial.SerialException as e:
                logging.error("Error while disconnecting GPS: %s", e)
            finally:
                self.serial_port = None
                self._connected = False
        else:
            logging.info("GPS was not connected; disconnect skipped.")

    def _verify_checksum(self, sentence: str) -> bool:
        if "*" not in sentence:
            return False
        body, _, csum_str = sentence.partition("*")
        if not body.startswith("$"):
            return False
        body = body[1:]
        try:
            expected = int(csum_str.strip(), 16)
        except ValueError:
            return False
        calculated = 0
        for ch in body:
            calculated ^= ord(ch)
        return calculated == expected

    def _nmea_to_decimal(self, coord: str, direction: str) -> Optional[float]:
        if not coord or not direction:
            return None
        try:
            dot = coord.index(".")
            deg_len = dot - 2
            degrees = float(coord[:deg_len])
            minutes = float(coord[deg_len:])
            decimal = degrees + minutes / 60.0
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError):
            return None

    def get_readings(self) -> Optional[GPS_readings]:
        if not self._connected or self.serial_port is None:
            logging.error("GPS not connected. Call connect() first.")
            return None
        try:
            raw = self.serial_port.readline()
        except serial.SerialException as e:
            logging.error("Serial read error: %s", e)
            return None
        if not raw:
            return None
        try:
            line = raw.decode("ascii", errors="replace").strip()
        except Exception as e:
            logging.error("Decode error: %s", e)
            return None
        if not line:
            return None
        if not self._verify_checksum(line):
            logging.warning("Checksum failed or missing: %s", line)
            return None
        if not line.startswith("$GPGGA"):
            return None
        fields = line.split(",")
        if len(fields) < 15:
            logging.warning("Incomplete GPGGA sentence: %s", line)
            return None
        try:
            fix_quality = int(fields[6])
        except ValueError:
            logging.warning("Invalid fix quality in GPGGA: %s", line)
            return None
        if fix_quality == 0:
            logging.warning("No GPS fix (fix_quality=0).")
            return None
        lat = self._nmea_to_decimal(fields[2], fields[3])
        lon = self._nmea_to_decimal(fields[4], fields[5])
        if lat is None or lon is None:
            logging.warning("Invalid lat/lon in GPGGA: %s", line)
            return None
        try:
            alt = float(fields[9]) if fields[9] else None
        except ValueError:
            alt = None
        try:
            sats = int(fields[7]) if fields[7] else None
        except ValueError:
            sats = None
        return GPS_readings(
            latitude=lat,
            longitude=lon,
            altitude=alt,
            satellites=sats,
        )

def main() -> None:
    gps = GPSReader(port="/dev/serial0", baudrate=9600, timeout=1.0)
    running = True

    def signal_handler(signum, frame):
        nonlocal running
        logging.info("Signal %d received, shutting down...", signum)
        running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not gps.connect():
        sys.exit(1)

    try:
        while running:
            readings = gps.get_readings()
            if readings is not None:
                logging.info(
                    "Lat: %.6f, Lon: %.6f, Alt: %s, Sats: %s",
                    readings.latitude,
                    readings.longitude,
                    readings.altitude,
                    readings.satellites,
                )
    except Exception as e:
        logging.error("Unexpected error in main loop: %s", e)
    finally:
        gps.disconnect()

