import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'health_readings_log.txt'
LOOP_DELAY = 0.1

running = True
serial_connection = None


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global serial_connection
    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
            print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")


def main():
    global serial_connection, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(
            SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT
        )
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

    try:
        while running:
            try:
                raw_data = serial_connection.readline()
                if not raw_data:
                    continue

                decoded_data = raw_data.decode('ascii', errors='replace').strip()
                if not decoded_data:
                    continue

                parts = decoded_data.split(',')
                if len(parts) != 2:
                    print(f"Invalid data format: {decoded_data}")
                    continue

                heart_rate, spo2 = parts
                timestamp = datetime.now().isoformat(timespec='seconds')
                log_entry = f"{timestamp} - Heart Rate: {heart_rate}, SpO2: {spo2}\n"

                print(log_entry, end='')

                try:
                    with open(LOG_FILE, 'a') as logfile:
                        logfile.write(log_entry)
                except IOError as e:
                    print(f"Error writing to log file: {e}")

            except ValueError as e:
                print(f"Error parsing data: {e}")
            except IOError as e:
                print(f"Error reading from serial port: {e}")
                break

            time.sleep(LOOP_DELAY)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

