import logging
import signal
import sys
import time

try:
    import serial
    from serial import SerialException
except ImportError:
    logging.error("pyserial is required. Install with: pip install pyserial")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)


class SimpleGPS:
    """
    A robust GPS module reader for Raspberry Pi using pyserial.
    Supports $GPGGA and $GNGGA sentences and handles malformed data gracefully.
    """

    def __init__(self, port="/dev/serial0", baudrate=9600, timeout=1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self._uart = None
        self._running = True

    def connect(self):
        """
        Opens the UART port. Returns True on success, False on failure.
        """
        try:
            self._uart = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logging.info(
                "Connected to GPS on %s at %d baud (8N1).",
                self.port,
                self.baudrate,
            )
            return True
        except SerialException as e:
            logging.error("Failed to connect to GPS on %s: %s", self.port, e)
            self._uart = None
            return False
        except OSError as e:
            logging.error("OS error opening %s: %s", self.port, e)
            self._uart = None
            return False

    def read_data(self):
        """
        Reads a line from the UART. Returns the stripped string, or None if
        no data is available, the connection is closed, or an error occurs.
        """
        if self._uart is None:
            logging.error("UART is not initialized. Call connect() first.")
            return None

        try:
            if not self._uart.is_open:
                logging.error("UART connection is closed.")
                return None

            raw = self._uart.readline()
            if not raw:
                return None

            return raw.decode("utf-8", errors="ignore").strip()
        except SerialException as e:
            logging.error("Serial read error: %s", e)
            return None
        except OSError as e:
            logging.error("OS read error: %s", e)
            return None

    @staticmethod
    def parse_gga(line):
        """
        Parses a $GPGGA or $GNGGA sentence.
        Returns a dict with utc_time, latitude, longitude, fix_quality,
        and num_satellites, or None if the sentence is malformed.
        """
        if not line:
            return None

        if not (line.startswith("$GPGGA") or line.startswith("$GNGGA")):
            return None

        try:
            parts = line.split(",")
            if len(parts) < 15:
                logging.warning("GGA sentence too short: %s", line)
                return None

            utc_time = parts[1] if parts[1] else None
            latitude = parts[2] if parts[2] else None
            latitude_dir = parts[3] if parts[3] else None
            longitude = parts[4] if parts[4] else None
            longitude_dir = parts[5] if parts[5] else None
            fix_quality = parts[6] if parts[6] else None
            num_satellites = parts[7] if parts[7] else None

            if latitude and latitude_dir:
                latitude = float(latitude)
                if latitude_dir.upper() == "S":
                    latitude = -latitude

            if longitude and longitude_dir:
                longitude = float(longitude)
                if longitude_dir.upper() == "W":
                    longitude = -longitude

            if fix_quality:
                fix_quality = int(fix_quality)
            if num_satellites:
                num_satellites = int(num_satellites)

            return {
                "utc_time": utc_time,
                "latitude": latitude,
                "longitude": longitude,
                "fix_quality": fix_quality,
                "num_satellites": num_satellites,
            }
        except (ValueError, IndexError) as e:
            logging.error("Error parsing GGA sentence '%s': %s", line, e)
            return None

    def close(self):
        """
        Closes the UART connection if open. Safe to call multiple times.
        """
        if self._uart is not None:
            try:
                if self._uart.is_open:
                    self._uart.close()
                    logging.info("UART connection closed.")
            except Exception as e:
                logging.error("Error closing UART: %s", e)
            finally:
                self._uart = None

    def stop(self):
        """Signal the main loop to stop."""
        self._running = False


def main():
    gps = SimpleGPS(port="/dev/serial0", baudrate=9600, timeout=1.0)

    def signal_handler(signum, frame):
        logging.info("Signal %d received, shutting down...", signum)
        gps.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not gps.connect():
        logging.error("Could not connect to GPS. Exiting.")
        sys.exit(1)

    try:
        while gps._running:
            line = gps.read_data()
            if line:
                parsed = gps.parse_gga(line)
                if parsed:
                    logging.info("GPS Data: %s", parsed)
            time.sleep(0.1)
    except Exception as e:
        logging.error("Unexpected error in main loop: %s", e)
    finally:
        gps.close()
        logging.info("Program terminated.")


if __name__ == "__main__":
    main()

