#!/usr/bin/env python3
"""Raspberry Pi UART web service with SCPI *IDN? query.

Listens on 0.0.0.0:5000.
  GET /version  -> queries the instrument via UART and returns its identity.
  GET /data     -> returns all stored items as JSON.
  GET /data/<id>-> returns a single item or 404.
  POST /data    -> creates a new item with auto-incremented id.
"""

import json
import signal
import sys
import threading
from typing import Any, Dict, List, Optional

import serial
from flask import Flask, Response, request

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
UART_PORT = "/dev/ttyUSB0"
UART_BAUDRATE = 9600
UART_TIMEOUT = 1          # seconds
WEB_HOST = "0.0.0.0"
WEB_PORT = 5000

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
app = Flask(__name__)

# Thread-safe shared state
_data_lock = threading.Lock()
_data_store: List[Dict[str, Any]] = [
    {"id": 1, "name": "Task 1", "done": False},
    {"id": 2, "name": "Task 2", "done": False},
]
_next_id = 3

_uart_lock = threading.Lock()
_uart: Optional[serial.Serial] = None


def _close_uart() -> None:
    """Idempotently close the UART port."""
    global _uart
    with _uart_lock:
        if _uart is not None:
            try:
                if _uart.is_open:
                    _uart.reset_input_buffer()
                    _uart.reset_output_buffer()
                    _uart.close()
            except Exception as exc:  # noqa: BLE001
                print(f"[uart] close error: {exc}", file=sys.stderr)
            finally:
                _uart = None


def _open_uart() -> Optional[serial.Serial]:
    """Open the UART port; return the Serial object or None on failure."""
    global _uart
    with _uart_lock:
        if _uart is not None and _uart.is_open:
            return _uart
        try:
            _uart = serial.Serial(
                port=UART_PORT,
                baudrate=UART_BAUDRATE,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=UART_TIMEOUT,
            )
            return _uart
        except serial.SerialException as exc:
            print(f"[uart] open failed: {exc}", file=sys.stderr)
            _uart = None
            return None
        except Exception as exc:  # noqa: BLE001
            print(f"[uart] unexpected open error: {exc}", file=sys.stderr)
            _uart = None
            return None


def _query_instrument(command: str) -> Optional[str]:
    """Send a SCPI query to the instrument and return the stripped response line.

    Returns None on timeout, port error, or read failure.
    """
    port = _open_uart()
    if port is None:
        return None
    try:
        port.reset_input_buffer()
        port.reset_output_buffer()
        payload = command.encode("ascii")
        written = port.write(payload)
        if written != len(payload):
