import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'access_log.txt'

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_access_event(tag_id):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} – RFID Tag: {tag_id}\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as logfile:
            logfile.write(log_entry)
            logfile.flush()
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)
    print(f'Access granted for RFID Tag: {tag_id}')

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = None
    try:
        try:
            serial_connection = serial.Serial(
                SERIAL_PORT,
                BAUD_RATE,
                timeout=TIMEOUT
            )
        except serial.SerialException as e:
            print(f'Error opening serial port {SERIAL_PORT}: {e}', file=sys.stderr)
            sys.exit(1)

        print(f'Listening for RFID tags on {SERIAL_PORT} @ {BAUD_RATE} baud...')

        while running:
            try:
                raw_data = serial_connection.readline()
                if not raw_data:
                    continue

                tag_id = raw_data.decode('ascii', errors='replace').strip()
                if tag_id:
                    log_access_event(tag_id)

            except serial.SerialException as e:
                print(f'Serial communication error: {e}', file=sys.stderr)
                time.sleep(1)
            except UnicodeDecodeError as e:
                print(f'Decoding error: {e}', file=sys.stderr)
            except Exception as e:
                print(f'Unexpected error processing data: {e}', file=sys.stderr)

    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print('Serial port closed.')

if __name__ == '__main__':
    main()

