    if serial_connection is None or not serial_connection.is_open:
        return None
    try:
        serial_connection.reset_input_buffer()
        serial_connection.write(command.encode('ascii'))
        time.sleep(RESPONSE_DELAY)
        response = serial_connection.read(serial_connection.in_waiting or 1024)
        if not response:
            return None
        return response.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None


@app.route('/')
def hello_world():
    return 'Hello, World!'


@app.route('/getdata')
def get_data():
    return jsonify(items)


@app.route('/getset/<int:item_id>')
def get_item(item_id):
    item = next((i for i in items if i['id'] == item_id), None)
    if item:
        return jsonify(item)
    return jsonify({'error': 'Item not found'}), 404


@app.route('/getpost/<int:item_id>/<name>')
def get_post_item(item_id, name):
