                new_id = (items[-1]['id'] if items else 0) + 1
                new_item = {
                    'id': new_id,
                    'name': data['name'],
                    'done': bool(data.get('done', False)),
                }
                items.append(new_item)
                return jsonify(items), 201
            except (TypeError, ValueError) as e:
                return jsonify({'error': f'Invalid JSON: {e}'}), 400
        elif 'application/x-www-form-urlencoded' in content_type or 'multipart/form-data' in content_type:
            name = request.form.get('name', '')
            done_str = request.form.get('done', 'false').lower()
            done = done_str in ('true', '1', 'yes')
            new_id = (items[-1]['id'] if items else 0) + 1
            new_item = {'id': new_id, 'name': name, 'done': done}
            items.append(new_item)
            return jsonify(items), 201
        else:
            return jsonify({'error': 'Unsupported Content-Type'}), 415
    else:
        return jsonify(items)


@app.route('/version')
def get_version():
    response = get_scpi_response('*IDN?\n')
    if response:
        html_response = response.replace('\n', '<br>')
        return Response(html_response, mimetype='text/html')
