import bluetooth
import time
import sys

BLUETOOTH_DEVICE_ADDRESS = "/dev/rfcomm4"
BLUETOOTH_BAUDRATE = 38400
COMMAND_PREFIX = "X"
DELAY_SECONDS = 0.1


def create_command_input(prefix: str) -> str:
    """Prompts the user for input and returns the prefixed command string."""
    try:
        user_input = input("Enter command: ")
    except EOFError:
        print("\nEOF received, exiting.")
        sys.exit(0)
    return prefix + user_input


def send_command(connection, command: str) -> None:
    """Sends a command over the Bluetooth connection with a delay."""
    try:
        connection.send(command + "\n")
        time.sleep(DELAY_SECONDS)
    except bluetooth.BluetoothError as e:
        raise RuntimeError(f"Bluetooth communication error: {e}") from e
    except OSError as e:
        raise RuntimeError(f"OS error during send: {e}") from e


def main() -> None:
    """Main function to handle Bluetooth communication and command sending."""
    connection = None
    try:
        print(f"Connecting to {BLUETOOTH_DEVICE_ADDRESS} at {BLUETOOTH_BAUDRATE} baud...")
        connection = bluetooth.BluetoothSocket(bluetooth.RFCOMM)
        connection.connect((BLUETOOTH_DEVICE_ADDRESS, BLUETOOTH_BAUDRATE))
        print("Connected. Enter 'exit' to quit.")

        while True:
            command = create_command_input(COMMAND_PREFIX)
            if command.lower() == "Xexit":
                break
            send_command(connection, command)

    except bluetooth.BluetoothError as e:
        raise RuntimeError(f"Bluetooth connection error: {e}") from e
    except KeyboardInterrupt:
